    @Scheduled(fixedRate = 60000) // 每分钟检测一次
    public void detectDeadlock() {
        // 1. 查询所有锁
        Set<String> locks = redisTemplate.keys("*:lock:*");
        
        // 2. 检查锁的持有时间
        for (String lockKey : locks) {
            Long ttl = redisTemplate.getExpire(lockKey, TimeUnit.SECONDS);
            
            if (ttl == null || ttl < 0) {
                // 锁没有过期时间，可能是死锁
