    public void detectResourceLeak() {
        // 1. 查询长时间RUNNING的任务
        List<TaskInstance> longRunningTasks = taskInstanceMapper
            .selectLongRunningTasks(3600); // 超过1小时
        
        for (TaskInstance task : longRunningTasks) {
