// ❌ 不好：锁持有时间长
public void scheduleTask(TaskInstance task) {
    lock.lock();
    try {
        // 查询数据库（慢）
        ResourceNode node = selectNode(task);
        
        // 预留资源（慢）
        reserveResource(task, node);
        
        // 提交执行器（慢）
        submitToExecutor(task, node);
        
    } finally {
        lock.unlock();
    }
}

// ✅ 好：只在关键操作时持有锁
public void scheduleTask(TaskInstance task) {
    // 1. 查询数据（不需要锁）
    ResourceNode node = selectNode(task);
    
    // 2. 预留资源（需要锁）
    lock.lock();
    try {
        reserveResource(task, node);
    } finally {
        lock.unlock();
    }
    
    // 3. 提交执行器（不需要锁）
    submitToExecutor(task, node);
}
```

