public void handlePartialFailure(Long workflowInstanceId) {
    // 查询失败的任务
    List<WorkflowTaskInstance> failedTasks = 
        workflowTaskInstanceMapper.selectByWorkflowInstanceAndStatus(
            workflowInstanceId, TaskStatus.FAILED
