 */
public void recursiveMethod(Long taskId, int level) {
    RLock lock = redisson.getLock("task:lock:" + taskId);
    
    try {
        lock.lock();
        
        // 业务逻辑
        if (level > 0) {
            recursiveMethod(taskId, level - 1); // 可重入
