public class ConfigService {
    
    @Autowired
    private RedissonClient redisson;
    
    private RReadWriteLock rwLock = redisson.getReadWriteLock("config:lock");
    
    /**
     * 读配置（允许多个线程同时读）
     */
    public Config getConfig() {
