@Mapper
public interface ResourceNodeMapper extends BaseMapper<ResourceNode> {

    /**
     * 查询心跳过期的 ONLINE 节点（疑似宕机节点）。
     * heartbeatBefore：最后心跳时间早于此时刻的节点视为疑似宕机（典型值 = NOW() - 30s）。
     * NodeHeartbeatWatchdog 用此结果触发节点标记 OFFLINE 和任务恢复流程。
     */
    @org.apache.ibatis.annotations.Select(
            "SELECT * FROM resource_node " +
            "WHERE status = 'ONLINE' " +
            "AND last_heartbeat_time IS NOT NULL " +
            "AND last_heartbeat_time < #{heartbeatBefore} " +
            "LIMIT #{limit}")
    java.util.List<ResourceNode> selectDeadNodes(
            @org.apache.ibatis.annotations.Param("heartbeatBefore") java.time.LocalDateTime heartbeatBefore,
            @org.apache.ibatis.annotations.Param("limit") int limit);

    /**
     * 更新节点状态为 OFFLINE。
     */
    @org.apache.ibatis.annotations.Update(
            "UPDATE resource_node SET status = 'OFFLINE', updated_at = NOW() " +
            "WHERE id = #{nodeId} AND status = 'ONLINE'")
    int markOffline(@org.apache.ibatis.annotations.Param("nodeId") Long nodeId);
}

@Mapper
public interface ResourceQuotaMapper extends BaseMapper<ResourceQuota> {

    @Update("""
            UPDATE resource_quota
            SET used_cpu = used_cpu + #{cpu},
                used_memory_mb = used_memory_mb + #{mem},
                used_gpu = used_gpu + #{gpu},
                running_tasks = running_tasks + #{runningDelta},
                version = version + 1,
                updated_at = CURRENT_TIMESTAMP
            WHERE tenant_id = #{tenantId}
              AND used_cpu + #{cpu} <= max_cpu
              AND used_memory_mb + #{mem} <= max_memory_mb
              AND used_gpu + #{gpu} <= max_gpu
              AND running_tasks + #{runningDelta} <= max_running_tasks
            """)
    int consumeIfWithinQuota(
            @Param("tenantId") long tenantId,
            @Param("cpu") int cpu,
            @Param("mem") int mem,
            @Param("gpu") int gpu,
            @Param("runningDelta") int runningDelta);

    @Update("""
            UPDATE resource_quota
            SET used_cpu = used_cpu - #{cpu},
                used_memory_mb = used_memory_mb - #{mem},
                used_gpu = used_gpu - #{gpu},
                running_tasks = running_tasks - #{runningDelta},
                version = version + 1,
                updated_at = CURRENT_TIMESTAMP
            WHERE tenant_id = #{tenantId}
              AND used_cpu >= #{cpu}
              AND used_memory_mb >= #{mem}
              AND used_gpu >= #{gpu}
              AND running_tasks >= #{runningDelta}
            """)
    int releaseUsed(
            @Param("tenantId") long tenantId,
            @Param("cpu") int cpu,
            @Param("mem") int mem,
            @Param("gpu") int gpu,
            @Param("runningDelta") int runningDelta);
}

@Mapper
public interface ResourceSlotMapper extends BaseMapper<ResourceSlot> {

    /**
     * 单语句插入三行槽位（若 uk 已存在则忽略），减少并发下「逐行 select + insert」的竞态窗口。
     */
    @Insert("""
            INSERT IGNORE INTO resource_slot (node_id, resource_type, total, available, reserved_qty, version)
            VALUES (#{nodeId}, 'CPU', #{totalCpu}, #{availCpu}, 0, 0),
                   (#{nodeId}, 'MEMORY', #{totalMem}, #{availMem}, 0, 0),
                   (#{nodeId}, 'GPU', #{totalGpu}, #{availGpu}, 0, 0)
            """)
    int insertSlotsIfAbsent(
            @Param("nodeId") long nodeId,
            @Param("totalCpu") int totalCpu,
            @Param("availCpu") int availCpu,
            @Param("totalMem") int totalMem,
            @Param("availMem") int availMem,
            @Param("totalGpu") int totalGpu,
            @Param("availGpu") int availGpu);

    /**
     * 条件扣减：仅当 available &gt;= amount 时生效，防止超分与负数。
     */
    @Update("""
            UPDATE resource_slot
            SET available = available - #{amount},
                reserved_qty = reserved_qty + #{amount},
                version = version + 1,
                updated_at = CURRENT_TIMESTAMP(3)
            WHERE node_id = #{nodeId}
              AND resource_type = #{resourceType}
              AND available >= #{amount}
            """)
    int decreaseIfEnough(
            @Param("nodeId") Long nodeId,
            @Param("resourceType") String resourceType,
            @Param("amount") int amount);

    /**
     * 释放回补：available 不超过 total；reserved_qty 不低于 0。
     */
    @Update("""
            UPDATE resource_slot
            SET available = LEAST(total, available + #{amount}),
                reserved_qty = GREATEST(0, reserved_qty - #{amount}),
                version = version + 1,
                updated_at = CURRENT_TIMESTAMP(3)
            WHERE node_id = #{nodeId}
              AND resource_type = #{resourceType}
            """)
    int increaseAvailable(
            @Param("nodeId") Long nodeId,
            @Param("resourceType") String resourceType,
            @Param("amount") int amount);
}

@Mapper
public interface ResourceUsageMapper extends BaseMapper<ResourceUsage> {

    /**
     * 查询孤儿 RESERVED 记录：resource_usage 状态为 RESERVED，
     * 但对应的 task_instance 不存在或不处于 RUNNING 状态。
     * 触发场景：reserve() 事务提交后 JVM crash，updateStatusWithVersion() 未执行，
     * 导致任务卡死 PENDING 且资源永久占用。
     */
    @org.apache.ibatis.annotations.Select(
            "SELECT ru.* FROM resource_usage ru " +
            "LEFT JOIN task_instance ti ON ti.id = ru.task_instance_id " +
            "WHERE ru.status = 'RESERVED' " +
            "AND (ti.id IS NULL OR ti.status != 'RUNNING') " +
            "LIMIT #{limit}")
    java.util.List<ResourceUsage> selectOrphanedReserved(@org.apache.ibatis.annotations.Param("limit") int limit);
}

@Mapper
public interface TaskInstanceMapper extends BaseMapper<TaskInstance> {

    // 批量插入任务实例
    @Insert({
            "<script>",
            "INSERT INTO task_instance (",
            "id, task_id, tenant_id, workflow_instance_id, instance_code, trigger_type, submit_user_id, status, priority,",
            "resource_requirement, executor_config, parameters, submit_time, resource_node_id, scheduled_time,",
            "start_time, end_time, duration_ms, exit_code, error_message, retry_count, version, created_at, updated_at",
            ") VALUES ",
            "<foreach collection='list' item='item' separator=','>",
            "(",
            "#{item.id}, #{item.taskId}, #{item.tenantId}, #{item.workflowInstanceId}, #{item.instanceCode}, #{item.triggerType},",
            "#{item.submitUserId}, #{item.status}, #{item.priority}, #{item.resourceRequirement}, #{item.executorConfig},",
            "#{item.parameters}, #{item.submitTime}, #{item.resourceNodeId}, #{item.scheduledTime}, #{item.startTime},",
            "#{item.endTime}, #{item.durationMs}, #{item.exitCode}, #{item.errorMessage}, #{item.retryCount},",
            "#{item.version}, #{item.createdAt}, #{item.updatedAt}",
            ")",
            "</foreach>",
            "</script>"
    })
    int insertBatch(@Param("list") List<TaskInstance> list);

    // 查询待调度的任务实例，按照提交时间排序，限制返回数量
    @Select({
            "SELECT ti.* ",
            "FROM task_instance ti ",
            "WHERE ti.status = 'PENDING' ",
            "  AND EXISTS (",
            "    SELECT 1 FROM task t ",
            "    WHERE t.id = ti.task_id ",
            "      AND t.status = 1 ",
            "      AND t.deleted = 0",
            "  ) ",
            "ORDER BY ti.submit_time ASC ",
            "LIMIT #{limit}"
    })
    List<TaskInstance> selectPendingTasks(@Param("limit") int limit);

    // 乐观锁更新任务实例状态，确保状态转换的原子性和一致性
    @Update({
            "UPDATE task_instance ",
            "SET status = #{toStatus}, ",
            "    resource_node_id = #{resourceNodeId}, ",
            "    start_time = #{startTime}, ",
            "    scheduled_time = #{scheduledTime}, ",
            "    version = version + 1, ",
            "    updated_at = NOW() ",
            "WHERE id = #{id} ",
            "  AND status = #{fromStatus} ",
            "  AND version = #{version}"
    })
    int updateStatusWithVersion(@Param("id") Long id,
                                @Param("fromStatus") String fromStatus,
                                @Param("toStatus") String toStatus,
                                @Param("version") Integer version,
                                @Param("resourceNodeId") Long resourceNodeId,
                                @Param("startTime") LocalDateTime startTime,
                                @Param("scheduledTime") LocalDateTime scheduledTime);

    // 查询待调度的任务实例，计算综合优先级（基于原始优先级和等待时间），按照综合优先级排序，限制返回数量
    @Select("SELECT ti.*, " +
            "       (#{priorityWeight} * (ti.priority / 10.0) + " +
            "        #{agingWeight} * (TIMESTAMPDIFF(SECOND, ti.submit_time, NOW()) / 3600.0)) AS computed_priority " +
            "FROM task_instance ti " +
            "WHERE ti.status = 'PENDING' " +
            "  AND EXISTS (" +
            "    SELECT 1 FROM task t " +
            "    WHERE t.id = ti.task_id " +
            "      AND t.status = 1 " +
            "      AND t.deleted = 0" +
            "  ) " +
            "ORDER BY computed_priority DESC, ti.submit_time " +
            "LIMIT #{limit}")
    List<TaskWithPriority> selectPendingTasksWithPriority(@Param("limit") int limit,
                                                          @Param("priorityWeight") double priorityWeight,
                                                          @Param("agingWeight") double agingWeight);

    /**
     * 该方法用于仅查询待调度任务的 ID 列表，按照与 {@link #selectPendingTasksWithPriority} 相同的优先级计算和排序逻辑。
     * 与 {@link #selectPendingTasksWithPriority} 相同的筛选与排序，仅返回 id 列表，便于稳定组装 {@link TaskWithPriority}。
     */
    @Select("SELECT ti.id FROM task_instance ti " +
            "WHERE ti.status = 'PENDING' " +
            "  AND EXISTS (" +
            "    SELECT 1 FROM task t " +
            "    WHERE t.id = ti.task_id " +
            "      AND t.status = 1 " +
            "      AND t.deleted = 0" +
            "  ) " +
            "ORDER BY (#{priorityWeight} * (ti.priority / 10.0) + " +
            "          #{agingWeight} * (TIMESTAMPDIFF(SECOND, ti.submit_time, NOW()) / 3600.0)) DESC, ti.submit_time " +
            "LIMIT #{limit}")
    List<Long> selectPendingTaskIdsByPriority(@Param("limit") int limit,
                                              @Param("priorityWeight") double priorityWeight,
                                              @Param("agingWeight") double agingWeight);

    /**
     * 查询已超时的 RUNNING 任务（timeout_seconds 来自 task 定义）。
     */
    @Select({
            "SELECT ti.* FROM task_instance ti ",
            "INNER JOIN task t ON t.id = ti.task_id ",
            "WHERE ti.status = 'RUNNING' ",
            "  AND ti.start_time IS NOT NULL ",
            "  AND t.timeout_seconds IS NOT NULL ",
            "  AND t.timeout_seconds > 0 ",
            "  AND TIMESTAMPDIFF(SECOND, ti.start_time, NOW()) > t.timeout_seconds ",
            "ORDER BY ti.start_time ASC ",
            "LIMIT #{limit}"
    })
    List<TaskInstance> selectTimedOutRunningTasks(@Param("limit") int limit);

    /**
     * 更新执行器心跳时间（仅更新 RUNNING 状态的任务，防止误更新已终态任务）。
     *
     * @param taskInstanceId 任务实例 ID
     * @return 更新行数（0 表示任务已不在 RUNNING 状态，执行器应停止）
     */
    @Update("UPDATE task_instance SET last_heartbeat_at = NOW(), updated_at = NOW() " +
            "WHERE id = #{taskInstanceId} AND status = 'RUNNING'")
    int updateHeartbeat(@Param("taskInstanceId") Long taskInstanceId);

    /**
     * 查询心跳超时的 RUNNING 任务（"僵尸任务"）。
     * 触发场景：执行器 JVM crash / 节点宕机，导致心跳停止但 status 仍为 RUNNING。
     * heartbeatBefore：上次心跳时间早于此时刻的任务视为僵尸（典型值 = NOW() - 30s）。
     */
    @Select("SELECT ti.* FROM task_instance ti " +
            "WHERE ti.status = 'RUNNING' " +
            "AND ti.last_heartbeat_at IS NOT NULL " +
            "AND ti.last_heartbeat_at < #{heartbeatBefore} " +
            "ORDER BY ti.last_heartbeat_at ASC " +
            "LIMIT #{limit}")
    List<TaskInstance> selectZombieRunningTasks(
            @Param("heartbeatBefore") LocalDateTime heartbeatBefore,
            @Param("limit") int limit);

    /**
     * 查询指定节点上所有 RUNNING 状态的任务实例（节点宕机恢复用）。
     */
    @Select("SELECT * FROM task_instance WHERE status = 'RUNNING' AND resource_node_id = #{nodeId}")
    List<TaskInstance> selectRunningByNodeId(@Param("nodeId") Long nodeId);
}

