public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private static final String BEARER_PREFIX = "Bearer ";

    private final JwtTokenProvider jwtTokenProvider;
    private final JsonMapper jsonMapper;

    public JwtAuthenticationFilter(JwtTokenProvider jwtTokenProvider, JsonMapper jsonMapper) {
        this.jwtTokenProvider = jwtTokenProvider;
        this.jsonMapper = jsonMapper;
    }

    @Override
    protected void doFilterInternal(
            HttpServletRequest request,
            HttpServletResponse response,
            FilterChain filterChain) throws ServletException, IOException {

        String header = request.getHeader("Authorization");
        if (header == null || !header.regionMatches(true, 0, BEARER_PREFIX, 0, BEARER_PREFIX.length())) {
            filterChain.doFilter(request, response);
            return;
        }

        String token = header.substring(BEARER_PREFIX.length()).trim();
        if (token.isEmpty()) {
            writeUnauthorized(response, "令牌不能为空");
            return;
        }

        try {
            Claims claims = jwtTokenProvider.parseClaims(token);
            Long userId = Long.parseLong(claims.getSubject());
            String username = claims.get(JwtTokenProvider.CLAIM_USERNAME, String.class);
            if (username == null) {
                username = "";
            }
            Object tenantIdObj = claims.get(JwtTokenProvider.CLAIM_TENANT_ID);
            Long tenantId = tenantIdObj == null ? null : ((Number) tenantIdObj).longValue();
            String tenantCode = claims.get(JwtTokenProvider.CLAIM_TENANT_CODE, String.class);
            String tenantRole = claims.get(JwtTokenProvider.CLAIM_TENANT_ROLE, String.class);
            JwtUserPrincipal principal = tenantId == null
                    ? new JwtUserPrincipal(userId, username)
                    : new JwtUserPrincipal(userId, username, tenantId, tenantCode, tenantRole);
            UsernamePasswordAuthenticationToken authentication =
                    new UsernamePasswordAuthenticationToken(principal, null, principal.getAuthorities());
            authentication.setDetails(new org.springframework.security.web.authentication.WebAuthenticationDetailsSource().buildDetails(request));
            SecurityContextHolder.getContext().setAuthentication(authentication);
        } catch (ExpiredJwtException e) {
            SecurityContextHolder.clearContext();
            writeUnauthorized(response, "登录已过期，请重新登录");
            return;
        } catch (JwtException | IllegalArgumentException e) {
            SecurityContextHolder.clearContext();
            writeUnauthorized(response, "令牌无效");
            return;
        }

        filterChain.doFilter(request, response);
    }

    private void writeUnauthorized(HttpServletResponse response, String message) throws IOException {
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        jsonMapper.writeValue(response.getWriter(), Result.failure(ResultCode.UNAUTHORIZED, message));
    }
}

@Component
public class JwtTokenProvider {

    public static final String CLAIM_TOKEN_TYPE = "token_type";
    public static final String TOKEN_TYPE_IDENTITY = "identity";
    public static final String TOKEN_TYPE_TENANT_ACCESS = "tenant_access";
    public static final String CLAIM_USERNAME = "username";
    public static final String CLAIM_TENANT_ID = "tenant_id";
    public static final String CLAIM_TENANT_CODE = "tenant_code";
    public static final String CLAIM_TENANT_ROLE = "tenant_role";

    private final SecretKey key;
    private final long expirationMs;

    public JwtTokenProvider(
            @Value("${jwt.secret}") String secret,
            @Value("${jwt.expiration-ms}") long expirationMs) {
        byte[] keyBytes = secret.getBytes(StandardCharsets.UTF_8);
        if (keyBytes.length < 32) {
            throw new IllegalArgumentException("jwt.secret must be at least 32 bytes (UTF-8) for HS256");
        }
        this.key = Keys.hmacShaKeyFor(keyBytes);
        this.expirationMs = expirationMs;
    }

    /** 访问令牌有效期（秒），供登录接口返回给客户端。 */
    public long getExpiresInSeconds() {
        return expirationMs / 1000;
    }

    /** 登录后的身份令牌（不含租户上下文）。 */
    public String createAccessToken(Long userId, String username) {
        Instant now = Instant.now();
        return Jwts.builder()
                .subject(String.valueOf(userId))
                .claim(CLAIM_TOKEN_TYPE, TOKEN_TYPE_IDENTITY)
                .claim(CLAIM_USERNAME, username)
                .issuedAt(Date.from(now))
                .expiration(Date.from(now.plusMillis(expirationMs)))
                .signWith(key)
                .compact();
    }

    /**
     * 租户上下文访问令牌：业务接口推荐携带此令牌，便于网关与业务层识别当前租户与成员角色。
     */
    public String createTenantAccessToken(
            Long userId,
            String username,
            Long tenantId,
            String tenantCode,
            String tenantRole) {
        Instant now = Instant.now();
        return Jwts.builder()
                .subject(String.valueOf(userId))
                .claim(CLAIM_TOKEN_TYPE, TOKEN_TYPE_TENANT_ACCESS)
                .claim(CLAIM_USERNAME, username)
                .claim(CLAIM_TENANT_ID, tenantId)
                .claim(CLAIM_TENANT_CODE, tenantCode != null ? tenantCode : "")
                .claim(CLAIM_TENANT_ROLE, tenantRole != null ? tenantRole : "")
                .issuedAt(Date.from(now))
                .expiration(Date.from(now.plusMillis(expirationMs)))
                .signWith(key)
                .compact();
    }

    public Claims parseClaims(String token) {
        return Jwts.parser()
                .verifyWith(key)
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }
}

