@Value
@Builder
public class ExecutionResult {

    boolean success;

    int exitCode;

    String stdout;

    String stderr;

    String errorMessage;

    boolean timedOut;

    public static ExecutionResult success(int exitCode, String stdout, String stderr) {
        return ExecutionResult.builder()
                .success(exitCode == 0)
                .exitCode(exitCode)
                .stdout(stdout)
                .stderr(stderr)
                .build();
    }

    public static ExecutionResult failure(int exitCode, String stdout, String stderr, String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(exitCode)
                .stdout(stdout)
                .stderr(stderr)
                .errorMessage(errorMessage)
                .build();
    }

    public static ExecutionResult timedOut(String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(-1)
                .timedOut(true)
                .errorMessage(errorMessage)
                .build();
    }

    public static ExecutionResult configurationError(String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(-1)
                .errorMessage(errorMessage)
                .build();
    }
}

@Component
public class ExecutorConfigSupport {

    private final ObjectMapper objectMapper;

    public ExecutorConfigSupport(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public JsonNode parse(String executorConfigJson) {
        if (!StringUtils.hasText(executorConfigJson)) {
            return null;
        }
        try {
            return objectMapper.readTree(executorConfigJson);
        } catch (Exception e) {
            return null;
        }
    }

    public String readText(JsonNode root, String field) {
        if (root == null || !root.hasNonNull(field)) {
            return null;
        }
        return root.get(field).asText();
    }

    public List<String> readStringList(JsonNode root, String field) {
        if (root == null || !root.has(field) || !root.get(field).isArray()) {
            return List.of();
        }
        List<String> list = new ArrayList<>();
        for (JsonNode node : root.get(field)) {
            list.add(node.asText());
        }
        return list;
    }

    public Map<String, String> readStringMap(JsonNode root, String field) {
        if (root == null || !root.has(field) || !root.get(field).isObject()) {
            return Collections.emptyMap();
        }
        Map<String, String> map = new LinkedHashMap<>();
        JsonNode objectNode = root.get(field);
        objectNode.fieldNames().forEachRemaining(name -> map.put(name, objectNode.get(name).asText()));
        return map;
    }
}

@Slf4j
@Service
@ConditionalOnProperty(name = "task.executor.mode", havingValue = "in-process", matchIfMissing = true)
public class InProcessTaskDispatchService implements TaskDispatchService {

    private final TaskExecutorProperties properties;
    private final Executor taskExecutorThreadPool;
    private final LocalTaskRunner localTaskRunner;

    public InProcessTaskDispatchService(
            TaskExecutorProperties properties,
            @Qualifier("taskExecutorThreadPool") Executor taskExecutorThreadPool,
            LocalTaskRunner localTaskRunner) {
        this.properties = properties;
        this.taskExecutorThreadPool = taskExecutorThreadPool;
        this.localTaskRunner = localTaskRunner;
    }

    @Override
    public boolean dispatch(TaskInstance taskInstance, ResourceNode node) {
        if (!properties.isEnabled()) {
            log.warn("任务执行器未启用，拒绝提交 taskInstanceId={}", taskInstance.getId());
            return false;
        }
        Long taskInstanceId = taskInstance.getId();
        Long nodeId = node != null ? node.getId() : null;
        try {
            taskExecutorThreadPool.execute(() -> localTaskRunner.run(taskInstanceId, nodeId));
            log.info(
                    "任务已提交进程内执行器 taskInstanceId={} nodeId={}",
                    taskInstanceId,
                    nodeId);
            return true;
        } catch (RejectedExecutionException e) {
            log.warn("执行器线程池已满，拒绝任务 taskInstanceId={}", taskInstanceId, e);
            return false;
        }
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class LocalTaskRunner {

    /** 心跳上报间隔（秒）。NodeHeartbeatWatchdog 的超时阈值应为此值的 3 倍，留有余量。 */
    static final int HEARTBEAT_INTERVAL_SECONDS = 10;

    private final RunSpecBuilder runSpecBuilder;
    private final TaskTypeExecutorRegistry executorRegistry;
    private final TaskExecutionReporter executionReporter;
    private final TaskHeartbeatService heartbeatService;

    public void run(Long taskInstanceId, Long resourceNodeId) {
        log.info("开始执行任务实例 taskInstanceId={} nodeId={}", taskInstanceId, resourceNodeId);

        AtomicBoolean externallyTerminated = new AtomicBoolean(false);
        ScheduledExecutorService heartbeatScheduler = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "heartbeat-" + taskInstanceId);
            t.setDaemon(true);
            return t;
        });

        // 立即发送第一次心跳，此后每 HEARTBEAT_INTERVAL_SECONDS 秒一次
        ScheduledFuture<?> heartbeatFuture = heartbeatScheduler.scheduleAtFixedRate(() -> {
            boolean alive = heartbeatService.beat(taskInstanceId);
            if (!alive) {
                // 任务已被外部标记为终态（宕机恢复路径强制 FAILED），协作式通知执行线程停止
                externallyTerminated.set(true);
            }
        }, 0, HEARTBEAT_INTERVAL_SECONDS, TimeUnit.SECONDS);

        try {
            RunSpec runSpec = runSpecBuilder.build(taskInstanceId, resourceNodeId);
            TaskTypeExecutor executor = executorRegistry.resolve(runSpec.getTaskType()).orElse(null);
            if (executor == null) {
                executionReporter.reportConfigurationError(
                        taskInstanceId,
                        "不支持的任务类型: " + runSpec.getTaskType());
                return;
            }

            ExecutionResult result = executor.execute(runSpec);

            // 执行完成后检查任务是否已被外部终止
            // 若是，不上报结果（外部已写 FAILED，不能再改回 SUCCESS）
            if (externallyTerminated.get()) {
                log.warn("任务已被外部终止（宕机恢复），忽略本地执行结果 taskInstanceId={}", taskInstanceId);
                return;
            }

            executionReporter.report(result, taskInstanceId);
        } catch (Exception e) {
            if (externallyTerminated.get()) {
                log.warn("任务已被外部终止，忽略本地异常 taskInstanceId={}", taskInstanceId, e);
                return;
            }
            log.error("任务执行异常 taskInstanceId={}", taskInstanceId, e);
            executionReporter.reportFailure(taskInstanceId, -1, e.getMessage());
        } finally {
            heartbeatFuture.cancel(false);
            heartbeatScheduler.shutdownNow();
            log.debug("心跳调度已停止 taskInstanceId={}", taskInstanceId);
        }
    }
}

public final class ParameterTemplateResolver {

    private static final Pattern PLACEHOLDER = Pattern.compile("\\$\\{([a-zA-Z0-9_.-]+)}");

    private ParameterTemplateResolver() {
    }

    public static String resolve(String template, Map<String, Object> parameters) {
        if (!StringUtils.hasText(template)) {
            return template;
        }
        if (parameters == null || parameters.isEmpty()) {
            return template;
        }
        Matcher matcher = PLACEHOLDER.matcher(template);
        StringBuilder sb = new StringBuilder();
        while (matcher.find()) {
            String key = matcher.group(1);
            Object value = parameters.get(key);
            String replacement = value == null ? matcher.group(0) : String.valueOf(value);
            matcher.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        return sb.toString();
    }
}

@Slf4j
@Service
@RequiredArgsConstructor
@ConditionalOnProperty(name = "task.executor.mode", havingValue = "remote")
public class RemoteTaskDispatchService implements TaskDispatchService {

    private final TaskExecutorProperties properties;
    private final RunSpecBuilder runSpecBuilder;
    private final WorkerRunRequestFactory workerRunRequestFactory;
    private final WorkerHttpClient workerHttpClient;

    @Override
    public boolean dispatch(TaskInstance taskInstance, ResourceNode node) {
        if (!properties.isEnabled()) {
            log.warn("任务执行器未启用，拒绝提交 taskInstanceId={}", taskInstance.getId());
            return false;
        }
        if (node == null) {
            log.warn("远程执行缺少资源节点 taskInstanceId={}", taskInstance.getId());
            return false;
        }
        if (!StringUtils.hasText(properties.getSchedulerPublicBaseUrl())) {
            log.error("未配置 task.executor.scheduler-public-base-url，无法构造 Worker 回调地址");
            return false;
        }

        try {
            RunSpec runSpec = runSpecBuilder.build(taskInstance.getId(), node.getId());
            WorkerRunRequest request = workerRunRequestFactory.fromRunSpec(runSpec, node);
            boolean accepted = workerHttpClient.submitRun(node, request);
            if (accepted) {
                log.info(
                        "任务已下发远程 Worker taskInstanceId={} nodeId={} taskType={}",
                        taskInstance.getId(),
                        node.getId(),
                        runSpec.getTaskType());
            }
            return accepted;
        } catch (Exception e) {
            log.error(
                    "远程下发任务失败 taskInstanceId={} nodeId={}",
                    taskInstance.getId(),
                    node.getId(),
                    e);
            return false;
        }
    }
}

@Value
@Builder
public class RunSpec {

    Long taskInstanceId;

    Long taskId;

    String taskType;

    String command;

    /** 原始 executorConfig JSON，供 PYTHON/DOCKER 等插件解析 */
    String executorConfig;

    Path workDirectory;

    Map<String, Object> parameters;

    Integer timeoutSeconds;

    Long resourceNodeId;
}

@Slf4j
@Component
@RequiredArgsConstructor
public class RunSpecBuilder {

    private final TaskInstanceMapper taskInstanceMapper;
    private final TaskMapper taskMapper;
    private final TaskExecutorProperties properties;
    private final ObjectMapper objectMapper;

    public RunSpec build(Long taskInstanceId, Long resourceNodeId) {
        TaskInstance instance = taskInstanceMapper.selectById(taskInstanceId);
        if (instance == null) {
            throw new IllegalArgumentException("任务实例不存在: " + taskInstanceId);
        }

        Task task = instance.getTaskId() != null ? taskMapper.selectById(instance.getTaskId()) : null;
        String taskType = task != null && StringUtils.hasText(task.getTaskType())
                ? task.getTaskType().trim()
                : "SHELL";

        String executorConfigJson = StringUtils.hasText(instance.getExecutorConfig())
                ? instance.getExecutorConfig()
                : (task != null ? task.getExecutorConfig() : null);

        Map<String, Object> parameters = parseParameters(instance.getParameters());
        String command = extractCommand(executorConfigJson);
        if (StringUtils.hasText(command)) {
            command = ParameterTemplateResolver.resolve(command, parameters);
        }

        Integer timeoutSeconds = task != null ? task.getTimeoutSeconds() : null;
        if (timeoutSeconds == null || timeoutSeconds <= 0) {
            timeoutSeconds = extractTimeoutOverride(executorConfigJson);
        }

        Path workDir = Path.of(properties.getWorkDir(), String.valueOf(taskInstanceId));

        return RunSpec.builder()
                .taskInstanceId(taskInstanceId)
                .taskId(instance.getTaskId())
                .taskType(taskType)
                .command(command)
                .executorConfig(executorConfigJson)
                .workDirectory(workDir)
                .parameters(parameters)
                .timeoutSeconds(timeoutSeconds)
                .resourceNodeId(resourceNodeId)
                .build();
    }

    private Map<String, Object> parseParameters(String parametersJson) {
        if (!StringUtils.hasText(parametersJson)) {
            return Collections.emptyMap();
        }
        try {
            return objectMapper.readValue(parametersJson, new TypeReference<>() {});
        } catch (Exception e) {
            log.warn("任务参数 JSON 解析失败，按空参数处理 json={}", parametersJson, e);
            return Collections.emptyMap();
        }
    }

    private Integer extractTimeoutOverride(String executorConfigJson) {
        if (!StringUtils.hasText(executorConfigJson)) {
            return null;
        }
        try {
            JsonNode root = objectMapper.readTree(executorConfigJson);
            if (root.hasNonNull("timeoutSeconds")) {
                return root.get("timeoutSeconds").asInt();
            }
        } catch (Exception ignored) {
            // ignore
        }
        return null;
    }

    private String extractCommand(String executorConfigJson) {
        if (!StringUtils.hasText(executorConfigJson)) {
            return null;
        }
        try {
            JsonNode root = objectMapper.readTree(executorConfigJson);
            if (root.hasNonNull("command")) {
                return root.get("command").asText();
            }
            if (root.hasNonNull("script")) {
                return root.get("script").asText();
            }
            return null;
        } catch (Exception e) {
            log.warn("executorConfig 解析失败 json={}", executorConfigJson, e);
            return null;
        }
    }
}

