@Slf4j
@Service
@RequiredArgsConstructor
public class TaskExecutionCancelService {

    private final RunningTaskRegistry runningTaskRegistry;
    private final TaskExecutorProperties taskExecutorProperties;
    private final ResourceNodeMapper resourceNodeMapper;
    private final WorkerHttpClient workerHttpClient;

    public void cancelRunningTask(Long taskInstanceId, Long resourceNodeId) {
        if (taskInstanceId == null) {
            return;
        }
        if (runningTaskRegistry.cancel(taskInstanceId)) {
            log.info("已取消本机运行任务 taskInstanceId={}", taskInstanceId);
            return;
        }
        if (!"remote".equalsIgnoreCase(taskExecutorProperties.getMode())) {
            return;
        }
        if (resourceNodeId == null) {
            log.debug("远程取消跳过：无 resourceNodeId taskInstanceId={}", taskInstanceId);
            return;
        }
        ResourceNode node = resourceNodeMapper.selectById(resourceNodeId);
        if (node == null) {
            log.warn("远程取消失败：节点不存在 nodeId={} taskInstanceId={}", resourceNodeId, taskInstanceId);
            return;
        }
        boolean cancelled = workerHttpClient.cancelRun(node, taskInstanceId);
        if (cancelled) {
            log.info("已向 Worker 发送取消请求 taskInstanceId={} nodeId={}", taskInstanceId, resourceNodeId);
        }
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class TaskExecutionReporter {

    private static final String TRIGGER_WORKER = "WORKER";

    private final TaskInstanceService taskInstanceService;
    private final TaskRetryService taskRetryService;

    public void report(ExecutionResult result, Long taskInstanceId) {
        if (result.isTimedOut()) {
            reportTimeout(taskInstanceId, result.getErrorMessage());
            return;
        }
        if (result.isSuccess()) {
            reportSuccess(taskInstanceId, result.getExitCode());
        } else {
            reportFailure(taskInstanceId, result.getExitCode(), result.getErrorMessage());
        }
    }

    public void reportSuccess(Long taskInstanceId, int exitCode) {
        transition(
                taskInstanceId,
                TaskInstanceStatus.RUNNING.getCode(),
                TaskInstanceStatus.SUCCESS.getCode(),
                exitCode,
                null,
                "执行成功");
    }

    public void reportFailure(Long taskInstanceId, Integer exitCode, String errorMessage) {
        Result<TaskInstance> result = transitionWithResult(
                taskInstanceId,
                TaskInstanceStatus.RUNNING.getCode(),
                TaskInstanceStatus.FAILED.getCode(),
                exitCode,
                errorMessage,
                "执行失败");
        if (result != null && result.isSuccess()) {
            triggerRetryIfNeeded(result.getData(), errorMessage);
        }
    }

    public void reportTimeout(Long taskInstanceId, String errorMessage) {
        Result<TaskInstance> result = transitionWithResult(
                taskInstanceId,
                TaskInstanceStatus.RUNNING.getCode(),
                TaskInstanceStatus.TIMEOUT.getCode(),
                -1,
                errorMessage,
                "执行超时");
        if (result != null && result.isSuccess()) {
            triggerRetryIfNeeded(result.getData(), errorMessage);
        }
    }

    private void triggerRetryIfNeeded(TaskInstance instance, String failReason) {
        if (instance == null) return;
        try {
            taskRetryService.retryIfNeeded(instance, failReason != null ? failReason : "worker reported failure");
        } catch (Exception e) {
            log.error("Worker 上报失败后触发重试异常 taskInstanceId={}", instance.getId(), e);
        }
    }

    public void reportConfigurationError(Long taskInstanceId, String errorMessage) {
        reportFailure(taskInstanceId, -1, errorMessage);
    }

    private void transition(
            Long taskInstanceId,
            String fromStatus,
            String toStatus,
            Integer exitCode,
            String errorMessage,
            String reason) {
        transitionWithResult(taskInstanceId, fromStatus, toStatus, exitCode, errorMessage, reason);
    }

    private Result<TaskInstance> transitionWithResult(
            Long taskInstanceId,
            String fromStatus,
            String toStatus,
            Integer exitCode,
            String errorMessage,
            String reason) {
        InternalTaskInstanceStatusTransitionRequest request =
                new InternalTaskInstanceStatusTransitionRequest(
                        fromStatus,
                        toStatus,
                        TRIGGER_WORKER,
                        reason,
                        null,
                        exitCode,
                        errorMessage);

        Result<TaskInstance> result = taskInstanceService.transitionStatus(taskInstanceId, request);
        if (result.isSuccess()) {
            log.info("任务状态已更新 taskInstanceId={} {} -> {}", taskInstanceId, fromStatus, toStatus);
        } else {
            log.warn("任务状态更新未生效 taskInstanceId={} {} -> {} code={} message={}",
                    taskInstanceId, fromStatus, toStatus, result.getCode(), result.getMessage());
        }
        return result;
    }
}

@Slf4j
@Service
@RequiredArgsConstructor
public class TaskHeartbeatService {

    private final TaskInstanceMapper taskInstanceMapper;

    /**
     * 更新指定任务实例的心跳时间（set last_heartbeat_at = NOW()）。
     *
     * @param taskInstanceId 任务实例 ID
     * @return true 表示更新成功（任务仍为 RUNNING）；
     *         false 表示任务已不在 RUNNING 状态（可能已被外部标记为 FAILED/TIMEOUT），
     *         调用方应停止心跳并终止执行。
     */
    public boolean beat(Long taskInstanceId) {
        try {
            int updated = taskInstanceMapper.updateHeartbeat(taskInstanceId);
            if (updated == 0) {
                log.warn("心跳更新失败：任务实例已不在 RUNNING 状态，执行器应停止 taskInstanceId={}", taskInstanceId);
                return false;
            }
            log.trace("心跳已更新 taskInstanceId={}", taskInstanceId);
            return true;
        } catch (Exception e) {
            log.error("心跳上报异常 taskInstanceId={}", taskInstanceId, e);
            return true; // 网络/DB 抖动时不中断执行，下次重试
        }
    }
}

public interface TaskTypeExecutor {

