}

@Component
@RequiredArgsConstructor
public class TaskTypeExecutorRegistry {

    private final List<TaskTypeExecutor> executors;

    public Optional<TaskTypeExecutor> resolve(String taskType) {
        if (taskType == null || taskType.isBlank()) {
            return Optional.empty();
        }
        return executors.stream()
                .filter(executor -> executor.supports(taskType))
                .findFirst();
    }
}

@Component
public class WorkerEndpointResolver {

    public String resolveBaseUrl(ResourceNode node) {
        if (node == null) {
            throw new IllegalArgumentException("资源节点不能为空");
        }
        if (StringUtils.hasText(node.getWorkerEndpoint())) {
            return trimTrailingSlash(node.getWorkerEndpoint().trim());
        }
        if (!StringUtils.hasText(node.getNodeHost()) || node.getNodePort() == null) {
            throw new IllegalStateException("节点缺少 host/port，无法推导 Worker 地址 nodeId=" + node.getId());
        }
        return "http://" + node.getNodeHost().trim() + ":" + node.getNodePort();
    }

    private static String trimTrailingSlash(String url) {
        String result = url;
        while (result.endsWith("/")) {
            result = result.substring(0, result.length() - 1);
        }
        return result;
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class WorkerHttpClient {

    private final RestClient workerRestClient;
    private final TaskExecutorProperties taskExecutorProperties;
    private final WorkerEndpointResolver workerEndpointResolver;

    public boolean submitRun(ResourceNode node, WorkerRunRequest request) {
        String baseUrl = workerEndpointResolver.resolveBaseUrl(node);
        String path = taskExecutorProperties.getWorkerDispatchPath();
        if (!path.startsWith("/")) {
            path = "/" + path;
        }
        String url = baseUrl + path;

        try {
            var spec = workerRestClient.post().uri(url).body(request);
            if (StringUtils.hasText(taskExecutorProperties.getWorkerApiToken())) {
                spec = spec.header(
                        WorkerRestClientConfig.WORKER_TOKEN_HEADER,
                        taskExecutorProperties.getWorkerApiToken());
            }
            var responseEntity = spec.retrieve().toEntity(WorkerRunAcceptedResponse.class);
            if (responseEntity.getStatusCode() != HttpStatus.ACCEPTED) {
                log.warn(
                        "Worker 未返回 202 taskInstanceId={} url={} status={}",
                        request.getTaskInstanceId(),
                        url,
                        responseEntity.getStatusCode());
                return false;
            }

            log.info(
                    "Worker 已接受任务 taskInstanceId={} workerUrl={} response={}",
                    request.getTaskInstanceId(),
                    url,
                    responseEntity.getBody());
            return true;
        } catch (RestClientResponseException e) {
            log.warn(
                    "Worker 返回错误 taskInstanceId={} url={} status={} body={}",
                    request.getTaskInstanceId(),
                    url,
                    e.getStatusCode().value(),
                    e.getResponseBodyAsString(),
                    e);
            return false;
        } catch (RestClientException e) {
            log.warn(
                    "调用 Worker 失败 taskInstanceId={} url={}",
                    request.getTaskInstanceId(),
                    url,
                    e);
            return false;
        }
    }

    /**
     * 请求 Worker 取消正在执行的任务。
     */
    public boolean cancelRun(ResourceNode node, Long taskInstanceId) {
        String baseUrl = workerEndpointResolver.resolveBaseUrl(node);
        String url = baseUrl + "/api/worker/runs/" + taskInstanceId + "/cancel";
        try {
            var spec = workerRestClient.post().uri(url);
            if (StringUtils.hasText(taskExecutorProperties.getWorkerApiToken())) {
                spec = spec.header(
                        WorkerRestClientConfig.WORKER_TOKEN_HEADER,
                        taskExecutorProperties.getWorkerApiToken());
            }
            var response = spec.retrieve().toBodilessEntity();
            return response.getStatusCode().is2xxSuccessful();
        } catch (RestClientException e) {
            log.warn("Worker 取消请求失败 taskInstanceId={} url={}", taskInstanceId, url, e);
            return false;
        }
    }
}

@Component
@RequiredArgsConstructor
public class WorkerRunRequestFactory {

    private final TaskExecutorProperties taskExecutorProperties;

    @Value("${internal.api.token:}")
    private String internalApiToken;

    public WorkerRunRequest fromRunSpec(RunSpec runSpec, ResourceNode node) {
        String baseUrl = trimTrailingSlash(taskExecutorProperties.getSchedulerPublicBaseUrl());
        String instanceBase = baseUrl + "/api/internal/task-instances/" + runSpec.getTaskInstanceId();

        WorkerRunCallback callback = WorkerRunCallback.builder()
                .statusTransitionUrl(instanceBase + "/status")
                .heartbeatUrl(instanceBase + "/heartbeat")
                .internalToken(internalApiToken)
                .build();

        return WorkerRunRequest.builder()
                .taskInstanceId(runSpec.getTaskInstanceId())
                .resourceNodeId(node != null ? node.getId() : runSpec.getResourceNodeId())
                .taskType(runSpec.getTaskType())
                .command(runSpec.getCommand())
                .timeoutSeconds(runSpec.getTimeoutSeconds())
                .executorConfig(runSpec.getExecutorConfig())
                .parameters(runSpec.getParameters())
                .callback(callback)
                .build();
    }

    private static String trimTrailingSlash(String url) {
        if (!StringUtils.hasText(url)) {
            return "http://localhost:8080";
        }
        String result = url.trim();
        while (result.endsWith("/")) {
            result = result.substring(0, result.length() - 1);
        }
        return result;
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class TaskInstanceTerminalHandler {

    private final ResourceSlotService resourceSlotService;

    public void afterTerminal(TaskInstance taskInstance, String terminalStatus) {
        if (taskInstance == null || taskInstance.getId() == null) {
            return;
        }
        String releaseReason = mapReleaseReason(terminalStatus);
        if (releaseReason == null) {
            return;
        }
        try {
            resourceSlotService.releaseForTaskInstanceSystem(taskInstance.getId(), releaseReason);
        } catch (Exception e) {
            log.error(
                    "任务终态资源释放异常 taskInstanceId={} status={}",
                    taskInstance.getId(),
                    terminalStatus,
                    e);
        }
    }

    private static String mapReleaseReason(String terminalStatus) {
        if (terminalStatus == null) {
            return null;
        }
        return switch (terminalStatus.toUpperCase()) {
            case "SUCCESS" -> "SUCCESS";
            case "FAILED" -> "FAILED";
            case "TIMEOUT" -> "TIMEOUT";
            case "CANCELLED" -> "CANCELLED";
            default -> null;
        };
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class DockerTaskTypeExecutor implements TaskTypeExecutor {

    private final ProcessExecutionHelper processExecutionHelper;
    private final ExecutorConfigSupport configSupport;

    @Override
    public boolean supports(String taskType) {
        return taskType != null && "DOCKER".equalsIgnoreCase(taskType.trim());
    }

    @Override
    public ExecutionResult execute(RunSpec runSpec) throws Exception {
        JsonNode root = configSupport.parse(runSpec.getExecutorConfig());
        String image = configSupport.readText(root, "image");
        if (!StringUtils.hasText(image)) {
            return ExecutionResult.configurationError("DOCKER 任务缺少 image 配置");
        }

        Map<String, Object> params = runSpec.getParameters() != null ? runSpec.getParameters() : Map.of();
        image = ParameterTemplateResolver.resolve(image, params);

        List<String> dockerCmd = new ArrayList<>();
        dockerCmd.add("docker");
        dockerCmd.add("run");
        dockerCmd.add("--rm");
        dockerCmd.add("-w");
        dockerCmd.add("/work");
        dockerCmd.add("-v");
        dockerCmd.add(runSpec.getWorkDirectory().toAbsolutePath() + ":/work");

        for (Map.Entry<String, String> env : configSupport.readStringMap(root, "env").entrySet()) {
            dockerCmd.add("-e");
            dockerCmd.add(
                    env.getKey()
                            + "="
                            + ParameterTemplateResolver.resolve(env.getValue(), params));
        }

        dockerCmd.add(image);

        List<String> containerCommand = configSupport.readStringList(root, "command");
        if (containerCommand.isEmpty() && StringUtils.hasText(runSpec.getCommand())) {
            containerCommand = List.of(runSpec.getCommand());
        }
        for (String part : containerCommand) {
            dockerCmd.add(ParameterTemplateResolver.resolve(part, params));
        }

        log.info("启动 DOCKER 子进程 taskInstanceId={} image={}", runSpec.getTaskInstanceId(), image);

        ProcessBuilder processBuilder = new ProcessBuilder(dockerCmd);
        return processExecutionHelper.execute(
                runSpec.getTaskInstanceId(),
                runSpec.getWorkDirectory(),
                runSpec.getTimeoutSeconds(),
                processBuilder);
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class PythonTaskTypeExecutor implements TaskTypeExecutor {

    private final ProcessExecutionHelper processExecutionHelper;
    private final ExecutorConfigSupport configSupport;

    @Override
    public boolean supports(String taskType) {
        return taskType != null && "PYTHON".equalsIgnoreCase(taskType.trim());
    }

    @Override
    public ExecutionResult execute(RunSpec runSpec) throws Exception {
        JsonNode root = configSupport.parse(runSpec.getExecutorConfig());
        String script = configSupport.readText(root, "script");
        if (!StringUtils.hasText(script) && StringUtils.hasText(runSpec.getCommand())) {
            script = runSpec.getCommand();
        }
        if (!StringUtils.hasText(script)) {
            return ExecutionResult.configurationError("PYTHON 任务缺少 script 配置");
        }

        Map<String, Object> params = runSpec.getParameters() != null ? runSpec.getParameters() : Map.of();
        script = ParameterTemplateResolver.resolve(script, params);

        List<String> command = new ArrayList<>();
        command.add(resolvePythonExecutable(root));
        command.add(script);

        for (String arg : configSupport.readStringList(root, "args")) {
            command.add(ParameterTemplateResolver.resolve(arg, params));
        }

        log.info("启动 PYTHON 子进程 taskInstanceId={} command={}", runSpec.getTaskInstanceId(), command);

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        return processExecutionHelper.execute(
                runSpec.getTaskInstanceId(),
                runSpec.getWorkDirectory(),
                runSpec.getTimeoutSeconds(),
                processBuilder);
    }

    private String resolvePythonExecutable(JsonNode root) {
        String configured = configSupport.readText(root, "python");
        return StringUtils.hasText(configured) ? configured.trim() : "python";
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class ShellTaskTypeExecutor implements TaskTypeExecutor {

    private final ProcessExecutionHelper processExecutionHelper;

    @Override
    public boolean supports(String taskType) {
        return taskType != null && "SHELL".equalsIgnoreCase(taskType.trim());
    }

    @Override
    public ExecutionResult execute(RunSpec runSpec) throws Exception {
        if (!StringUtils.hasText(runSpec.getCommand())) {
            return ExecutionResult.configurationError("SHELL 任务缺少 command 配置");
        }

        boolean windows =
                System.getProperty("os.name", "").toLowerCase(Locale.ROOT).contains("win");
        ProcessBuilder processBuilder = windows
                ? new ProcessBuilder("cmd.exe", "/c", runSpec.getCommand())
                : new ProcessBuilder("sh", "-c", runSpec.getCommand());

        log.info(
                "启动 SHELL 子进程 taskInstanceId={} command={}",
                runSpec.getTaskInstanceId(),
                runSpec.getCommand());

        return processExecutionHelper.execute(
                runSpec.getTaskInstanceId(),
                runSpec.getWorkDirectory(),
                runSpec.getTimeoutSeconds(),
                processBuilder);
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class ProcessExecutionHelper {

    private final TaskExecutorProperties properties;
    private final RunningTaskRegistry runningTaskRegistry;

    public ExecutionResult execute(
            Long taskInstanceId, Path workDirectory, Integer timeoutSeconds, ProcessBuilder processBuilder)
            throws Exception {
        Files.createDirectories(workDirectory);
        processBuilder.directory(workDirectory.toFile());
        processBuilder.redirectErrorStream(false);

        Process process = processBuilder.start();
        runningTaskRegistry.register(taskInstanceId, new ProcessRunningTaskHandle(taskInstanceId, process));

        try {
            long waitSeconds = timeoutSeconds != null && timeoutSeconds > 0 ? timeoutSeconds : Long.MAX_VALUE;

            StringBuilder stdout = new StringBuilder();
            StringBuilder stderr = new StringBuilder();
            Charset charset = Charset.defaultCharset();

            Thread stdoutReader = readStream(process.getInputStream(), stdout, charset);
            Thread stderrReader = readStream(process.getErrorStream(), stderr, charset);
            stdoutReader.start();
            stderrReader.start();

            boolean finished;
            if (waitSeconds == Long.MAX_VALUE) {
                process.waitFor();
                finished = true;
            } else {
                finished = process.waitFor(waitSeconds, TimeUnit.SECONDS);
            }

            stdoutReader.join(5_000);
            stderrReader.join(5_000);

            String out = truncate(stdout.toString());
            String err = truncate(stderr.toString());

            if (!finished) {
                process.destroyForcibly();
                process.waitFor(5, TimeUnit.SECONDS);
                return ExecutionResult.timedOut("任务执行超时（超过 " + waitSeconds + " 秒）");
            }

            int exitCode = process.exitValue();
            if (exitCode == 0) {
                return ExecutionResult.success(exitCode, out, err);
            }
            String message = err != null && !err.isBlank() ? err : ("进程退出码 " + exitCode);
            return ExecutionResult.failure(exitCode, out, err, truncate(message));
        } finally {
            runningTaskRegistry.unregister(taskInstanceId);
        }
    }

    private Thread readStream(java.io.InputStream stream, StringBuilder target, Charset charset) {
        Thread thread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, charset))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    if (target.length() < properties.getOutputMaxChars()) {
                        if (!target.isEmpty()) {
                            target.append(System.lineSeparator());
                        }
                        target.append(line);
                    }
                }
            } catch (Exception e) {
                log.debug("读取进程输出异常", e);
            }
        }, "process-exec-stream");
        thread.setDaemon(true);
        return thread;
    }

    private String truncate(String text) {
        if (text == null) {
            return null;
        }
        int max = properties.getOutputMaxChars();
        return text.length() <= max ? text : text.substring(0, max) + "...(truncated)";
    }
}

@Slf4j
@RequiredArgsConstructor
public class ProcessRunningTaskHandle implements RunningTaskHandle {

    private final Long taskInstanceId;
    private final Process process;

    @Override
    public void cancelForcibly() {
        if (process == null || !process.isAlive()) {
            return;
        }
        log.info("强制终止任务进程 taskInstanceId={}", taskInstanceId);
        process.destroyForcibly();
        try {
            process.waitFor(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

public interface RunningTaskHandle {

    void cancelForcibly();
}

@Slf4j
@Component
public class RunningTaskRegistry {

    private final ConcurrentHashMap<Long, RunningTaskHandle> handles = new ConcurrentHashMap<>();

    public void register(Long taskInstanceId, RunningTaskHandle handle) {
        if (taskInstanceId == null || handle == null) {
            return;
        }
        handles.put(taskInstanceId, handle);
    }

    public void unregister(Long taskInstanceId) {
        if (taskInstanceId != null) {
            handles.remove(taskInstanceId);
        }
    }

    /**
     * @return true 表示找到并尝试取消
     */
    public boolean cancel(Long taskInstanceId) {
        RunningTaskHandle handle = handles.remove(taskInstanceId);
        if (handle == null) {
            return false;
        }
        handle.cancelForcibly();
        return true;
    }

    public boolean isTracked(Long taskInstanceId) {
        return taskInstanceId != null && handles.containsKey(taskInstanceId);
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class TaskTimeoutWatchdog {

    private final TaskExecutorProperties properties;
    private final TaskInstanceMapper taskInstanceMapper;
    private final TaskInstanceService taskInstanceService;
    private final TaskExecutionCancelService taskExecutionCancelService;
    private final TaskRetryService taskRetryService;
    private final SchedulerLeaderElection schedulerLeaderElection;

    @Scheduled(fixedDelayString = "${task.executor.timeout-scan-interval-ms:30000}")
    public void scanTimedOutTasks() {
        if (!properties.isTimeoutWatchEnabled()) {
            return;
        }
        boolean executed = schedulerLeaderElection.executeIfLeader(() -> {
            List<TaskInstance> timedOut =
                    taskInstanceMapper.selectTimedOutRunningTasks(properties.getTimeoutScanBatchSize());
            if (timedOut.isEmpty()) {
                return;
            }
            log.info("检测到超时 RUNNING 任务 count={}", timedOut.size());
            for (TaskInstance instance : timedOut) {
                handleTimedOut(instance);
            }
        });
        if (!executed) {
            log.debug("非 Leader 节点，跳过超时任务扫描");
        }
    }

    private void handleTimedOut(TaskInstance instance) {
        Long taskInstanceId = instance.getId();
        taskExecutionCancelService.cancelRunningTask(taskInstanceId, instance.getResourceNodeId());

        InternalTaskInstanceStatusTransitionRequest request =
                new InternalTaskInstanceStatusTransitionRequest(
                        TaskInstanceStatus.RUNNING.getCode(),
                        TaskInstanceStatus.TIMEOUT.getCode(),
                        "SYSTEM",
                        "调度器超时守护",
                        null,
                        -1,
                        "任务执行超过 timeoutSeconds 限制");

        Result<TaskInstance> result = taskInstanceService.transitionStatus(taskInstanceId, request);
        if (result.isSuccess()) {
            log.info("任务已标记为 TIMEOUT taskInstanceId={}", taskInstanceId);
            try {
                taskRetryService.retryIfNeeded(instance, "task timeout exceeded");
            } catch (Exception e) {
                log.error("超时后触发重试失败 taskInstanceId={}", taskInstanceId, e);
            }
        } else {
            log.warn("任务超时状态更新失败 taskInstanceId={} message={}", taskInstanceId, result.getMessage());
        }
    }
}

@Service
public class AuthServiceImpl implements AuthService {

    /** 与实体 User.status：1-正常 */
    private static final int USER_STATUS_ACTIVE = 1;
    /** 与实体 Tenant.status：1-正常 */
    private static final int TENANT_STATUS_ACTIVE = 1;

    private final UserMapper userMapper;
    private final TenantMapper tenantMapper;
    private final TenantMemberMapper tenantMemberMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtTokenProvider jwtTokenProvider;

    public AuthServiceImpl(
            UserMapper userMapper,
            TenantMapper tenantMapper,
            TenantMemberMapper tenantMemberMapper,
            PasswordEncoder passwordEncoder,
            JwtTokenProvider jwtTokenProvider) {
        this.userMapper = userMapper;
        this.tenantMapper = tenantMapper;
        this.tenantMemberMapper = tenantMemberMapper;
        this.passwordEncoder = passwordEncoder;
        this.jwtTokenProvider = jwtTokenProvider;
    }

    @Override
    public Result<LoginResponse> login(String username, String password) {
        if (!StringUtils.hasText(username) || !StringUtils.hasText(password)) {
            return Result.failure(ResultCode.BAD_REQUEST, "用户名和密码不能为空");
        }
        String name = username.trim();

        LambdaQueryWrapper<User> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(User::getUsername, name);
        User user = userMapper.selectOne(queryWrapper);

        if (user == null || !passwordEncoder.matches(password, user.getPasswordHash())) {
            return Result.failure(ResultCode.UNAUTHORIZED, "用户名或密码错误");
        }
        if (user.getStatus() == null || user.getStatus() != USER_STATUS_ACTIVE) {
            return Result.failure(ResultCode.FORBIDDEN, "账号已禁用，请联系管理员");
        }

        String token = jwtTokenProvider.createAccessToken(user.getId(), user.getUsername());
        touchLastLogin(user.getId());

        List<LoginTenantItem> tenants = loadLoginTenants(user.getId());
        Long defaultTenantId = resolveDefaultTenantId(tenants);

        LoginResponse body = new LoginResponse(
                token,
                LoginResponse.BEARER,
                jwtTokenProvider.getExpiresInSeconds(),
                null,
                tenants,
                defaultTenantId);
        return Result.success(body);
    }

    /**
     * 加载登录租户
     * @param userId
     * @return
     */
    @Override
    public List<LoginTenantItem> loadLoginTenants(Long userId) {
        List<TenantMember> members = tenantMemberMapper.selectList(
                new LambdaQueryWrapper<TenantMember>().eq(TenantMember::getUserId, userId));
        if (members.isEmpty()) {
            return List.of();
        }
        List<LoginTenantItem> items = new ArrayList<>();
        for (TenantMember m : members) {
            Tenant t = tenantMapper.selectById(m.getTenantId());
            if (!isTenantUsable(t)) {
                continue;
            }
            items.add(new LoginTenantItem(
                    t.getId(),
                    t.getTenantCode(),
                    t.getTenantName(),
                    m.getRole() != null ? m.getRole() : ""));
        }
        items.sort(Comparator.comparing(LoginTenantItem::tenantId));
        return List.copyOf(items);
    }

    private static Long resolveDefaultTenantId(List<LoginTenantItem> tenants) {
        if (tenants.isEmpty()) {
            return null;
        }
        return tenants.stream()
                .filter(i -> "OWNER".equalsIgnoreCase(i.role()))
                .findFirst()
                .map(LoginTenantItem::tenantId)
                .orElseGet(() -> tenants.get(0).tenantId());
    }

    @Override
    public Result<LoginResponse> switchTenant(Long userId, SwitchTenantRequest request) {
        if (userId == null) {
            return Result.failure(ResultCode.UNAUTHORIZED, "未登录");
        }
        boolean hasId = request.tenantId() != null;
        boolean hasCode = StringUtils.hasText(request.tenantCode());
        if (hasId && hasCode) {
            return Result.failure(ResultCode.BAD_REQUEST, "请只填写 tenantId 或 tenantCode 之一");
        }
        if (!hasId && !hasCode) {
            return Result.failure(ResultCode.BAD_REQUEST, "请提供 tenantId 或 tenantCode");
        }

        User user = userMapper.selectById(userId);
        if (user == null) {
            return Result.failure(ResultCode.UNAUTHORIZED, "用户不存在");
        }

        //查询登录用户将会切换进入哪个租户里权限
        Tenant tenant;
        if (hasId) {
            tenant = tenantMapper.selectById(request.tenantId());
        } else {
            tenant = tenantMapper.selectOne(
                    new LambdaQueryWrapper<Tenant>()
                            .eq(Tenant::getTenantCode, request.tenantCode().trim()));
        }
        if (!isTenantUsable(tenant)) {
            return Result.failure(ResultCode.BAD_REQUEST, "租户不存在、已禁用或已过期");
        }

        TenantMember membership = tenantMemberMapper.selectOne(
                new LambdaQueryWrapper<TenantMember>()
                        .eq(TenantMember::getUserId, userId)
                        .eq(TenantMember::getTenantId, tenant.getId()));
        if (membership == null) {
            return Result.failure(ResultCode.FORBIDDEN, "无权访问该租户");
        }

        String accessToken = jwtTokenProvider.createTenantAccessToken(
                userId,
                user.getUsername(),
                tenant.getId(),
                tenant.getTenantCode(),
                membership.getRole());

        List<LoginTenantItem> tenants = loadLoginTenants(userId);
        Long defaultTenantId = tenant.getId();

        LoginResponse body = new LoginResponse(
                accessToken,
                LoginResponse.BEARER,
                jwtTokenProvider.getExpiresInSeconds(),
                null,
                tenants,
                defaultTenantId);
        return Result.success(body);
    }

    private boolean isTenantUsable(Tenant t) {
        if (t == null || t.getStatus() == null || t.getStatus() != TENANT_STATUS_ACTIVE) {
            return false;
        }
        if (t.getExpireTime() != null && !t.getExpireTime().isAfter(LocalDateTime.now())) {
            return false;
        }
        return true;
    }

    @Override
    public Result<RegisterResponse> register(RegisterRequest request) {
        String username = request.username().trim();
        String email = request.email().trim().toLowerCase(Locale.ROOT);

        if (existsUsername(username)) {
            return Result.failure(ResultCode.CONFLICT, "用户名已存在，请直接登录");
        }
        if (existsEmail(email)) {
            return Result.failure(ResultCode.CONFLICT, "该邮箱已被注册");
        }

        User user = new User();
        user.setUsername(username);
        user.setEmail(email);
        user.setPasswordHash(passwordEncoder.encode(request.password()));
        user.setNickname(username);
        user.setStatus(USER_STATUS_ACTIVE);

        userMapper.insert(user);
        return Result.success(new RegisterResponse("注册成功，请登录"));
    }

    private boolean existsUsername(String username) {
        return userMapper.selectCount(new LambdaQueryWrapper<User>().eq(User::getUsername, username)) > 0;
    }

    private boolean existsEmail(String email) {
        return userMapper.selectCount(new LambdaQueryWrapper<User>().eq(User::getEmail, email)) > 0;
    }

    private void touchLastLogin(Long userId) {
        LambdaUpdateWrapper<User> uw = new LambdaUpdateWrapper<>();
        uw.eq(User::getId, userId).set(User::getLastLoginTime, LocalDateTime.now());
        userMapper.update(null, uw);
    }
}

@Service
public class ProjectServiceImpl extends ServiceImpl<ProjectMapper, Project> implements ProjectService {
    private static final Set<String> CREATE_PROJECT_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");
    private static final Set<String> UPDATE_PROJECT_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");
    private static final Set<String> DELETE_PROJECT_ROLES = Set.of("OWNER", "ADMIN");
    private static final int PROJECT_STATUS_ACTIVE = 1;
    private static final int NOT_DELETED = 0;
    private static final String MSG_PROJECT_NOT_FOUND = "项目不存在";
    private static final String MSG_PROJECT_CODE_EXISTS = "项目编码已存在";

    private final TenantAccessGuard tenantAccessGuard;


    public ProjectServiceImpl(TenantAccessGuard tenantAccessGuard) {
        this.tenantAccessGuard = tenantAccessGuard;
    }

    /**
     * 创建项目（租户内权限校验版）。
     * <p>
     * 校验顺序：
     * 1) 必须已登录；2) 必须已切换租户；3) 必须是该租户成员且角色满足 OWNER/ADMIN/MEMBER；
     * 4) 同租户下 projectCode 不能重复。
     */
    @Override
    public Result<Project> createProject(CreateProjectRequest request) {
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                CREATE_PROJECT_ROLES, "当前角色无创建项目权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();
        Long userId = access.getData().principal().userId();

        String projectCode = request.projectCode().trim();
        // 约束项目编码在同租户内唯一，防止重复创建。
        Long duplicateCount = baseMapper.selectCount(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED)
                        .eq(Project::getProjectCode, projectCode));
        if (duplicateCount != null && duplicateCount > 0) {
            return Result.failure(ResultCode.CONFLICT, MSG_PROJECT_CODE_EXISTS);
        }

        Project project = new Project();
        project.setTenantId(tenantId);
        project.setCreatorUserId(userId);
        project.setProjectName(request.projectName().trim());
        project.setProjectCode(projectCode);
        project.setDescription(StringUtils.hasText(request.description()) ? request.description().trim() : null);
        project.setExtraConfig(StringUtils.hasText(request.extraConfig()) ? request.extraConfig().trim() : null);
        project.setStatus(request.status() != null ? request.status() : PROJECT_STATUS_ACTIVE);

        // 成功写入后返回实体（含数据库生成的主键）。
        int inserted = baseMapper.insert(project);
        if (inserted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "创建项目失败");
        }
        return Result.success(project);
    }

    @Override
    public Result<PageResponse<Project>> listProjects(ListProjectsRequest request) {
        // 列表查询要求：已登录 + 已切租户 + 至少是该租户成员（含 GUEST）。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        int page = Math.max(request.page(), 1);
        int size = Math.min(request.size(), 100);
        Page<Project> pageParam = new Page<>(page, size);
        LambdaQueryWrapper<Project> qw = new LambdaQueryWrapper<Project>()
                .eq(Project::getTenantId, tenantId)
                .eq(Project::getDeleted, NOT_DELETED)
                .orderByDesc(Project::getCreatedAt);
        if (StringUtils.hasText(request.keyword())) {
            String keyword = request.keyword().trim();
            qw.and(w -> w.like(Project::getProjectName, keyword)
                    .or()
                    .like(Project::getProjectCode, keyword));
        }
        IPage<Project> pageResult = baseMapper.selectPage(pageParam, qw);
        return Result.success(new PageResponse<>(pageResult.getRecords(), pageResult.getTotal()));
    }

    @Override
    public Result<Project> getProject(Long projectId) {
        // 详情查询同样必须做租户边界过滤，避免通过 projectId 跨租户探测。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Project project = baseMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, projectId)
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
        }
        return Result.success(project);
    }

    @Override
    public Result<Project> updateProject(Long projectId, UpdateProjectRequest request) {
        // 更新项目要求租户成员角色为 OWNER/ADMIN/MEMBER。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                UPDATE_PROJECT_ROLES, "当前角色无更新项目权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Project project = baseMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, projectId)
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
        }

        if (StringUtils.hasText(request.projectCode())) {
            String newCode = request.projectCode().trim();
            Long duplicateCount = baseMapper.selectCount(
                    new LambdaQueryWrapper<Project>()
                            .eq(Project::getTenantId, tenantId)
                            .eq(Project::getDeleted, NOT_DELETED)
                            .eq(Project::getProjectCode, newCode)
                            .ne(Project::getId, projectId));
            if (duplicateCount != null && duplicateCount > 0) {
                return Result.failure(ResultCode.CONFLICT, MSG_PROJECT_CODE_EXISTS);
            }
            project.setProjectCode(newCode);
        }
        if (StringUtils.hasText(request.projectName())) {
            project.setProjectName(request.projectName().trim());
        }
        // 允许显式清空描述与扩展配置（传空串时转 null）。
        if (request.description() != null) {
            project.setDescription(StringUtils.hasText(request.description()) ? request.description().trim() : null);
        }
        if (request.extraConfig() != null) {
            project.setExtraConfig(StringUtils.hasText(request.extraConfig()) ? request.extraConfig().trim() : null);
        }
        if (request.status() != null) {
            project.setStatus(request.status());
        }

        int updated = baseMapper.updateById(project);
        if (updated != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "更新项目失败");
        }
        return Result.success(project);
    }

    @Override
    public Result<Void> deleteProject(Long projectId) {
        // 删除项目默认使用逻辑删除；仅 OWNER/ADMIN 可删。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                DELETE_PROJECT_ROLES, "当前角色无删除项目权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Project project = baseMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, projectId)
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
        }

        int deleted = baseMapper.deleteById(projectId);
        if (deleted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "删除项目失败");
        }
        return Result.success();
    }
}

@Service
public class ResourceQuotaServiceImpl extends ServiceImpl<ResourceQuotaMapper, ResourceQuota> implements ResourceQuotaService {

    private static final Logger log = LoggerFactory.getLogger(ResourceQuotaServiceImpl.class);

    public static final String REJECT_CPU = "CPU_QUOTA_EXCEEDED";
    public static final String REJECT_MEMORY = "MEMORY_QUOTA_EXCEEDED";
    public static final String REJECT_GPU = "GPU_QUOTA_EXCEEDED";
    public static final String REJECT_RUNNING = "RUNNING_TASKS_QUOTA_EXCEEDED";

    private static final Set<String> READ_ROLES = Set.of("OWNER", "ADMIN", "MEMBER", "GUEST");
    private static final Set<String> RESERVE_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");
    private static final Set<String> OWNER_ONLY = Set.of("OWNER");

    private static final int DEFAULT_MAX_CPU = 10;
    private static final int DEFAULT_MAX_MEMORY_MB = 10240;
    private static final int DEFAULT_MAX_GPU = 0;
    private static final int DEFAULT_MAX_RUNNING = 50;
    private static final int DEFAULT_MAX_PENDING = 500;

    private final TenantAccessGuard tenantAccessGuard;

    public ResourceQuotaServiceImpl(TenantAccessGuard tenantAccessGuard) {
        this.tenantAccessGuard = tenantAccessGuard;
    }

    @Override
    public Result<ResourceQuotaDetailResponse> getQuota(long tenantId) {
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                READ_ROLES, "当前角色无查看配额权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() != tenantId) {
            return Result.failure(ResultCode.FORBIDDEN, "无权查看其他租户配额");
        }
        ResourceQuota row = loadOrCreateQuota(tenantId);
        return Result.success(toDetail(row));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<ResourceQuotaDetailResponse> updateQuota(long tenantId, UpdateResourceQuotaRequest request) {
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                OWNER_ONLY, "仅租户 OWNER 可修改配额");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() != tenantId) {
            return Result.failure(ResultCode.FORBIDDEN, "无权修改其他租户配额");
        }

        ResourceQuota row = loadOrCreateQuota(tenantId);
        // 设计稿 §4.2：新上限不得低于当前已用量，避免立即违约
        if (request.maxCpu() < nz(row.getUsedCpu())) {
            return Result.failure(ResultCode.BAD_REQUEST, "maxCpu 不能小于当前已用 CPU: " + nz(row.getUsedCpu()));
        }
        if (request.maxMemoryMb() < nz(row.getUsedMemoryMb())) {
            return Result.failure(ResultCode.BAD_REQUEST, "maxMemoryMb 不能小于当前已用内存(MB): " + nz(row.getUsedMemoryMb()));
        }
        if (request.maxGpu() < nz(row.getUsedGpu())) {
            return Result.failure(ResultCode.BAD_REQUEST, "maxGpu 不能小于当前已用 GPU: " + nz(row.getUsedGpu()));
        }
        if (request.maxRunningTasks() < nz(row.getRunningTasks())) {
            return Result.failure(ResultCode.BAD_REQUEST, "maxRunningTasks 不能小于当前运行占用计数: " + nz(row.getRunningTasks()));
        }

        row.setMaxCpu(request.maxCpu());
        row.setMaxMemoryMb(request.maxMemoryMb());
        row.setMaxGpu(request.maxGpu());
        row.setMaxRunningTasks(request.maxRunningTasks());
        row.setMaxPendingTasks(request.maxPendingTasks());

        int updated = baseMapper.updateById(row);
        if (updated != 1) {
            return Result.failure(ResultCode.CONFLICT, "配额并发更新冲突，请重试");
        }
        // 设计稿 §4.2：记录审计日志（此处用结构化 INFO，后续可接审计表）
        log.info(
                "resource_quota updated tenantId={} maxCpu={} maxMemoryMb={} maxGpu={} maxRunningTasks={} maxPendingTasks={} operatorUserId={}",
                tenantId, request.maxCpu(), request.maxMemoryMb(), request.maxGpu(), request.maxRunningTasks(), request.maxPendingTasks(),
                access.getData().principal().userId());
        ResourceQuota fresh = baseMapper.selectById(row.getId());
        return Result.success(toDetail(fresh));
    }

    @Override
    public Result<QuotaCheckResponse> checkQuota(long tenantId, QuotaCheckRequest request) {
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                RESERVE_ROLES, "当前角色无配额预检权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() != tenantId) {
            return Result.failure(ResultCode.FORBIDDEN, "无权为其他租户执行配额预检");
        }
        return Result.success(evaluateReserveFeasibility(tenantId, request.requestCpu(), request.requestMemoryMb(), request.requestGpu()));
    }

    @Override
    public QuotaCheckResponse evaluateReserveFeasibility(long tenantId, int cpu, int memoryMb, int gpu) {
        ResourceQuota q = loadOrCreateQuota(tenantId);
        return evaluateAgainstRow(q, cpu, memoryMb, gpu);
    }

    @Override
    public boolean tryConsumeForReserve(long tenantId, int cpu, int memoryMb, int gpu) {
        loadOrCreateQuota(tenantId);
        int rows = baseMapper.consumeIfWithinQuota(tenantId, cpu, memoryMb, gpu, 1);
        return rows == 1;
    }

    @Override
    public void releaseForReserve(long tenantId, int cpu, int memoryMb, int gpu) {
        int rows = baseMapper.releaseUsed(tenantId, cpu, memoryMb, gpu, 1);
        if (rows != 1) {
            throw new ResourceQuotaInvariantException("租户配额回退失败，请排查 resource_quota 与 resource_usage 一致性");
        }
    }

    private QuotaCheckResponse evaluateAgainstRow(ResourceQuota q, int cpu, int memoryMb, int gpu) {
        if (nz(q.getUsedCpu()) + cpu > nz(q.getMaxCpu())) {
            return QuotaCheckResponse.reject(REJECT_CPU);
        }
        if (nz(q.getUsedMemoryMb()) + memoryMb > nz(q.getMaxMemoryMb())) {
            return QuotaCheckResponse.reject(REJECT_MEMORY);
        }
        if (nz(q.getUsedGpu()) + gpu > nz(q.getMaxGpu())) {
            return QuotaCheckResponse.reject(REJECT_GPU);
        }
        if (nz(q.getRunningTasks()) + 1 > nz(q.getMaxRunningTasks())) {
            return QuotaCheckResponse.reject(REJECT_RUNNING);
        }
        return QuotaCheckResponse.ok();
    }

    private ResourceQuota loadOrCreateQuota(long tenantId) {
        ResourceQuota q = baseMapper.selectOne(
                new LambdaQueryWrapper<ResourceQuota>().eq(ResourceQuota::getTenantId, tenantId));
        if (q != null) {
            return q;
        }
        ResourceQuota n = new ResourceQuota();
        n.setTenantId(tenantId);
        n.setMaxCpu(DEFAULT_MAX_CPU);
        n.setMaxMemoryMb(DEFAULT_MAX_MEMORY_MB);
        n.setMaxGpu(DEFAULT_MAX_GPU);
        n.setMaxRunningTasks(DEFAULT_MAX_RUNNING);
        n.setMaxPendingTasks(DEFAULT_MAX_PENDING);
        n.setUsedCpu(0);
        n.setUsedMemoryMb(0);
        n.setUsedGpu(0);
        n.setRunningTasks(0);
        try {
            baseMapper.insert(n);
        } catch (DataIntegrityViolationException e) {
            log.debug("concurrent resource_quota insert for tenant {}", tenantId);
        }
        q = baseMapper.selectOne(new LambdaQueryWrapper<ResourceQuota>().eq(ResourceQuota::getTenantId, tenantId));
        if (q == null) {
            throw new IllegalStateException("无法加载或创建租户配额 tenantId=" + tenantId);
        }
        return q;
    }

    private static ResourceQuotaDetailResponse toDetail(ResourceQuota q) {
        long tenantId = q.getTenantId();
        int maxCpu = nz(q.getMaxCpu());
        int maxMem = nz(q.getMaxMemoryMb());
        int maxGpu = nz(q.getMaxGpu());
        int maxRt = nz(q.getMaxRunningTasks());
        int usedCpu = nz(q.getUsedCpu());
        int usedMem = nz(q.getUsedMemoryMb());
        int usedGpu = nz(q.getUsedGpu());
        int run = nz(q.getRunningTasks());
        return new ResourceQuotaDetailResponse(
                tenantId,
                maxCpu,
                maxMem,
                maxGpu,
                maxRt,
                nz(q.getMaxPendingTasks()),
                usedCpu,
                usedMem,
                usedGpu,
                run,
                util(usedCpu, maxCpu),
                util(usedMem, maxMem),
                util(usedGpu, maxGpu),
                util(run, maxRt));
    }

    private static double util(int used, int max) {
        if (max <= 0) {
            return 0;
        }
        return Math.min(1.0, (double) used / max);
    }

    private static int nz(Integer v) {
        return v == null ? 0 : v;
    }
}

@Service
public class ResourceServiceImpl extends ServiceImpl<ResourceNodeMapper, ResourceNode> implements ResourceService {

    private static final Logger log = LoggerFactory.getLogger(ResourceServiceImpl.class);

    /** 设计稿约定：可被调度器纳入候选池 */
    private static final String STATUS_ONLINE = "ONLINE";
    /** 设计稿约定：超时或主动下线后不可调度 */
    private static final String STATUS_OFFLINE = "OFFLINE";

    /** 注册/心跳在 @Version 冲突时的有限重试次数，贴合设计稿「幂等与最后写入为准」 */
    private static final int OPTIMISTIC_UPDATE_RETRY = 5;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<ResourceNode> registerNode(RegisterResourceNodeRequest request) {
        // node_host + node_port 为唯一业务键：存在则走更新（重注册），否则插入
        String host = request.nodeHost().trim();
        int port = request.nodePort();

        ResourceNode existing = findByHostPort(host, port);
        LocalDateTime now = LocalDateTime.now();

        if (existing != null) {
            // 分支 1：已存在 —— upsert 语义下重复注册走更新（设计稿 4.1、6.1）
            for (int attempt = 0; attempt < OPTIMISTIC_UPDATE_RETRY; attempt++) {
                ResourceNode row = findByHostPort(host, port);
                if (row == null) {
                    break;
                }
                fillRegisterStaticFields(row, request);
                row.setTotalCpu(request.totalCpu());
                row.setTotalMemoryMb(request.totalMemoryMb());
                row.setTotalGpu(request.totalGpu());
                // 重注册视为 Worker 重新声明整机容量，可用量与总量对齐，避免残留旧快照
                row.setAvailableCpu(request.totalCpu());
                row.setAvailableMemoryMb(request.totalMemoryMb());
                row.setAvailableGpu(request.totalGpu());
                row.setStatus(STATUS_ONLINE);
                row.setLastHeartbeatTime(now);

                int updated = baseMapper.updateById(row);
                if (updated == 1) {
                    return Result.success(baseMapper.selectById(row.getId()));
                }
            }
            return Result.failure(ResultCode.CONFLICT, "节点信息并发更新冲突，请重试");
        }

        // 分支 2：新建 —— 初始 available = total，状态 ONLINE（设计稿 4.1）
        ResourceNode created = new ResourceNode();
        fillRegisterStaticFields(created, request);
        created.setTotalCpu(request.totalCpu());
        created.setTotalMemoryMb(request.totalMemoryMb());
        created.setTotalGpu(request.totalGpu());
        created.setAvailableCpu(request.totalCpu());
        created.setAvailableMemoryMb(request.totalMemoryMb());
        created.setAvailableGpu(request.totalGpu());
        created.setStatus(STATUS_ONLINE);
        created.setLastHeartbeatTime(now);

        int inserted = baseMapper.insert(created);
        if (inserted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "注册节点失败");
        }
        return Result.success(created);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<ResourceNode> heartbeat(ResourceHeartbeatRequest request) {
        String host = request.nodeHost().trim();
        int port = request.nodePort();

        // 设计稿 4.2：先采用严格模式，找不到则 NOT_FOUND（不隐式自动注册）
        for (int attempt = 0; attempt < OPTIMISTIC_UPDATE_RETRY; attempt++) {
            ResourceNode node = findByHostPort(host, port);
            if (node == null) {
                return Result.failure(ResultCode.NOT_FOUND, "节点不存在，请先注册");
            }

            LocalDateTime now = LocalDateTime.now();
            node.setLastHeartbeatTime(now);

            // 可用资源为可选字段：未传则保留库中旧值，避免空值覆盖有效快照
            if (request.availableCpu() != null) {
                node.setAvailableCpu(request.availableCpu());
            }
            if (request.availableMemoryMb() != null) {
                node.setAvailableMemoryMb(request.availableMemoryMb());
            }
            if (request.availableGpu() != null) {
                node.setAvailableGpu(request.availableGpu());
            }

            // 状态：显式传入则采纳；否则 OFFLINE 节点通过心跳自动拉回 ONLINE，MAINTENANCE 保持不变（设计稿 4.2）
            if (StringUtils.hasText(request.status())) {
                node.setStatus(request.status().trim());
            } else if (STATUS_OFFLINE.equals(node.getStatus())) {
                node.setStatus(STATUS_ONLINE);
            }

            int updated = baseMapper.updateById(node);
            if (updated == 1) {
                return Result.success(baseMapper.selectById(node.getId()));
            }
            // updated == 0：通常为 @Version 乐观锁不匹配，重读再合并，保证最后写入可见
        }
        return Result.failure(ResultCode.CONFLICT, "心跳并发更新冲突，请重试");
    }

    @Override
    public Result<List<ResourceNode>> listNodes(ListResourceNodesRequest request) {
        int page = request.page();
        int size = request.size();
        int offset = (page - 1) * size;

        LambdaQueryWrapper<ResourceNode> qw = new LambdaQueryWrapper<>();
        if (StringUtils.hasText(request.status())) {
            qw.eq(ResourceNode::getStatus, request.status().trim());
        }
        if (StringUtils.hasText(request.nodeType())) {
            qw.eq(ResourceNode::getNodeType, request.nodeType().trim());
        }
        if (StringUtils.hasText(request.keyword())) {
            String keyword = request.keyword().trim();
            // 关键词同时匹配节点名与主机地址，便于控制台检索（设计稿 4.3）
            qw.and(w -> w.like(ResourceNode::getNodeName, keyword).or().like(ResourceNode::getNodeHost, keyword));
        }
        qw.orderByDesc(ResourceNode::getLastHeartbeatTime)
                .orderByDesc(ResourceNode::getId)
                .last("LIMIT " + offset + ", " + size);

        return Result.success(baseMapper.selectList(qw));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Integer> offlineTimeoutNodes(Integer heartbeatTimeoutSeconds) {
        if (heartbeatTimeoutSeconds == null || heartbeatTimeoutSeconds < 1) {
            return Result.failure(ResultCode.BAD_REQUEST, "heartbeatTimeoutSeconds 须为正整数");
        }

        LocalDateTime threshold = LocalDateTime.now().minusSeconds(heartbeatTimeoutSeconds);

        // 仅扫描当前仍为 ONLINE 的节点；last_heartbeat 为空视为从未心跳，一并下线（设计稿 5.2）
        List<ResourceNode> candidates = baseMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getStatus, STATUS_ONLINE)
                        .and(w -> w.isNull(ResourceNode::getLastHeartbeatTime)
                                .or()
                                .lt(ResourceNode::getLastHeartbeatTime, threshold)));

        if (candidates.isEmpty()) {
            return Result.success(0);
        }

        // 设计稿 5.2：记录系统日志，便于排查「何时、因何」被判定超时
        LocalDateTime offlineAt = LocalDateTime.now();
        for (ResourceNode n : candidates) {
            log.info(
                    "Resource node offline by heartbeat timeout: id={}, host={}, port={}, lastHeartbeatTime={}, offlineAt={}, timeoutSeconds={}",
                    n.getId(), n.getNodeHost(), n.getNodePort(), n.getLastHeartbeatTime(), offlineAt, heartbeatTimeoutSeconds);
        }

        // 批量将仍满足条件的节点标为 OFFLINE（二次带 status 条件，降低与心跳并发时的误伤）
        LambdaUpdateWrapper<ResourceNode> uw = new LambdaUpdateWrapper<>();
        uw.set(ResourceNode::getStatus, STATUS_OFFLINE)
                .eq(ResourceNode::getStatus, STATUS_ONLINE)
                .in(ResourceNode::getId, candidates.stream().map(ResourceNode::getId).toList())
                .and(w -> w.isNull(ResourceNode::getLastHeartbeatTime).or().lt(ResourceNode::getLastHeartbeatTime, threshold));

        int affected = baseMapper.update(null, uw);
        return Result.success(affected);
    }

    private ResourceNode findByHostPort(String host, int port) {
        return baseMapper.selectOne(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getNodeHost, host)
                        .eq(ResourceNode::getNodePort, port));
    }

    private static void fillRegisterStaticFields(ResourceNode target, RegisterResourceNodeRequest request) {
        target.setNodeName(request.nodeName().trim());
        target.setNodeHost(request.nodeHost().trim());
        target.setNodePort(request.nodePort());
        if (StringUtils.hasText(request.workerEndpoint())) {
            target.setWorkerEndpoint(normalizeWorkerEndpoint(request.workerEndpoint()));
        } else {
            target.setWorkerEndpoint(defaultWorkerEndpoint(request.nodeHost(), request.nodePort()));
        }
        target.setNodeType(request.nodeType().trim());
        target.setGpuModel(StringUtils.hasText(request.gpuModel()) ? request.gpuModel().trim() : null);
        target.setLabels(StringUtils.hasText(request.labels()) ? request.labels().trim() : null);
    }

    private static String defaultWorkerEndpoint(String host, int port) {
        return "http://" + host.trim() + ":" + port;
    }

    private static String normalizeWorkerEndpoint(String endpoint) {
        String trimmed = endpoint.trim();
        while (trimmed.endsWith("/")) {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }
        return trimmed;
    }
}

@Service
public class ResourceSlotServiceImpl implements ResourceSlotService {

    private static final Logger log = LoggerFactory.getLogger(ResourceSlotServiceImpl.class);

    private static final String NODE_STATUS_ONLINE = "ONLINE";

    private static final String SLOT_CPU = "CPU";
    private static final String SLOT_GPU = "GPU";
    private static final String SLOT_MEMORY = "MEMORY";

    private static final String USAGE_RESERVED = ResourceUsageStatuses.RESERVED;
    private static final String USAGE_RELEASED = ResourceUsageStatuses.RELEASED;

    private static final Set<String> RESERVE_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");

    private final ResourceSlotMapper resourceSlotMapper;
    private final ResourceUsageMapper resourceUsageMapper;
    private final ResourceNodeMapper resourceNodeMapper;
    private final TaskInstanceMapper taskInstanceMapper;
    private final TaskMapper taskMapper;
    private final ProjectMapper projectMapper;
    private final TenantAccessGuard tenantAccessGuard;
    private final ResourceQuotaService resourceQuotaService;

    public ResourceSlotServiceImpl(
            ResourceSlotMapper resourceSlotMapper,
            ResourceUsageMapper resourceUsageMapper,
            ResourceNodeMapper resourceNodeMapper,
            TaskInstanceMapper taskInstanceMapper,
            TaskMapper taskMapper,
            ProjectMapper projectMapper,
            TenantAccessGuard tenantAccessGuard,
            ResourceQuotaService resourceQuotaService) {
        this.resourceSlotMapper = resourceSlotMapper;
        this.resourceUsageMapper = resourceUsageMapper;
        this.resourceNodeMapper = resourceNodeMapper;
        this.taskInstanceMapper = taskInstanceMapper;
        this.taskMapper = taskMapper;
        this.projectMapper = projectMapper;
        this.tenantAccessGuard = tenantAccessGuard;
        this.resourceQuotaService = resourceQuotaService;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<ReserveResourceResponse> reserve(ReserveResourceRequest request) {
        if (request == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "请求不能为空");
        }

        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                RESERVE_ROLES, "当前角色无资源预留权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "缺少租户上下文");
        }
        long principalTenantId = access.getData().principal().tenantId();
        if (principalTenantId != request.tenantId()) {
            return Result.failure(ResultCode.FORBIDDEN, "租户上下文与请求不一致");
        }

        return doReserve(request);
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<ReserveResourceResponse> reserveForScheduler(ReserveResourceRequest request) {
        if (request == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "请求不能为空");
        }
        if (request.tenantId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "租户ID不能为空");
        }
        return doReserve(request);
    }

    private Result<ReserveResourceResponse> doReserve(ReserveResourceRequest request) {
        int cpu = request.cpu();
        int mem = request.memoryMb();
        int gpu = request.gpu();
        if (cpu <= 0 && mem <= 0 && gpu <= 0) {
            return Result.failure(ResultCode.BAD_REQUEST, "资源需求至少一项大于 0");
        }

        if (request.taskInstanceId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "任务实例ID不能为空");
        }

        // 非 RELEASED 的流水均视为仍占用租户/实例语义，必须先 release 才能再次 reserve（含 FAILED 等终态未回补场景）
        Long blockingCnt = resourceUsageMapper.selectCount(
                new LambdaQueryWrapper<ResourceUsage>()
                        .eq(ResourceUsage::getTaskInstanceId, request.taskInstanceId())
                        .in(ResourceUsage::getStatus, ResourceUsageStatuses.BLOCK_NEW_RESERVE_UNTIL_RELEASED));
        if (blockingCnt != null && blockingCnt > 0) {
            return Result.failure(ResultCode.CONFLICT, "该任务实例仍有未释放的资源流水，请先 release");
        }

        Result<Long> tenantCheck = resolveTenantForTaskInstance(request.taskInstanceId());
        if (!tenantCheck.isSuccess()) {
            return Result.failure(tenantCheck.getCode(), tenantCheck.getMessage());
        }
        if (!tenantCheck.getData().equals(request.tenantId())) {
            return Result.failure(ResultCode.FORBIDDEN, "任务实例不属于当前租户");
        }

        CandidateNodes candidateNodes = resolveCandidateNodes(request.candidateNodeIds());
        List<Long> candidates = candidateNodes.ids();
        if (candidates.isEmpty()) {
            return Result.failure(ResultCode.BAD_REQUEST, "无 ONLINE 候选节点");
        }
        Map<Long, ResourceNode> onlineById = candidateNodes.onlineById();

        /*
         * P0 配额竞态修复：先 tryConsume（单条 SQL 条件更新），再抢槽位写流水。
         * 原因：@Transactional 方法内「return Result.failure」仍会提交事务；若在扣槽位之后才 consume 失败，
         * 仅靠抛异常回滚不够覆盖所有 return 分支。失败路径在返回前显式 releaseForReserve 与 consume 对称。
         * 已删除仅内存预检 evaluateReserveFeasibility：与原子 consume 重复且不能消除竞态。
         */
        if (!resourceQuotaService.tryConsumeForReserve(request.tenantId(), cpu, mem, gpu)) {
            return Result.failure(ResultCode.BAD_REQUEST, "租户配额不足（含并发竞争）");
        }

        for (Long nodeId : candidates) {
            if (nodeId == null) {
                continue;
            }
            ResourceNode node = onlineById.get(nodeId);
            if (node == null) {
                continue;
            }
            ensureSlotsInitialized(node);
            if (!tryDecrementAll(nodeId, cpu, mem, gpu)) {
                continue;
            }
            try {
                ResourceUsage usage = new ResourceUsage();
                usage.setTenantId(request.tenantId());
                usage.setTaskInstanceId(request.taskInstanceId());
                usage.setNodeId(nodeId);
                usage.setCpuUsed(cpu);
                usage.setMemoryMbUsed(mem);
                usage.setGpuUsed(gpu);
                usage.setStatus(USAGE_RESERVED);
                usage.setReason(null);
                usage.setCreatedAt(LocalDateTime.now());
                int ins = resourceUsageMapper.insert(usage);
                if (ins != 1) {
                    undoDecrementAll(nodeId, cpu, mem, gpu);
                    rollbackQuotaConsumed(request.tenantId(), cpu, mem, gpu);
                    return Result.failure(ResultCode.INTERNAL_ERROR, "写入资源使用流水失败");
                }
                int tu = taskInstanceMapper.update(
                        null,
                        new LambdaUpdateWrapper<TaskInstance>()
                                .eq(TaskInstance::getId, request.taskInstanceId())
                                .set(TaskInstance::getResourceNodeId, nodeId));
                if (tu != 1) {
                    // 仅抛异常：由事务回滚撤销本方法内已执行的 quota consume、槽位扣减与 usage 插入，避免先 undo 再回滚造成双重回补
                    throw new IllegalStateException("更新任务实例节点绑定失败，taskInstanceId=" + request.taskInstanceId());
                }
                log.info(
                        "resource reserve ok tenantId={} taskInstanceId={} nodeId={} usageId={} cpu={} memMb={} gpu={}",
                        request.tenantId(), request.taskInstanceId(), nodeId, usage.getId(), cpu, mem, gpu);
                return Result.success(new ReserveResourceResponse(nodeId, usage.getId(), cpu, mem, gpu));
            } catch (DataIntegrityViolationException e) {
                undoDecrementAll(nodeId, cpu, mem, gpu);
                rollbackQuotaConsumed(request.tenantId(), cpu, mem, gpu);
                log.warn(
                        "resource reserve conflict tenantId={} taskInstanceId={} nodeId={} detail={}",
                        request.tenantId(), request.taskInstanceId(), nodeId, e.getMessage());
                return Result.failure(ResultCode.CONFLICT, "资源预留冲突，请重试");
            }
        }

        rollbackQuotaConsumed(request.tenantId(), cpu, mem, gpu);
        return Result.failure(ResultCode.BAD_REQUEST, "无可用节点满足资源需求");
    }

    /**
     * 与 tryConsumeForReserve 对称回补配额；用于「已 consume 但槽位/流水路径失败」且方法即将 return failure 的场景。
     */
    private void rollbackQuotaConsumed(long tenantId, int cpu, int mem, int gpu) {
        resourceQuotaService.releaseForReserve(tenantId, cpu, mem, gpu);
    }

    //这个方法的核心逻辑是：找到符合条件的资源占用记录，验证权限和状态，然后更新状态为 RELEASED，并回补资源槽位和租户配额。
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Void> release(ReleaseResourceRequest request) {
        if (request == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "请求不能为空");
        }

        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                RESERVE_ROLES, "当前角色无资源释放权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "缺少租户上下文");
        }
        long principalTenantId = access.getData().principal().tenantId();

        if (request.usageId() == null && request.taskInstanceId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "usageId 与 taskInstanceId 至少填一个");
        }

        ResourceUsage active = findActiveUsage(request);
        if (active == null) {
            if (isAlreadyReleased(request)) {
                return Result.success();
            }
            return Result.failure(ResultCode.NOT_FOUND, "未找到可释放的资源占用");
        }
        if (active.getTenantId() == null || principalTenantId != active.getTenantId()) {
            return Result.failure(ResultCode.FORBIDDEN, "无权释放该资源占用");
        }
        return applyRelease(active, buildReleaseReason(request.reason(), request.remark()));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void releaseForTaskInstanceSystem(Long taskInstanceId, String reason) {
        if (taskInstanceId == null) {
            return;
        }
        ReleaseResourceRequest request = new ReleaseResourceRequest(taskInstanceId, null, reason, "system");
        ResourceUsage active = findActiveUsage(request);
        if (active == null) {
            if (!isAlreadyReleased(request)) {
                log.debug("系统释放：未找到可释放占用 taskInstanceId={}", taskInstanceId);
            }
            return;
        }
        applyRelease(active, buildReleaseReason(reason, "system"));
    }

    private Result<Void> applyRelease(ResourceUsage active, String reasonText) {
        if (active.getNodeId() == null) {
            log.warn("release skipped slot restore: usageId={} has null nodeId", active.getId());
        }

        LocalDateTime now = LocalDateTime.now();
        int u = resourceUsageMapper.update(
                null,
                new LambdaUpdateWrapper<ResourceUsage>()
                        .eq(ResourceUsage::getId, active.getId())
                        .in(ResourceUsage::getStatus, ResourceUsageStatuses.RELEASABLE_STATUSES)
                        .set(ResourceUsage::getStatus, USAGE_RELEASED)
                        .set(ResourceUsage::getReason, reasonText)
                        .set(ResourceUsage::getReleasedAt, now));
        if (u != 1) {
            return Result.failure(ResultCode.CONFLICT, "资源占用状态已变更，请重试");
        }

        if (active.getNodeId() != null) {
            restoreSlots(active.getNodeId(), active.getCpuUsed(), active.getMemoryMbUsed(), active.getGpuUsed());
        }
        if (active.getTenantId() != null) {
            resourceQuotaService.releaseForReserve(
                    active.getTenantId(),
                    nz(active.getCpuUsed()),
                    nz(active.getMemoryMbUsed()),
                    nz(active.getGpuUsed()));
        }
        log.info(
                "resource release ok usageId={} taskInstanceId={} tenantId={} nodeId={} reason={}",
                active.getId(), active.getTaskInstanceId(), active.getTenantId(), active.getNodeId(), reasonText);
        return Result.success();
    }

    @Override
    public Result<List<ResourceUsage>> listUsage(ListResourceUsageRequest request) {
        if (request == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "请求不能为空");
        }

        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                RESERVE_ROLES, "当前角色无查看资源流水权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        if (access.getData().principal().tenantId() == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "缺少租户上下文");
        }
        long principalTenantId = access.getData().principal().tenantId();
        if (principalTenantId != request.tenantId()) {
            return Result.failure(ResultCode.FORBIDDEN, "租户上下文与请求不一致");
        }

        int offset = (request.page() - 1) * request.size();
        LambdaQueryWrapper<ResourceUsage> qw = new LambdaQueryWrapper<ResourceUsage>()
                .eq(ResourceUsage::getTenantId, request.tenantId());
        if (StringUtils.hasText(request.status())) {
            qw.eq(ResourceUsage::getStatus, request.status().trim().toUpperCase(Locale.ROOT));
        }
        if (request.nodeId() != null) {
            qw.eq(ResourceUsage::getNodeId, request.nodeId());
        }
        qw.orderByDesc(ResourceUsage::getCreatedAt).orderByDesc(ResourceUsage::getId)
                .last("LIMIT " + offset + ", " + request.size());
        return Result.success(resourceUsageMapper.selectList(qw));
    }

    /**
     * P1：一次 IN 查询拉齐候选 ONLINE 节点，避免对每个 nodeId 单独 selectById。
     */
    /**
     * 解析候选节点：显式 id 列表走一次 IN 查询；未指定时沿用「全量 ONLINE」单次查询结果，避免二次打库。
     */
    private CandidateNodes resolveCandidateNodes(List<Long> candidateNodeIds) {
        if (candidateNodeIds != null && !candidateNodeIds.isEmpty()) {
            List<Long> ordered = new ArrayList<>();
            for (Long id : candidateNodeIds) {
                if (id != null && !ordered.contains(id)) {
                    ordered.add(id);
                }
            }
            return new CandidateNodes(ordered, loadOnlineCandidatesById(ordered));
        }
        List<ResourceNode> online = resourceNodeMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getStatus, NODE_STATUS_ONLINE)
                        .orderByAsc(ResourceNode::getId));
        Map<Long, ResourceNode> map = online.stream()
                .filter(n -> n.getId() != null)
                .collect(Collectors.toMap(ResourceNode::getId, n -> n, (a, b) -> a));
        List<Long> ids = online.stream().map(ResourceNode::getId).toList();
        return new CandidateNodes(ids, map);
    }

    private Map<Long, ResourceNode> loadOnlineCandidatesById(List<Long> candidateIds) {
        if (candidateIds == null || candidateIds.isEmpty()) {
            return Map.of();
        }
        List<Long> ids = candidateIds.stream().filter(id -> id != null).distinct().toList();
        if (ids.isEmpty()) {
            return Map.of();
        }
        List<ResourceNode> rows = resourceNodeMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .in(ResourceNode::getId, ids)
                        .eq(ResourceNode::getStatus, NODE_STATUS_ONLINE));
        return rows.stream()
                .filter(n -> n.getId() != null)
                .collect(Collectors.toMap(ResourceNode::getId, n -> n, (a, b) -> a));
    }

    private record CandidateNodes(List<Long> ids, Map<Long, ResourceNode> onlineById) {
    }

    /**
     * 按 CPU → MEMORY → GPU 顺序尝试原子扣减；任一失败则回补已成功的维度，避免“只扣到一半”。
     */
    private boolean tryDecrementAll(Long nodeId, int cpu, int mem, int gpu) {
        int r1 = decLine(nodeId, SLOT_CPU, cpu);
        if (r1 != 1) {
            return false;
        }
        int r2 = decLine(nodeId, SLOT_MEMORY, mem);
        if (r2 != 1) {
            undoDecrementLine(nodeId, SLOT_CPU, cpu);
            return false;
        }
        int r3 = decLine(nodeId, SLOT_GPU, gpu);
        if (r3 != 1) {
            undoDecrementLine(nodeId, SLOT_CPU, cpu);
            undoDecrementLine(nodeId, SLOT_MEMORY, mem);
            return false;
        }
        return true;
    }

    private void undoDecrementAll(Long nodeId, int cpu, int mem, int gpu) {
        undoDecrementLine(nodeId, SLOT_CPU, cpu);
        undoDecrementLine(nodeId, SLOT_MEMORY, mem);
        undoDecrementLine(nodeId, SLOT_GPU, gpu);
    }

    private int decLine(Long nodeId, String type, int amount) {
        if (amount <= 0) {
            return 1;
        }
        return resourceSlotMapper.decreaseIfEnough(nodeId, type, amount);
    }

    private void undoDecrementLine(Long nodeId, String type, int amount) {
        if (amount <= 0) {
            return;
        }
        int n = resourceSlotMapper.increaseAvailable(nodeId, type, amount);
        if (n != 1) {
            log.error("槽位回补失败 nodeId={} type={} amount={}", nodeId, type, amount);
            throw new IllegalStateException("槽位回补失败 nodeId=" + nodeId + " type=" + type);
        }
    }

    private void restoreSlots(Long nodeId, Integer cpu, Integer mem, Integer gpu) {
        undoDecrementLine(nodeId, SLOT_CPU, nz(cpu));
        undoDecrementLine(nodeId, SLOT_MEMORY, nz(mem));
        undoDecrementLine(nodeId, SLOT_GPU, nz(gpu));
    }

    /**
     * P2：单条 INSERT IGNORE 初始化三行槽位，降低并发下逐行判断的窗口。
     */
    private void ensureSlotsInitialized(ResourceNode node) {
        if (node == null || node.getId() == null) {
            return;
        }
        long nid = node.getId();
        int tc = nz(node.getTotalCpu());
        int ac = cappedAvail(tc, nz(node.getAvailableCpu()));
        int tm = nz(node.getTotalMemoryMb());
        int am = cappedAvail(tm, nz(node.getAvailableMemoryMb()));
        int tg = nz(node.getTotalGpu());
        int ag = cappedAvail(tg, nz(node.getAvailableGpu()));
        resourceSlotMapper.insertSlotsIfAbsent(nid, tc, ac, tm, am, tg, ag);
    }

    private static int cappedAvail(int total, int avail) {
        return Math.min(total, Math.max(0, avail));
    }

    private static int nz(Integer v) {
        return v == null ? 0 : v;
    }

    private Result<Long> resolveTenantForTaskInstance(Long taskInstanceId) {
        TaskInstance ti = taskInstanceMapper.selectById(taskInstanceId);
        if (ti == null) {
            return Result.failure(ResultCode.NOT_FOUND, "任务实例不存在");
        }
        Task task = taskMapper.selectById(ti.getTaskId());
        if (task == null) {
            return Result.failure(ResultCode.NOT_FOUND, "任务定义不存在");
        }
        Project project = projectMapper.selectById(task.getProjectId());
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, "项目不存在");
        }
        return Result.success(project.getTenantId());
    }

    private ResourceUsage findActiveUsage(ReleaseResourceRequest request) {
        if (request.usageId() != null) {
            return resourceUsageMapper.selectOne(
                    new LambdaQueryWrapper<ResourceUsage>()
                            .eq(ResourceUsage::getId, request.usageId())
                            .in(ResourceUsage::getStatus, ResourceUsageStatuses.RELEASABLE_STATUSES));
        }
        return resourceUsageMapper.selectOne(
                new LambdaQueryWrapper<ResourceUsage>()
                        .eq(ResourceUsage::getTaskInstanceId, request.taskInstanceId())
                        .in(ResourceUsage::getStatus, ResourceUsageStatuses.RELEASABLE_STATUSES)
                        .orderByDesc(ResourceUsage::getId)
                        .last("LIMIT 1"));
    }

    private boolean isAlreadyReleased(ReleaseResourceRequest request) {
        if (request.usageId() != null) {
            ResourceUsage u = resourceUsageMapper.selectById(request.usageId());
            return u != null && USAGE_RELEASED.equalsIgnoreCase(safe(u.getStatus()));
        }
        Long cnt = resourceUsageMapper.selectCount(
                new LambdaQueryWrapper<ResourceUsage>()
                        .eq(ResourceUsage::getTaskInstanceId, request.taskInstanceId())
                        .eq(ResourceUsage::getStatus, USAGE_RELEASED));
        return cnt != null && cnt > 0;
    }

    private static String buildReleaseReason(String reason, String remark) {
        if (reason == null || reason.isBlank()) {
            return "UNKNOWN";
        }
        if (!StringUtils.hasText(remark)) {
            return reason.trim();
        }
        return reason.trim() + " | " + remark.trim();
    }

    private static String safe(String s) {
        return s == null ? "" : s.trim();
    }
}

@Service
@Slf4j
public class TaskInstanceServiceImpl extends ServiceImpl<TaskInstanceMapper, TaskInstance> implements TaskInstanceService {
    
    private static final String STATUS_PENDING = "PENDING";
    private static final String STATUS_RUNNING = "RUNNING";
    private static final String STATUS_SUCCESS = "SUCCESS";
    private static final String STATUS_FAILED = "FAILED";
    private static final String STATUS_CANCELLED = "CANCELLED";
    private static final String STATUS_TIMEOUT = "TIMEOUT";

    private static final Set<String> TERMINAL_STATUSES = Set.of(
            STATUS_SUCCESS, STATUS_FAILED, STATUS_CANCELLED, STATUS_TIMEOUT
    );

    private static final Map<String, Set<String>> ALLOWED_TRANSITIONS = Map.of(
            STATUS_PENDING, Set.of(STATUS_RUNNING, STATUS_CANCELLED),
            STATUS_RUNNING, Set.of(STATUS_SUCCESS, STATUS_FAILED, STATUS_CANCELLED, STATUS_TIMEOUT),
            STATUS_SUCCESS, Set.of(),
            STATUS_FAILED, Set.of(),
            STATUS_CANCELLED, Set.of(),
            STATUS_TIMEOUT, Set.of()
    );

    private final TaskStatusChangeLogMapper taskStatusChangeLogMapper;

    @Autowired
    private TaskCompletionEventPublisher taskCompletionEventPublisher;

    @Autowired
    private TaskInstanceTerminalHandler taskInstanceTerminalHandler;

    public TaskInstanceServiceImpl(TaskStatusChangeLogMapper taskStatusChangeLogMapper) {
        this.taskStatusChangeLogMapper = taskStatusChangeLogMapper;
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<TaskInstance> transitionStatus(Long taskInstanceId, InternalTaskInstanceStatusTransitionRequest request) {
        String fromStatus = normalizeStatus(request.fromStatus());
        String toStatus = normalizeStatus(request.toStatus());

        if (!isKnownStatus(fromStatus) || !isKnownStatus(toStatus)) {
            return Result.failure(ResultCode.BAD_REQUEST, "状态值无效，仅支持 PENDING/RUNNING/SUCCESS/FAILED/CANCELLED/TIMEOUT");
        }
        if (!canTransition(fromStatus, toStatus)) {
            return Result.failure(ResultCode.BAD_REQUEST, "非法状态流转: " + fromStatus + " -> " + toStatus);
        }
        if (!StringUtils.hasText(request.triggerSource())) {
            return Result.failure(ResultCode.BAD_REQUEST, "triggerSource 不能为空");
        }

        TaskInstance current = baseMapper.selectById(taskInstanceId);
        if (current == null) {
            return Result.failure(ResultCode.NOT_FOUND, "任务实例不存在");
        }
        String currentStatus = normalizeStatus(current.getStatus());
        if (!fromStatus.equals(currentStatus)) {
            if (currentStatus.equals(toStatus) && TERMINAL_STATUSES.contains(currentStatus)) {
                return Result.success(current);
            }
            if (TERMINAL_STATUSES.contains(currentStatus)
                    && isWorkerTrigger(request.triggerSource())) {
                log.debug(
                        "忽略迟到 Worker 回调 taskInstanceId={} current={} requested={}",
                        taskInstanceId,
                        currentStatus,
                        toStatus);
                return Result.success(current);
            }
            if (TERMINAL_STATUSES.contains(currentStatus)) {
                return Result.failure(
                        ResultCode.CONFLICT,
                        "任务已处于终态 " + currentStatus + "，无法流转为 " + toStatus);
            }
            return Result.failure(ResultCode.CONFLICT, "当前状态不匹配，期望 " + fromStatus + "，实际 " + currentStatus);
        }

        LocalDateTime now = LocalDateTime.now();
        LambdaUpdateWrapper<TaskInstance> uw = new LambdaUpdateWrapper<TaskInstance>()
                .eq(TaskInstance::getId, taskInstanceId)
                .eq(TaskInstance::getStatus, current.getStatus())
                .eq(TaskInstance::getVersion, current.getVersion())
                .set(TaskInstance::getStatus, toStatus);
        //如果任务转为运行态，就设置开始时间
        if (STATUS_RUNNING.equals(toStatus)) {
            uw.set(TaskInstance::getStartTime, now);
            uw.set(TaskInstance::getEndTime, null);
            uw.set(TaskInstance::getDurationMs, null);
            uw.set(TaskInstance::getExitCode, null);
            uw.set(TaskInstance::getErrorMessage, null);
        }
        //如果任务转为终止态，就设置结束时间
        if (TERMINAL_STATUSES.contains(toStatus)) {
            uw.set(TaskInstance::getEndTime, now);
            if (current.getStartTime() != null) {
                long durationMs = Math.max(0L, Duration.between(current.getStartTime(), now).toMillis());
                uw.set(TaskInstance::getDurationMs, durationMs);
            }
            if (STATUS_SUCCESS.equals(toStatus)) {
                uw.set(TaskInstance::getExitCode, request.exitCode() != null ? request.exitCode() : 0);
                uw.set(TaskInstance::getErrorMessage, null);
            } else if (STATUS_FAILED.equals(toStatus) || STATUS_TIMEOUT.equals(toStatus)) {
                uw.set(TaskInstance::getExitCode, request.exitCode());
                uw.set(TaskInstance::getErrorMessage,
                        StringUtils.hasText(request.errorMessage()) ? request.errorMessage().trim() : null);
            }
        }
        //执行乐观锁更新，update(null, uw)：第一个参数为 null，表示完全由 Wrapper 指定更新内容
        //生成的 SQL 类似：
        /*UPDATE task_instance
        SET status = 'RUNNING',
            start_time = '2024-01-01 10:00:00',
            version = version + 1  -- MyBatis-Plus 自动处理版本号
        WHERE id = 123
          AND status = 'PENDING'
          AND version = 5*/
        int updated = baseMapper.update(null, uw);
        //检查更新行数，如果更新行数不是1行，说明版本冲突了。
        if (updated != 1) {
            return Result.failure(ResultCode.CONFLICT, "状态更新冲突，请重试");
        }

        //成功更新后返回最新状态的实体（重新查询）。
        persistStatusChangeLog(taskInstanceId, fromStatus, toStatus, request);

        TaskInstance latest = baseMapper.selectById(taskInstanceId);
        
        // 如果转换到终止状态，发布事件到 Redis Stream（异步，不阻塞返回）
        if (TERMINAL_STATUSES.contains(toStatus)) {
            publishTaskCompletionEvent(latest);
            taskInstanceTerminalHandler.afterTerminal(latest, toStatus);
        }
        
        return Result.success(latest);
    }

    private void persistStatusChangeLog(Long taskInstanceId,
                                        String fromStatus,
                                        String toStatus,
                                        InternalTaskInstanceStatusTransitionRequest request) {
        TaskStatusChangeLog log = new TaskStatusChangeLog();
        log.setTaskInstanceId(taskInstanceId);
        log.setFromStatus(fromStatus);
        log.setToStatus(toStatus);
        log.setTriggerSource(request.triggerSource().trim().toUpperCase(Locale.ROOT));
        log.setReason(StringUtils.hasText(request.reason()) ? request.reason().trim() : null);
        log.setOperatorUserId(request.operatorUserId());
        taskStatusChangeLogMapper.insert(log);
    }

    private static String normalizeStatus(String status) {
        return status == null ? null : status.trim().toUpperCase(Locale.ROOT);
    }

    private static boolean isKnownStatus(String status) {
        return ALLOWED_TRANSITIONS.containsKey(status);
    }

    private static boolean canTransition(String from, String to) {
        Set<String> allowed = ALLOWED_TRANSITIONS.get(from);
        return allowed != null && allowed.contains(to);
    }

    private static boolean isWorkerTrigger(String triggerSource) {
        return triggerSource != null && "WORKER".equalsIgnoreCase(triggerSource.trim());
    }

    /**
     * 发布任务完成事件到 Redis Stream
     * 
     * 这个事件会被 TaskCompletionStreamListener 消费，驱动 DAG 工作流继续执行
     * 
     * @param taskInstance 已转换到终止状态的任务实例
     */
    private void publishTaskCompletionEvent(TaskInstance taskInstance) {
        taskCompletionEventPublisher.publish(taskInstance);
    }
}

@Service
public class TaskServiceImpl extends ServiceImpl<TaskMapper, Task> implements TaskService {
    private static final int TASK_STATUS_ACTIVE = 1;
    private static final int NOT_DELETED = 0;
    private static final Set<String> CREATE_TASK_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");
    private static final Set<String> LIST_TASKS_ROLES = Set.of("OWNER", "ADMIN", "MEMBER", "GUEST");
    private static final Set<String> UPDATE_TASK_ROLES = Set.of("OWNER", "ADMIN", "MEMBER");
    private static final Set<String> DELETE_TASK_ROLES = Set.of("OWNER", "ADMIN");
    private static final String MSG_PROJECT_NOT_FOUND = "项目不存在";
    private static final String MSG_TASK_NOT_FOUND = "任务不存在";
    private static final String MSG_TASK_CODE_EXISTS = "任务编码已存在";

    private final ProjectMapper projectMapper;
    private final TenantAccessGuard tenantAccessGuard;

    public TaskServiceImpl(ProjectMapper projectMapper, TenantAccessGuard tenantAccessGuard) {
        this.projectMapper = projectMapper;
        this.tenantAccessGuard = tenantAccessGuard;
    }

    @Override
    public Result<Task> createTask(CreateTaskRequest request) {
        //首先检验用户是否登录，然后检验用户是否在这个tenant里
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                CREATE_TASK_ROLES, "当前角色无创建任务权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();
        Long userId = access.getData().principal().userId();

        //根据请求中的projectId把项目查出来
        // 这里额外带 tenantId 过滤，防止仅凭 projectId 跨租户创建任务。
        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, request.projectId())
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
        }

        //如果上述检查都通过了，就新建Task对象，设置/拷贝属性，然后保存到数据库中
        Task task = new Task();
        task.setProjectId(project.getId());
        task.setTaskName(request.taskName().trim());

        String taskCode = StringUtils.hasText(request.taskCode()) ? request.taskCode().trim() : null;
        if (taskCode != null) {
            Long duplicateCount = baseMapper.selectCount(
                    new LambdaQueryWrapper<Task>()
                            .eq(Task::getProjectId, project.getId())
                            .eq(Task::getDeleted, NOT_DELETED)
                            .eq(Task::getTaskCode, taskCode));
            if (duplicateCount != null && duplicateCount > 0) {
                return Result.failure(ResultCode.CONFLICT, MSG_TASK_CODE_EXISTS);
            }
        }
        task.setTaskCode(taskCode);

        task.setTaskType(request.taskType().trim());
        task.setExecutorConfig(StringUtils.hasText(request.executorConfig()) ? request.executorConfig().trim() : null);
        task.setScheduleType(StringUtils.hasText(request.scheduleType()) ? request.scheduleType().trim() : "MANUAL");
        task.setCronExpression(StringUtils.hasText(request.cronExpression()) ? request.cronExpression().trim() : null);
        task.setTimeoutSeconds(request.timeoutSeconds() != null ? request.timeoutSeconds() : 3600);
        task.setRetryTimes(request.retryTimes() != null ? request.retryTimes() : 0);
        task.setRetryInterval(request.retryInterval() != null ? request.retryInterval() : 0);
        task.setPriority(request.priority() != null ? request.priority() : 5);
        task.setResourceRequirement(StringUtils.hasText(request.resourceRequire()) ? request.resourceRequire().trim() : null);
        task.setAlertOnFailure(request.alertOnFailure() != null ? request.alertOnFailure() : 0);
        task.setAlertOnTimeout(request.alertOnTimeout() != null ? request.alertOnTimeout() : 0);
        task.setDescription(StringUtils.hasText(request.description()) ? request.description().trim() : null);
        task.setCreatorUserId(userId);
        task.setStatus(request.status() != null ? request.status() : TASK_STATUS_ACTIVE);

        int inserted = baseMapper.insert(task);
        if (inserted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "创建任务失败");
        }

        //返回包装在Result对象中的Task对象
        return Result.success(task);
    }

    @Override
    public Result<List<Task>> listTasks(ListTasksRequest request) {

        //首先检验用户是否登录，然后检验用户是否在这个tenant里
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                LIST_TASKS_ROLES, "当前角色无查看任务列表权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        //只是列举所有的人物列表，这个并不需要太高的权限，租户内的GUEST也可以查看

        //根据请求中的projectId把项目查出来，确认项目存在且用户有权限访问
        Long projectId = request.projectId();
        if (projectId != null) {
            Project project = projectMapper.selectOne(
                    new LambdaQueryWrapper<Project>()
                            .eq(Project::getId, projectId)
                            .eq(Project::getTenantId, tenantId)
                            .eq(Project::getDeleted, NOT_DELETED));
            if (project == null) {
                return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
            }
        }

        //把项目中的任务列表查出来，返回包装在Result对象中的List<Task>对象
        int page = request.page();
        int size = request.size();
        int offset = (page - 1) * size;

        LambdaQueryWrapper<Task> qw = new LambdaQueryWrapper<>();
        if (projectId != null) {
            // 传入 projectId 时，直接按 project_id 查询（上面已完成 tenant 边界校验）。
            qw.eq(Task::getProjectId, projectId);
        } else {
            // 未传 projectId 时，通过可见项目集合收敛任务范围，避免跨租户数据泄漏。
            List<Project> tenantProjects = projectMapper.selectList(
                    new LambdaQueryWrapper<Project>()
                            .eq(Project::getTenantId, tenantId)
                            .eq(Project::getDeleted, NOT_DELETED));
            if (tenantProjects.isEmpty()) {
                return Result.success(List.of());
            }
            List<Long> tenantProjectIds = tenantProjects.stream().map(Project::getId).toList();
            qw.in(Task::getProjectId, tenantProjectIds);
        }
        qw.eq(Task::getDeleted, NOT_DELETED);
        if (request.status() != null) {
            qw.eq(Task::getStatus, request.status());
        }
        if (StringUtils.hasText(request.keyword())) {
            String keyword = request.keyword().trim();
            qw.and(w -> w.like(Task::getTaskName, keyword).or().like(Task::getTaskCode, keyword));
        }
        qw.orderByDesc(Task::getCreatedAt).last("LIMIT " + offset + ", " + size);

        List<Task> tasks = baseMapper.selectList(qw);
        return Result.success(tasks);
    }

    @Override
    public Result<Task> getTask(Long taskId) {
        // 获取任务详情：登录态 + 租户上下文 + 成员权限 + 资源归属校验（task -> project -> tenant）。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                LIST_TASKS_ROLES, "当前角色无查看任务详情权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Task task = baseMapper.selectOne(
                new LambdaQueryWrapper<Task>()
                        .eq(Task::getId, taskId)
                        .eq(Task::getDeleted, NOT_DELETED));
        if (task == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }
        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, task.getProjectId())
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            // 不暴露跨租户任务是否存在，统一返回不存在。
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }
        return Result.success(task);
    }

    @Override
    public Result<Task> updateTask(Long taskId, UpdateTaskRequest request) {
        // 更新任务：登录态 + 租户上下文 + 成员角色（OWNER/ADMIN/MEMBER）+ 资源归属校验。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                UPDATE_TASK_ROLES, "当前角色无更新任务权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Task task = baseMapper.selectOne(
                new LambdaQueryWrapper<Task>()
                        .eq(Task::getId, taskId)
                        .eq(Task::getDeleted, NOT_DELETED));
        if (task == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }
        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, task.getProjectId())
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }

        if (StringUtils.hasText(request.taskCode())) {
            String newCode = request.taskCode().trim();
            Long duplicateCount = baseMapper.selectCount(
                    new LambdaQueryWrapper<Task>()
                            .eq(Task::getProjectId, task.getProjectId())
                            .eq(Task::getDeleted, NOT_DELETED)
                            .eq(Task::getTaskCode, newCode)
                            .ne(Task::getId, taskId));
            if (duplicateCount != null && duplicateCount > 0) {
                return Result.failure(ResultCode.CONFLICT, MSG_TASK_CODE_EXISTS);
            }
            task.setTaskCode(newCode);
        }
        if (StringUtils.hasText(request.taskName())) {
            task.setTaskName(request.taskName().trim());
        }
        if (StringUtils.hasText(request.taskType())) {
            task.setTaskType(request.taskType().trim());
        }
        if (request.executorConfig() != null) {
            task.setExecutorConfig(StringUtils.hasText(request.executorConfig()) ? request.executorConfig().trim() : null);
        }
        if (request.scheduleType() != null) {
            task.setScheduleType(StringUtils.hasText(request.scheduleType()) ? request.scheduleType().trim() : null);
        }
        if (request.cronExpression() != null) {
            task.setCronExpression(StringUtils.hasText(request.cronExpression()) ? request.cronExpression().trim() : null);
        }
        if (request.timeoutSeconds() != null) {
            task.setTimeoutSeconds(request.timeoutSeconds());
        }
        if (request.retryTimes() != null) {
            task.setRetryTimes(request.retryTimes());
        }
        if (request.retryInterval() != null) {
            task.setRetryInterval(request.retryInterval());
        }
        if (request.priority() != null) {
            task.setPriority(request.priority());
        }
        if (request.resourceRequire() != null) {
            task.setResourceRequirement(StringUtils.hasText(request.resourceRequire()) ? request.resourceRequire().trim() : null);
        }
        if (request.alertOnFailure() != null) {
            task.setAlertOnFailure(request.alertOnFailure());
        }
        if (request.alertOnTimeout() != null) {
            task.setAlertOnTimeout(request.alertOnTimeout());
        }
        if (request.description() != null) {
            task.setDescription(StringUtils.hasText(request.description()) ? request.description().trim() : null);
        }
        if (request.status() != null) {
            task.setStatus(request.status());
        }

        int updated = baseMapper.updateById(task);
        if (updated != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "更新任务失败");
        }
        return Result.success(task);
    }

    @Override
    public Result<Void> deleteTask(Long taskId) {
        // 删除任务：默认逻辑删除，仅 OWNER/ADMIN 可执行。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                DELETE_TASK_ROLES, "当前角色无删除任务权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();

        Task task = baseMapper.selectOne(
                new LambdaQueryWrapper<Task>()
                        .eq(Task::getId, taskId)
                        .eq(Task::getDeleted, NOT_DELETED));
        if (task == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }
        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, task.getProjectId())
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_TASK_NOT_FOUND);
        }

        int deleted = baseMapper.deleteById(taskId);
        if (deleted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "删除任务失败");
        }
        return Result.success();
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<List<Task>> batchCreateTasks(BatchCreateTasksRequest request) {
        // 批量创建策略：同一 project、同一 tenant；任一失败整体回滚，避免部分成功导致脏数据。
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                CREATE_TASK_ROLES, "当前角色无批量创建任务权限");
        if (!access.isSuccess()) {
            return Result.failure(access.getCode(), access.getMessage());
        }
        Long tenantId = access.getData().principal().tenantId();
        Long userId = access.getData().principal().userId();

        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, request.projectId())
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            return Result.failure(ResultCode.NOT_FOUND, MSG_PROJECT_NOT_FOUND);
        }

        List<BatchCreateTasksRequest.BatchTaskItem> items = request.tasks();
        if (items == null || items.isEmpty()) {
            return Result.failure(ResultCode.BAD_REQUEST, "任务列表不能为空");
        }

        Set<String> codesInBatch = new HashSet<>();
        // 先做完整校验，避免边插入边失败导致部分成功。
        for (BatchCreateTasksRequest.BatchTaskItem item : items) {
            String taskCode = StringUtils.hasText(item.taskCode()) ? item.taskCode().trim() : null;
            if (taskCode == null) {
                continue;
            }
            String key = taskCode.toUpperCase(Locale.ROOT);
            if (!codesInBatch.add(key)) {
                return Result.failure(ResultCode.CONFLICT, "批量任务中存在重复任务编码: " + taskCode);
            }
            Long duplicateCount = baseMapper.selectCount(
                    new LambdaQueryWrapper<Task>()
                            .eq(Task::getProjectId, project.getId())
                            .eq(Task::getDeleted, NOT_DELETED)
                            .eq(Task::getTaskCode, taskCode));
            if (duplicateCount != null && duplicateCount > 0) {
                return Result.failure(ResultCode.CONFLICT, MSG_TASK_CODE_EXISTS + ": " + taskCode);
            }
        }

        List<Task> created = new ArrayList<>(items.size());
        for (BatchCreateTasksRequest.BatchTaskItem item : items) {
            String taskCode = StringUtils.hasText(item.taskCode()) ? item.taskCode().trim() : null;

            Task task = new Task();
            task.setProjectId(project.getId());
            task.setTaskName(item.taskName().trim());
            task.setTaskCode(taskCode);
            task.setTaskType(item.taskType().trim());
            task.setExecutorConfig(StringUtils.hasText(item.executorConfig()) ? item.executorConfig().trim() : null);
            task.setScheduleType(StringUtils.hasText(item.scheduleType()) ? item.scheduleType().trim() : "MANUAL");
            task.setCronExpression(StringUtils.hasText(item.cronExpression()) ? item.cronExpression().trim() : null);
            task.setTimeoutSeconds(item.timeoutSeconds() != null ? item.timeoutSeconds() : 3600);
            task.setRetryTimes(item.retryTimes() != null ? item.retryTimes() : 0);
            task.setRetryInterval(item.retryInterval() != null ? item.retryInterval() : 0);
            task.setPriority(item.priority() != null ? item.priority() : 5);
            task.setResourceRequirement(StringUtils.hasText(item.resourceRequire()) ? item.resourceRequire().trim() : null);
            task.setAlertOnFailure(item.alertOnFailure() != null ? item.alertOnFailure() : 0);
            task.setAlertOnTimeout(item.alertOnTimeout() != null ? item.alertOnTimeout() : 0);
            task.setDescription(StringUtils.hasText(item.description()) ? item.description().trim() : null);
            task.setCreatorUserId(userId);
            task.setStatus(item.status() != null ? item.status() : TASK_STATUS_ACTIVE);

            int inserted = baseMapper.insert(task);
            if (inserted != 1) {
                return Result.failure(ResultCode.INTERNAL_ERROR, "批量创建任务失败");
            }
            created.add(task);
        }
        return Result.success(created);
    }

}

@Slf4j
@Service
public class TaskSubmitServiceImpl implements TaskSubmitService {

    private static final int DEFAULT_PRIORITY = 5;
    private static final int MAX_BATCH_SIZE = 500;

    private final Snowflake snowflake = IdUtil.getSnowflake(1, 1);
    private final ObjectMapper objectMapper = new ObjectMapper();

    @Autowired
    private TaskInstanceMapper taskInstanceMapper;

    @Autowired
    private TaskMapper taskMapper;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<TaskSubmitResponse> submitTask(TaskSubmitRequest request) {
        try {
            Long tenantId;
            Long submitUserId;
            String traceId = MDC.get("traceId");

            if (request.getWorkflowInstanceId() != null) {
                if (request.getTenantId() == null) {
                    return Result.failure(400, "工作流任务提交缺少 tenantId");
                }
                tenantId = request.getTenantId();
                submitUserId = request.getSubmitUserId();
            } else {
                JwtUserPrincipal principal =
                        (JwtUserPrincipal)
                                SecurityContextHolder.getContext().getAuthentication().getPrincipal();
                tenantId = principal.tenantId();
                submitUserId = principal.userId();
                if (tenantId == null) {
                    return Result.failure(404, "租户信息不存在，请检查令牌");
                }
            }

            Task task = taskMapper.selectOne(new LambdaQueryWrapper<Task>()
                    .eq(Task::getId, request.getTaskId())
                    .eq(Task::getStatus, 1));
            if (task == null) {
                return Result.failure(404, "任务不存在或已被禁用");
            }

            request.setTenantId(tenantId);
            request.setSubmitUserId(submitUserId);
            request.setTraceId(traceId);
            request.setTaskInstanceId(snowflake.nextId());
            request.setSubmitTime(LocalDateTime.now());

            Integer submittedPriority = request.getPriority();
            String submittedExecutorConfig = request.getExecutorConfig();
            String submittedResourceRequirement = request.getResourceRequirement();
            BeanUtils.copyProperties(task, request);

            if (org.springframework.util.StringUtils.hasText(submittedExecutorConfig)) {
                request.setExecutorConfig(submittedExecutorConfig);
            }
            if (org.springframework.util.StringUtils.hasText(submittedResourceRequirement)) {
                request.setResourceRequirement(submittedResourceRequirement);
            }
            if (submittedPriority != null) {
                request.setPriority(submittedPriority);
            } else if (request.getPriority() == null) {
                request.setPriority(DEFAULT_PRIORITY);
            }

            TaskInstance taskInstance = toTaskInstance(request);
            // 同步事务写入：调用方收到 200 时任务已持久化，不存在"已确认但未落库"的悬空窗口
            taskInstanceMapper.insert(taskInstance);

            log.info("任务提交成功 taskInstanceId={} tenantId={} taskId={} taskName={} traceId={}",
                    request.getTaskInstanceId(), tenantId, request.getTaskId(), task.getTaskName(), traceId);

            return Result.success(TaskSubmitResponse.builder()
                    .taskInstanceId(request.getTaskInstanceId())
                    .status(TaskInstanceStatus.PENDING.getCode())
                    .estimatedStartTime(Instant.now())
                    .build());
        } catch (Exception e) {
            log.error("任务提交异常 taskId={}", request.getTaskId(), e);
            return Result.failure(500, "任务提交失败，请稍后重试");
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<BatchTaskSubmitResponse> submitBatch(BatchTaskSubmitRequest request) {
        List<TaskSubmitRequest> tasks = request.getTasks();
        if (tasks == null || tasks.isEmpty()) {
            return Result.failure(400, "批量提交的任务列表不能为空");
        }
        if (tasks.size() > MAX_BATCH_SIZE) {
            return Result.failure(400, "批量提交的任务数量不能超过 " + MAX_BATCH_SIZE);
        }

        List<Long> taskInstanceIds = new ArrayList<>();
        List<TaskInstance> toInsert = new ArrayList<>();
        int failedCount = 0;

        for (TaskSubmitRequest task : tasks) {
            Result<TaskSubmitResponse> result = prepareTaskInstance(task);
            if (result.isSuccess()) {
                taskInstanceIds.add(result.getData().getTaskInstanceId());
                // 从 request 中取出已构建好的 TaskInstance（通过 taskInstanceId 反查）
                toInsert.add(buildTaskInstanceFromRequest(task));
            } else {
                failedCount++;
                log.warn("批量提交任务预处理失败 taskId={} reason={}", task.getTaskId(), result.getMessage());
            }
        }

        if (!toInsert.isEmpty()) {
            taskInstanceMapper.insertBatch(toInsert);
        }

        log.info("批量提交统计 total={} success={} failed={}",
                tasks.size(), toInsert.size(), failedCount);

        if (toInsert.isEmpty()) {
            return Result.failure(500, "所有任务提交失败");
        }

        return Result.success(BatchTaskSubmitResponse.builder()
                .successCount(toInsert.size())
                .taskInstanceIds(taskInstanceIds)
                .build());
    }

    /**
     * 仅做校验和字段填充，不写库，返回已准备好的 TaskSubmitResponse。
     * 供 submitBatch 批量收集后一次性 insertBatch。
     */
    private Result<TaskSubmitResponse> prepareTaskInstance(TaskSubmitRequest request) {
        try {
            Task task = taskMapper.selectOne(new LambdaQueryWrapper<Task>()
                    .eq(Task::getId, request.getTaskId())
                    .eq(Task::getStatus, 1));
            if (task == null) {
                return Result.failure(404, "任务不存在或已被禁用 taskId=" + request.getTaskId());
            }

            request.setTaskInstanceId(snowflake.nextId());
            request.setSubmitTime(LocalDateTime.now());

            Integer submittedPriority = request.getPriority();
            String submittedExecutorConfig = request.getExecutorConfig();
            String submittedResourceRequirement = request.getResourceRequirement();
            BeanUtils.copyProperties(task, request);

            if (org.springframework.util.StringUtils.hasText(submittedExecutorConfig)) {
                request.setExecutorConfig(submittedExecutorConfig);
            }
            if (org.springframework.util.StringUtils.hasText(submittedResourceRequirement)) {
                request.setResourceRequirement(submittedResourceRequirement);
            }
            if (submittedPriority != null) {
                request.setPriority(submittedPriority);
            } else if (request.getPriority() == null) {
                request.setPriority(DEFAULT_PRIORITY);
            }

            return Result.success(TaskSubmitResponse.builder()
                    .taskInstanceId(request.getTaskInstanceId())
                    .status(TaskInstanceStatus.PENDING.getCode())
                    .estimatedStartTime(Instant.now())
                    .build());
        } catch (Exception e) {
            return Result.failure(500, "任务预处理失败: " + e.getMessage());
        }
    }

    private TaskInstance buildTaskInstanceFromRequest(TaskSubmitRequest request) {
        TaskInstance taskInstance = new TaskInstance();
        BeanUtils.copyProperties(request, taskInstance,
                "taskInstanceId", "parameters", "traceId", "taskName", "taskType");
        taskInstance.setId(request.getTaskInstanceId());
        // 触发类型优先使用 request 中显式设置的值（RETRY / WORKFLOW / CRON），否则按来源推断
        if (org.springframework.util.StringUtils.hasText(request.getTriggerType())) {
            taskInstance.setTriggerType(request.getTriggerType());
        } else {
            taskInstance.setTriggerType(request.getWorkflowInstanceId() != null ? "WORKFLOW" : "API");
        }
        taskInstance.setStatus(TaskInstanceStatus.PENDING.getCode());
        taskInstance.setRetryCount(request.getRetryCount() != null ? request.getRetryCount() : 0);
        taskInstance.setVersion(0);
        taskInstance.setInstanceCode(String.valueOf(request.getTaskInstanceId()));
        taskInstance.setCreatedAt(LocalDateTime.now());
        taskInstance.setUpdatedAt(LocalDateTime.now());
        try {
            if (request.getParameters() != null && !request.getParameters().isEmpty()) {
                taskInstance.setParameters(objectMapper.writeValueAsString(request.getParameters()));
            }
        } catch (JsonProcessingException e) {
            log.error("参数序列化失败 taskInstanceId={}", request.getTaskInstanceId(), e);
            taskInstance.setParameters("{}");
        }
        return taskInstance;
    }

    private TaskInstance toTaskInstance(TaskSubmitRequest request) {
        TaskInstance taskInstance = buildTaskInstanceFromRequest(request);
        if (request.getWorkflowInstanceId() != null) {
            taskInstance.setWorkflowInstanceId(request.getWorkflowInstanceId());
        }
        return taskInstance;
    }
}

@Service
public class TenantServiceImpl extends ServiceImpl<TenantMapper, Tenant> implements TenantService {

    private static final int TENANT_STATUS_ACTIVE = 1;
    private static final int USER_STATUS_ACTIVE = 1;
    private static final int DEFAULT_MAX_PROJECTS = 10;
    private static final int DEFAULT_MAX_TASKS = 1000;
    private static final Set<String> ALL_ROLES = Set.of("OWNER", "ADMIN", "MEMBER", "GUEST");

    private final TenantMapper tenantMapper;
    private final TenantMemberMapper tenantMemberMapper;
    private final UserMapper userMapper;
    private final TenantAccessGuard tenantAccessGuard;

    public TenantServiceImpl(
            TenantMapper tenantMapper,
            TenantMemberMapper tenantMemberMapper,
            UserMapper userMapper,
            TenantAccessGuard tenantAccessGuard) {
        this.tenantMapper = tenantMapper;
        this.tenantMemberMapper = tenantMemberMapper;
        this.userMapper = userMapper;
        this.tenantAccessGuard = tenantAccessGuard;
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<Tenant> createTenant(CreateTenantRequest request) {
        //首先理清实现的业务具体是什么样的，这是要创建一个新的租户，而这只能是由已登录用户完成的
        //1.首先检验用户是否登录，如果没有登录则直接返回错误
        Result<JwtUserPrincipal> login = tenantAccessGuard.requireLogin();
        if (!login.isSuccess()) {
            return Result.failure(login.getCode(), login.getMessage());
        }
        JwtUserPrincipal principal = login.getData();

        //2.根据request创建一个新的Tenant对象（应该会需要拷贝一些属性），然后将它放到数据库里
        String tenantCode = request.tenantCode().trim().toLowerCase(Locale.ROOT);
        Long duplicate = tenantMapper.selectCount(
                new LambdaQueryWrapper<Tenant>().eq(Tenant::getTenantCode, tenantCode));
        if (duplicate != null && duplicate > 0) {
            return Result.failure(ResultCode.CONFLICT, "租户编码已存在");
        }

        Tenant tenant = new Tenant();
        tenant.setTenantName(request.tenantName().trim());
        tenant.setTenantCode(tenantCode);
        tenant.setOwnerUserId(principal.userId());
        tenant.setDescription(StringUtils.hasText(request.description()) ? request.description().trim() : null);
        tenant.setStatus(TENANT_STATUS_ACTIVE);
        tenant.setMaxProjects(request.maxProjects() != null ? request.maxProjects() : DEFAULT_MAX_PROJECTS);
        tenant.setMaxTasks(request.maxTasks() != null ? request.maxTasks() : DEFAULT_MAX_TASKS);
        tenant.setExpireTime(request.expireTime());
        int insertedTenant = tenantMapper.insert(tenant);
        if (insertedTenant != 1 || tenant.getId() == null) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "创建租户失败");
        }

        //3.似乎也需要更新tenant_member表，该用户需要作为这个租户的OWNER放到tenant_member表里（一条新记录）
        TenantMember ownerMembership = new TenantMember();
        ownerMembership.setTenantId(tenant.getId());
        ownerMembership.setUserId(principal.userId());
        ownerMembership.setRole("OWNER");
        ownerMembership.setJoinTime(LocalDateTime.now());
        int insertedMember = tenantMemberMapper.insert(ownerMembership);
        if (insertedMember != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "创建租户成员关系失败");
        }

        //4.最后返回创建好的Tenant对象，包装在Result里
        return Result.success(tenant);
    }

    @Override
    public Result<List<TenantMember>> getTenantMembers(Long tenantId) {
        //这个看起来还可以，首先检查用户登陆状态（这绝对能单独抽出一个方法了），
        Result<JwtUserPrincipal> login = tenantAccessGuard.requireLogin();
        if (!login.isSuccess()) {
            return Result.failure(login.getCode(), login.getMessage());
        }
        JwtUserPrincipal principal = login.getData();

        Tenant tenant = tenantMapper.selectById(tenantId);
        if (!isTenantUsable(tenant)) {
            return Result.failure(ResultCode.NOT_FOUND, "租户不存在、已禁用或已过期");
        }

        // 然后检查用户在这个租户里的权限是否足够（至少要是成员），租户内成员有权查看租户中的其他成员列表，如果权限不够则直接返回错误
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess() || !tenantId.equals(access.getData().principal().tenantId())) {
            return Result.failure(ResultCode.FORBIDDEN, "无权查看该租户成员");
        }

        // 最后查询tenant_member表，返回这个租户的所有成员列表
        List<TenantMember> members = tenantMemberMapper.selectList(
                new LambdaQueryWrapper<TenantMember>().eq(TenantMember::getTenantId, tenantId));
        return Result.success(members);
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<TenantMember> addTenantMember(Long tenantId, Long userId, String role) {
        //这个看起来也还可以，首先检查用户登陆状态（这绝对能单独抽出一个方法了），
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess() || !tenantId.equals(access.getData().principal().tenantId())) {
            return Result.failure(ResultCode.FORBIDDEN, "无权操作该租户成员");
        }
        JwtUserPrincipal principal = access.getData().principal();

        Tenant tenant = tenantMapper.selectById(tenantId);
        if (!isTenantUsable(tenant)) {
            return Result.failure(ResultCode.NOT_FOUND, "租户不存在、已禁用或已过期");
        }

        //然后检查用户在这个租户里的权限是否足够（至少要是管理员），其中OWNER有权添加任意成员，ADMIN只能添加MEMBER/GUEST，其他不允许，如果权限不够则直接返回错误
        String operatorRole = normalizeRole(access.getData().membership().getRole());
        String targetRole = normalizeRole(role);
        if (targetRole == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "角色无效，仅支持 OWNER/ADMIN/MEMBER/GUEST");
        }
        if (!canAddRole(operatorRole, targetRole)) {
            return Result.failure(ResultCode.FORBIDDEN, "当前角色无添加该成员角色权限");
        }

        User targetUser = userMapper.selectById(userId);
        if (targetUser == null || targetUser.getStatus() == null || targetUser.getStatus() != USER_STATUS_ACTIVE) {
            return Result.failure(ResultCode.BAD_REQUEST, "目标用户不存在或不可用");
        }
        TenantMember existing = findMembership(tenantId, userId);
        if (existing != null) {
            return Result.failure(ResultCode.CONFLICT, "该用户已是租户成员");
        }

        //最后在tenant_member表里添加一条记录，表示这个用户加入了这个租户，并且具有指定的角色
        TenantMember member = new TenantMember();
        member.setTenantId(tenantId);
        member.setUserId(userId);
        member.setRole(targetRole);
        member.setJoinTime(LocalDateTime.now());
        int inserted = tenantMemberMapper.insert(member);
        if (inserted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "添加成员失败");
        }

        //最后返回添加的TenantMember对象，包装在Result里
        return Result.success(member);
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<TenantMember> updateTenantMemberRole(Long tenantId, Long userId, String role) {
        //这个看起来也还可以，首先检查用户登陆状态（这绝对能单独抽出一个方法了），
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess() || !tenantId.equals(access.getData().principal().tenantId())) {
            return Result.failure(ResultCode.FORBIDDEN, "只有 OWNER 可以修改成员角色");
        }
        JwtUserPrincipal principal = access.getData().principal();

        Tenant tenant = tenantMapper.selectById(tenantId);
        if (!isTenantUsable(tenant)) {
            return Result.failure(ResultCode.NOT_FOUND, "租户不存在、已禁用或已过期");
        }

        //然后检查用户在这个租户里的权限是否足够，只有OWNER有权修改成员角色，如果权限不够则直接返回错误
        if (!"OWNER".equals(normalizeRole(access.getData().membership().getRole()))) {
            return Result.failure(ResultCode.FORBIDDEN, "只有 OWNER 可以修改成员角色");
        }
        String newRole = normalizeRole(role);
        if (newRole == null) {
            return Result.failure(ResultCode.BAD_REQUEST, "角色无效，仅支持 OWNER/ADMIN/MEMBER/GUEST");
        }
        TenantMember targetMembership = findMembership(tenantId, userId);
        if (targetMembership == null) {
            return Result.failure(ResultCode.NOT_FOUND, "成员不存在");
        }
        String oldRole = normalizeRole(targetMembership.getRole());
        if ("OWNER".equals(oldRole) && !"OWNER".equals(newRole)) {
            Long ownerCount = tenantMemberMapper.selectCount(
                    new LambdaQueryWrapper<TenantMember>()
                            .eq(TenantMember::getTenantId, tenantId)
                            .eq(TenantMember::getRole, "OWNER"));
            if (ownerCount != null && ownerCount <= 1) {
                return Result.failure(ResultCode.BAD_REQUEST, "租户必须至少保留一个 OWNER");
            }
        }

        //最后在tenant_member表里更新对应记录的角色字段，表示这个用户在这个租户里的角色被修改了
        targetMembership.setRole(newRole);
        int updated = tenantMemberMapper.updateById(targetMembership);
        if (updated != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "更新成员角色失败");
        }
        // 若更新的是 ownerUserId 对应成员，保持 owner 字段与成员角色一致。
        if (tenant.getOwnerUserId() != null && tenant.getOwnerUserId().equals(userId) && !"OWNER".equals(newRole)) {
            TenantMember anotherOwner = tenantMemberMapper.selectOne(
                    new LambdaQueryWrapper<TenantMember>()
                            .eq(TenantMember::getTenantId, tenantId)
                            .eq(TenantMember::getRole, "OWNER")
                            .last("LIMIT 1"));
            if (anotherOwner != null) {
                tenant.setOwnerUserId(anotherOwner.getUserId());
                tenantMapper.updateById(tenant);
            }
        } else if ("OWNER".equals(newRole) && (tenant.getOwnerUserId() == null || !tenant.getOwnerUserId().equals(userId))) {
            tenant.setOwnerUserId(userId);
            tenantMapper.updateById(tenant);
        }

        //最后返回更新后的TenantMember对象，包装在Result里
        return Result.success(targetMembership);
    }

    @Transactional(rollbackFor = Exception.class)
    @Override
    public Result<Void> deleteTenantMember(Long tenantId, Long userId) {
        //这个看起来也还可以，首先检查用户登陆状态（这绝对能单独抽出一个方法了），
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(Set.of(), "");
        if (!access.isSuccess() || !tenantId.equals(access.getData().principal().tenantId())) {
            return Result.failure(ResultCode.FORBIDDEN, "无权操作该租户成员");
        }
        JwtUserPrincipal principal = access.getData().principal();

        Tenant tenant = tenantMapper.selectById(tenantId);
        if (!isTenantUsable(tenant)) {
            return Result.failure(ResultCode.NOT_FOUND, "租户不存在、已禁用或已过期");
        }
        if (principal.userId().equals(userId)) {
            return Result.failure(ResultCode.BAD_REQUEST, "不支持通过该接口删除自己，请使用退出租户接口");
        }

        //然后检查用户在这个租户里的权限是否足够（至少要是管理员），OWNER可以删除其他任何成员，ADMIN有权删除成员（不能操作OWNER），如果权限不够则直接返回错误
        TenantMember operatorMembership = access.getData().membership();
        TenantMember targetMembership = findMembership(tenantId, userId);
        if (targetMembership == null) {
            return Result.failure(ResultCode.NOT_FOUND, "成员不存在");
        }
        String operatorRole = normalizeRole(operatorMembership.getRole());
        String targetRole = normalizeRole(targetMembership.getRole());
        if (!canDeleteMember(operatorRole, targetRole)) {
            return Result.failure(ResultCode.FORBIDDEN, "当前角色无删除该成员权限");
        }
        if ("OWNER".equals(targetRole)) {
            Long ownerCount = tenantMemberMapper.selectCount(
                    new LambdaQueryWrapper<TenantMember>()
                            .eq(TenantMember::getTenantId, tenantId)
                            .eq(TenantMember::getRole, "OWNER"));
            if (ownerCount != null && ownerCount <= 1) {
                return Result.failure(ResultCode.BAD_REQUEST, "租户必须至少保留一个 OWNER");
            }
        }

        //最后在tenant_member表里删除对应记录，表示这个用户被移出了这个租户
        int deleted = tenantMemberMapper.deleteById(targetMembership.getId());
        if (deleted != 1) {
            return Result.failure(ResultCode.INTERNAL_ERROR, "删除成员失败");
        }
        // 若删除的是 ownerUserId 指向用户，则同步 owner 字段到现存 OWNER。
        if (tenant.getOwnerUserId() != null && tenant.getOwnerUserId().equals(userId)) {
            TenantMember anotherOwner = tenantMemberMapper.selectOne(
                    new LambdaQueryWrapper<TenantMember>()
                            .eq(TenantMember::getTenantId, tenantId)
                            .eq(TenantMember::getRole, "OWNER")
                            .last("LIMIT 1"));
            if (anotherOwner != null) {
                tenant.setOwnerUserId(anotherOwner.getUserId());
                tenantMapper.updateById(tenant);
            }
        }

        //最后返回成功的Result对象，表示删除成功
        return Result.success();
    }

    private TenantMember findMembership(Long tenantId, Long userId) {
        return tenantMemberMapper.selectOne(
                new LambdaQueryWrapper<TenantMember>()
                        .eq(TenantMember::getTenantId, tenantId)
                        .eq(TenantMember::getUserId, userId));
    }

    private static String normalizeRole(String role) {
        if (!StringUtils.hasText(role)) {
            return null;
        }
        String normalized = role.trim().toUpperCase(Locale.ROOT);
        return ALL_ROLES.contains(normalized) ? normalized : null;
    }

    private static boolean canAddRole(String operatorRole, String targetRole) {
        if ("OWNER".equals(operatorRole)) {
            return true;
        }
        if ("ADMIN".equals(operatorRole)) {
            return "MEMBER".equals(targetRole) || "GUEST".equals(targetRole);
        }
        return false;
    }

    private static boolean canDeleteMember(String operatorRole, String targetRole) {
        if ("OWNER".equals(operatorRole)) {
            return true;
        }
        if ("ADMIN".equals(operatorRole)) {
            return !"OWNER".equals(targetRole);
        }
        return false;
    }

    private static boolean isTenantUsable(Tenant t) {
        if (t == null || t.getStatus() == null || t.getStatus() != TENANT_STATUS_ACTIVE) {
            return false;
        }
        return t.getExpireTime() == null || t.getExpireTime().isAfter(LocalDateTime.now());
    }
}

