@Slf4j
@Service
@RequiredArgsConstructor
public class TaskRetryService {

    private final TaskInstanceMapper taskInstanceMapper;
    private final TaskMapper taskMapper;
    private final TaskSubmitService taskSubmitService;

    /**
     * 评估失败任务是否应该重试，若是则创建新实例重新入队。
     *
     * @param failedTaskInstance 刚变为终态（FAILED/TIMEOUT）的任务实例
     * @param failReason         失败原因（写入新实例的 errorMessage）
     * @return true 表示已触发重试；false 表示达到重试上限或 task 不允许重试
     */
    @Transactional(rollbackFor = Exception.class)
    public boolean retryIfNeeded(TaskInstance failedTaskInstance, String failReason) {
        if (failedTaskInstance == null) return false;

        Task task = taskMapper.selectOne(new LambdaQueryWrapper<Task>()
                .eq(Task::getId, failedTaskInstance.getTaskId())
                .eq(Task::getStatus, 1));

        if (task == null) {
            log.warn("任务定义不存在或已禁用，跳过重试 taskId={}", failedTaskInstance.getTaskId());
            return false;
        }

        int maxRetries = task.getRetryTimes() == null ? 0 : task.getRetryTimes();
        int currentRetry = failedTaskInstance.getRetryCount() == null ? 0 : failedTaskInstance.getRetryCount();

        if (currentRetry >= maxRetries) {
            log.info("已达到最大重试次数，不再重试 taskInstanceId={} retryCount={} maxRetries={}",
                    failedTaskInstance.getId(), currentRetry, maxRetries);
            return false;
        }

        // 如果配置了重试间隔，等待一段时间（通过 scheduledTime 实现延迟调度）
        int retryIntervalSeconds = task.getRetryInterval() == null ? 0 : task.getRetryInterval();

        return submitRetryInstance(failedTaskInstance, task, currentRetry + 1, retryIntervalSeconds, failReason);
    }

    private boolean submitRetryInstance(TaskInstance original, Task task, int newRetryCount,
                                        int delaySeconds, String retryReason) {
        TaskSubmitRequest retryRequest = new TaskSubmitRequest();
        retryRequest.setTaskId(original.getTaskId());
        retryRequest.setTenantId(original.getTenantId());
        retryRequest.setSubmitUserId(original.getSubmitUserId());
        retryRequest.setWorkflowInstanceId(original.getWorkflowInstanceId());
        retryRequest.setTriggerType("RETRY");
        retryRequest.setPriority(original.getPriority());
        retryRequest.setParameters(parseParameters(original.getParameters()));
        retryRequest.setResourceRequirement(original.getResourceRequirement());
        retryRequest.setExecutorConfig(original.getExecutorConfig());
        retryRequest.setRetryCount(newRetryCount);

        // 延迟调度：scheduledTime = now + retryInterval
        if (delaySeconds > 0) {
            retryRequest.setScheduledTime(LocalDateTime.now().plusSeconds(delaySeconds));
        }

        Result<?> result = taskSubmitService.submitTask(retryRequest);
        if (result.isSuccess()) {
            log.info("触发任务重试 originalTaskInstanceId={} newRetryCount={}/{} reason={}",
                    original.getId(), newRetryCount, task.getRetryTimes(), retryReason);
            return true;
        } else {
            log.error("触发重试失败 originalTaskInstanceId={} reason={}", original.getId(), result.getMessage());
            return false;
        }
    }

    private java.util.Map<String, Object> parseParameters(String parametersJson) {
        if (parametersJson == null || parametersJson.isBlank()) {
            return java.util.Collections.emptyMap();
        }
        try {
            return new com.fasterxml.jackson.databind.ObjectMapper()
                    .readValue(parametersJson, new com.fasterxml.jackson.core.type.TypeReference<>() {});
        } catch (Exception e) {
            return java.util.Collections.emptyMap();
        }
    }
}

@Slf4j
@Component
@RequiredArgsConstructor
public class TaskScheduleLock {

    private final RedissonClient redissonClient;
    private final SchedulerProperties schedulerProperties;

    public RLock lockFor(long taskInstanceId) {
        return redissonClient.getLock(lockKey(taskInstanceId));
    }

    /**
     * 尝试获取任务调度锁（Watchdog 续期，无固定 lease）。
     *
     * @return true 表示当前线程已持有锁，可执行单任务调度路径
     */
    public boolean tryAcquire(RLock lock) {
        try {
            return lock.tryLock(
                    schedulerProperties.getTaskLockWaitSeconds(),
                    -1,
                    TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    /**
     * 释放任务调度锁（仅当当前线程持有时 unlock）。
     */
    public void release(RLock lock) {
        try {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        } catch (IllegalMonitorStateException e) {
            log.warn("释放任务调度锁时当前线程未持有锁 lockName={}", lock.getName());
        }
    }

    private String lockKey(long taskInstanceId) {
        return schedulerProperties.getTaskLockKeyPrefix() + taskInstanceId;
    }
}

@Slf4j
@Service
@ConditionalOnProperty(name = "scheduler.strategy", havingValue = "fifo")
public class FifoSchedulerServiceImpl extends AbstractSchedulerService implements FifoSchedulerService {

    private static final int BATCH_SIZE = 100;

    public FifoSchedulerServiceImpl(
            TaskInstanceMapper taskInstanceMapper,
            ResourceNodeMapper resourceNodeMapper,
            ResourceSlotService resourceSlotService,
            ResourceQuotaService resourceQuotaService,
            TaskScheduleLock taskScheduleLock,
            TaskDispatchService taskDispatchService) {
        super(taskInstanceMapper, resourceNodeMapper, resourceSlotService,
                resourceQuotaService, taskScheduleLock, taskDispatchService);
    }

    @Override
    public void scheduleLoop() {
        long loopStart = System.currentTimeMillis();
        log.info("开始 FIFO 调度周期");
        try {
            List<TaskInstance> pendingTasks = scanPendingTasks(BATCH_SIZE);
            if (pendingTasks.isEmpty()) {
                log.debug("无待调度任务");
                return;
            }
            int successCount = 0;
            int skipCount = 0;
            for (TaskInstance task : pendingTasks) {
                if (scheduleTask(task)) successCount++;
                else skipCount++;
            }
            long elapsed = System.currentTimeMillis() - loopStart;
            log.info("FIFO 调度周期完成 total={} success={} skip={} elapsedMs={}",
                    pendingTasks.size(), successCount, skipCount, elapsed);
        } catch (Exception e) {
            log.error("FIFO 调度周期异常", e);
        }
    }

    @Override
    public boolean scheduleTask(TaskInstance task) {
        if (task == null || task.getId() == null) {
            return false;
        }
        RLock lock = taskScheduleLock.lockFor(task.getId());
        Long reservedUsageId = null;
        long startMs = System.currentTimeMillis();
        try {
            if (!taskScheduleLock.tryAcquire(lock)) {
                log.debug("任务调度锁获取失败，跳过 taskId={}", task.getId());
                return false;
            }
            TaskInstance latest = taskInstanceMapper.selectById(task.getId());
            if (latest == null) {
                log.warn("任务不存在，跳过调度 taskId={}", task.getId());
                return false;
            }
            if (!TaskInstanceStatus.PENDING.matches(latest.getStatus())) {
                log.debug("任务状态非 PENDING，跳过 taskId={} status={}", latest.getId(), latest.getStatus());
                return false;
            }
            if (!checkQuota(latest)) {
                log.debug("任务配额检查未通过，跳过 taskId={}", latest.getId());
                return false;
            }
            ResourceNode selectedNode = selectNode();
            if (selectedNode == null) {
                log.debug("无可用 ONLINE 节点，跳过 taskId={}", latest.getId());
                return false;
            }
            reservedUsageId = reserveResource(latest, selectedNode);
            if (reservedUsageId == null) {
                log.debug("资源预留失败，跳过 taskId={} nodeId={}", latest.getId(), selectedNode.getId());
                return false;
            }
            LocalDateTime now = LocalDateTime.now();
            int updated = taskInstanceMapper.updateStatusWithVersion(
                    latest.getId(),
                    TaskInstanceStatus.PENDING.getCode(),
                    TaskInstanceStatus.RUNNING.getCode(),
                    latest.getVersion() == null ? 0 : latest.getVersion(),
                    selectedNode.getId(),
                    now,
                    now
            );
            if (updated != 1) {
                rollbackReservation(latest, reservedUsageId);
                log.warn("状态流转失败（并发冲突）taskId={} version={}", latest.getId(), latest.getVersion());
                return false;
            }
            if (!submitToExecutor(latest, selectedNode)) {
                rollbackAfterDispatchFailure(latest, reservedUsageId);
                log.warn("提交执行器失败，已回滚 taskId={} nodeId={}", latest.getId(), selectedNode.getId());
                return false;
            }
            long elapsed = System.currentTimeMillis() - startMs;
            log.info("FIFO 任务调度成功 taskId={} nodeId={} elapsedMs={}",
                    latest.getId(), selectedNode.getId(), elapsed);
            return true;
        } catch (Exception e) {
            if (reservedUsageId != null) {
                rollbackReservation(task, reservedUsageId);
            }
            log.error("FIFO 任务调度异常 taskId={}", task.getId(), e);
            return false;
        } finally {
            taskScheduleLock.release(lock);
        }
    }

    @Override
    public List<TaskInstance> scanPendingTasks(int limit) {
        if (limit <= 0) return Collections.emptyList();
        limit = Math.min(limit, BATCH_SIZE);
        try {
            return taskInstanceMapper.selectPendingTasks(limit);
        } catch (Exception e) {
            log.error("扫描待调度任务失败 limit={}", limit, e);
            return Collections.emptyList();
        }
    }

    private ResourceNode selectNode() {
        List<ResourceNode> onlineNodes = resourceNodeMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getStatus, "ONLINE")
                        .orderByAsc(ResourceNode::getId)
        );
        if (onlineNodes == null || onlineNodes.isEmpty()) return null;
        return onlineNodes.get(0);
    }
}

@Slf4j
@Service
@ConditionalOnProperty(name = "scheduler.strategy", havingValue = "priority")
public class PrioritySchedulerServiceImpl extends AbstractSchedulerService implements PrioritySchedulerService {

    private static final double PRIORITY_WEIGHT = 10.0;
    private static final double AGING_WEIGHT = 0.1;
    private static final int BATCH_SIZE = 100;

    public PrioritySchedulerServiceImpl(
            TaskInstanceMapper taskInstanceMapper,
            ResourceNodeMapper resourceNodeMapper,
            ResourceSlotService resourceSlotService,
            ResourceQuotaService resourceQuotaService,
            TaskScheduleLock taskScheduleLock,
            TaskDispatchService taskDispatchService) {
        super(taskInstanceMapper, resourceNodeMapper, resourceSlotService,
                resourceQuotaService, taskScheduleLock, taskDispatchService);
    }

    @Override
    public void scheduleLoop() {
        long loopStart = System.currentTimeMillis();
        try {
            List<TaskWithPriority> tasks = scanPendingTasksWithPriority(BATCH_SIZE);
            if (tasks.isEmpty()) {
                log.debug("无待调度任务");
                return;
            }
            int successCount = 0;
            int skipCount = 0;
            for (TaskWithPriority task : tasks) {
                if (scheduleTask(task.getTask())) successCount++;
                else skipCount++;
            }
            long elapsed = System.currentTimeMillis() - loopStart;
            log.info("优先级调度周期完成 total={} success={} skip={} elapsedMs={}",
                    tasks.size(), successCount, skipCount, elapsed);
        } catch (Exception e) {
            log.error("优先级调度周期异常", e);
        }
    }

    @Override
    public List<TaskWithPriority> scanPendingTasksWithPriority(int limit) {
        try {
            if (limit <= 0) return Collections.emptyList();
            limit = Math.min(limit, BATCH_SIZE);
            List<TaskWithPriority> tasks = taskInstanceMapper.selectPendingTasksWithPriority(
                    limit, PRIORITY_WEIGHT, AGING_WEIGHT);
            if (tasks == null || tasks.isEmpty()) return Collections.emptyList();
            tasks.removeIf(item -> item == null || item.getTask() == null || item.getTask().getId() == null);
            for (TaskWithPriority item : tasks) {
                if (item.getEffectivePriority() == null) item.setEffectivePriority(0.0d);
                if (item.getWaitingMinutes() == null) item.setWaitingMinutes(0L);
                if (item.getPriorityBonus() == null) item.setPriorityBonus(0);
            }
            tasks.sort((a, b) -> Double.compare(
                    b.getEffectivePriority() == null ? 0.0d : b.getEffectivePriority(),
                    a.getEffectivePriority() == null ? 0.0d : a.getEffectivePriority()));
            return tasks;
        } catch (Exception e) {
            log.error("查询优先级待调度任务失败 limit={}", limit, e);
            return Collections.emptyList();
        }
    }

    @Override
    public boolean scheduleTask(TaskInstance taskInstance) {
        if (taskInstance == null || taskInstance.getId() == null) {
            log.warn("无效的任务实例，无法调度 taskInstance={}", taskInstance);
            return false;
        }
        RLock taskLock = taskScheduleLock.lockFor(taskInstance.getId());
        Long reservedUsageId = null;
        try {
            if (!taskScheduleLock.tryAcquire(taskLock)) {
                log.debug("任务调度锁获取失败，跳过 taskId={}", taskInstance.getId());
                return false;
            }
            TaskInstance latest = taskInstanceMapper.selectById(taskInstance.getId());
            if (latest == null) {
                log.warn("任务不存在，跳过调度 taskId={}", taskInstance.getId());
                return false;
            }
            if (!TaskInstanceStatus.PENDING.getCode().equals(latest.getStatus())) {
                log.debug("任务状态非 PENDING，跳过 taskId={} status={}", latest.getId(), latest.getStatus());
                return false;
            }
            if (!checkQuota(latest)) {
                log.debug("任务配额检查未通过，跳过 taskId={}", latest.getId());
                return false;
            }
            ResourceNode selectedNode = selectNode();
            if (selectedNode == null) {
                log.debug("无可用 ONLINE 节点，跳过 taskId={}", latest.getId());
                return false;
            }
            reservedUsageId = reserveResource(latest, selectedNode);
            if (reservedUsageId == null) {
                log.debug("资源预留失败，跳过 taskId={} nodeId={}", latest.getId(), selectedNode.getId());
                return false;
            }
            LocalDateTime now = LocalDateTime.now();
            int updated = taskInstanceMapper.updateStatusWithVersion(
                    latest.getId(),
                    TaskInstanceStatus.PENDING.getCode(),
                    TaskInstanceStatus.RUNNING.getCode(),
                    latest.getVersion() == null ? 0 : latest.getVersion(),
                    selectedNode.getId(),
                    now,
                    now
            );
            if (updated != 1) {
                rollbackReservation(latest, reservedUsageId);
                log.warn("状态流转失败（并发冲突）taskId={} version={}", latest.getId(), latest.getVersion());
                return false;
            }
            if (!submitToExecutor(latest, selectedNode)) {
                rollbackAfterDispatchFailure(latest, reservedUsageId);
                log.warn("提交执行器失败，已回滚 taskId={} nodeId={}", latest.getId(), selectedNode.getId());
                return false;
            }
            log.info("优先级任务调度成功 taskId={} nodeId={} basePriority={}",
                    latest.getId(), selectedNode.getId(), latest.getPriority());
            return true;
        } catch (Exception e) {
            if (reservedUsageId != null) {
                rollbackReservation(taskInstance, reservedUsageId);
            }
            log.error("优先级任务调度异常 taskId={}", taskInstance.getId(), e);
            return false;
        } finally {
            taskScheduleLock.release(taskLock);
        }
    }

    private ResourceNode selectNode() {
        List<ResourceNode> onlineNodes = resourceNodeMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getStatus, "ONLINE")
                        .orderByAsc(ResourceNode::getId)
        );
        if (onlineNodes == null || onlineNodes.isEmpty()) return null;
        return onlineNodes.get(0);
    }
}

@Slf4j
@Service
@ConditionalOnProperty(name = "scheduler.strategy", havingValue = "resource-aware", matchIfMissing = true)
public class ResourceAwareSchedulerServiceImpl extends AbstractSchedulerService implements ResourceAwareSchedulerService {

    private static final int BATCH_SIZE = 100;
    private static final double FIT_SCORE_REJECT = -1.0;
    private static final double PRIORITY_WEIGHT = 10.0;
    private static final double AGING_WEIGHT = 0.1;

    public ResourceAwareSchedulerServiceImpl(
            TaskInstanceMapper taskInstanceMapper,
            ResourceNodeMapper resourceNodeMapper,
            ResourceSlotService resourceSlotService,
            ResourceQuotaService resourceQuotaService,
            TaskScheduleLock taskScheduleLock,
            TaskDispatchService taskDispatchService) {
        super(taskInstanceMapper, resourceNodeMapper, resourceSlotService,
                resourceQuotaService, taskScheduleLock, taskDispatchService);
    }

    /**
     * 调度主循环（Leader 选举由 {@link com.imperium.distributed_lite_scheduler_v1.service.scheduler.SchedulerLoopRunner} 负责）：
     * 1) 扫描待调度任务
     * 2) 查询在线节点并执行 Best Fit 选点
     * 3) 提交单任务调度
     */
    @Override
    public void scheduleLoop() {
        long loopStart = System.currentTimeMillis();
        try {
            List<TaskWithPriority> tasks = scanPendingTasksWithPriority(BATCH_SIZE);
            if (tasks.isEmpty()) {
                log.debug("无待调度任务");
                return;
            }
            // 整轮共享一次节点列表，避免每任务重复查库（原来 100 条 = 100 次全表扫）
            List<ResourceNode> onlineNodes = listOnlineNodes();
            if (onlineNodes.isEmpty()) {
                log.info("当前无在线节点，跳过本轮调度 pendingTasks={}", tasks.size());
                return;
            }
            int successCount = 0;
            int skipCount = 0;
            for (TaskWithPriority twp : tasks) {
                TaskInstance t = twp == null ? null : twp.getTask();
                if (t == null || t.getId() == null) {
                    continue;
                }
                if (scheduleTask(t, onlineNodes)) {
                    successCount++;
                } else {
                    skipCount++;
                }
            }
            long elapsed = System.currentTimeMillis() - loopStart;
            log.info("资源感知调度周期完成 total={} success={} skip={} elapsedMs={}",
                    tasks.size(), successCount, skipCount, elapsed);
        } catch (Exception e) {
            log.error("资源感知调度周期异常", e);
        }
    }

    /**
     * 扫描待调度任务并附带优先级信息。
     */
    @Override
    public List<TaskWithPriority> scanPendingTasksWithPriority(int limit) {
        try {
            if (limit <= 0) {
                return Collections.emptyList();
            }
            limit = Math.min(limit, BATCH_SIZE);
            List<Long> ids = taskInstanceMapper.selectPendingTaskIdsByPriority(limit, PRIORITY_WEIGHT, AGING_WEIGHT);
            if (ids == null || ids.isEmpty()) {
                return Collections.emptyList();
            }
            return buildWithPriorityFromOrderedIds(ids);
        } catch (Exception e) {
            log.error("资源感知：查询待调度任务失败 limit={}", limit, e);
            return Collections.emptyList();
        }
    }

    /**
     * 调度单个任务（对外接口兼容方法，内部单独查询节点列表）。
     * 批量调度场景请优先使用 {@link #scheduleTask(TaskInstance, List)}，避免重复查库。
     */
    @Override
    public boolean scheduleTask(TaskInstance taskInstance) {
        return scheduleTask(taskInstance, listOnlineNodes());
    }

    /**
     * 调度单个任务（复用调用方预加载的在线节点列表，避免每任务重复查库）。
     */
    private boolean scheduleTask(TaskInstance taskInstance, List<ResourceNode> onlineNodes) {
        if (taskInstance == null || taskInstance.getId() == null) {
            log.warn("无效的任务实例，无法调度 taskInstance={}", taskInstance);
            return false;
        }
        RLock taskLock = taskScheduleLock.lockFor(taskInstance.getId());
        try {
            if (!taskScheduleLock.tryAcquire(taskLock)) {
                log.debug("任务调度锁获取失败，跳过 taskId={}", taskInstance.getId());
                return false;
            }
            try {
                TaskInstance latest = taskInstanceMapper.selectById(taskInstance.getId());
                if (latest == null) {
                    log.warn("任务不存在，跳过调度 taskId={}", taskInstance.getId());
                    return false;
                }
                if (!TaskInstanceStatus.PENDING.getCode().equals(latest.getStatus())) {
                    log.debug("任务状态非PENDING，跳过 taskId={} status={}", latest.getId(), latest.getStatus());
                    return false;
                }
                if (!checkQuota(latest)) {
                    log.debug("任务配额检查未通过，跳过 taskId={}", latest.getId());
                    return false;
                }
                ResourceNode best = selectBestNode(latest, onlineNodes);
                if (best == null) {
                    log.debug("无可用BestFit节点，跳过 taskId={}", latest.getId());
                    return false;
                }
                return finalizeDispatch(latest, best);
            } finally {
                taskScheduleLock.release(taskLock);
            }
        } catch (Exception e) {
            log.error("资源感知任务调度异常 taskId={}", taskInstance.getId(), e);
            return false;
        }
    }

    /**
     * 在已通过任务锁与 PENDING/配额校验后，执行预留、乐观锁状态流转与执行器提交。
     */
    private boolean finalizeDispatch(TaskInstance latest, ResourceNode node) {
        Long reservedUsageId = null;
        try {
            reservedUsageId = reserveResource(latest, node);
            if (reservedUsageId == null) {
                return false;
            }
            LocalDateTime now = LocalDateTime.now();
            int updated = taskInstanceMapper.updateStatusWithVersion(
                    latest.getId(),
                    TaskInstanceStatus.PENDING.getCode(),
                    TaskInstanceStatus.RUNNING.getCode(),
                    latest.getVersion() == null ? 0 : latest.getVersion(),
                    node.getId(),
                    now,
                    now
            );
            if (updated != 1) {
                rollbackReservation(latest, reservedUsageId);
                log.warn("状态流转失败（可能并发冲突） taskId={} version={}", latest.getId(), latest.getVersion());
                return false;
            }
            if (!submitToExecutor(latest, node)) {
                rollbackAfterDispatchFailure(latest, reservedUsageId);
                log.warn("提交执行器失败，已回滚 taskId={} nodeId={}", latest.getId(), node.getId());
                return false;
            }
            log.info("资源感知任务调度成功 taskId={} nodeId={} basePriority={}", latest.getId(), node.getId(), latest.getPriority());
            return true;
        } catch (Exception e) {
            if (reservedUsageId != null) {
                rollbackReservation(latest, reservedUsageId);
            }
            log.error("finalizeDispatch 异常 taskId={}", latest.getId(), e);
            return false;
        }
    }

    private List<TaskWithPriority> buildWithPriorityFromOrderedIds(List<Long> ids) {
        List<TaskInstance> rows = taskInstanceMapper.selectByIds(ids);
        if (rows == null || rows.isEmpty()) {
            return Collections.emptyList();
        }
        Map<Long, TaskInstance> byId = new HashMap<>(rows.size() * 2);
        for (TaskInstance row : rows) {
            if (row != null && row.getId() != null) {
                byId.put(row.getId(), row);
            }
        }
        LocalDateTime now = LocalDateTime.now();
        List<TaskWithPriority> out = new ArrayList<>(ids.size());
        for (Long id : ids) {
            if (id == null) {
                continue;
            }
            TaskInstance ti = byId.get(id);
            if (ti == null || !TaskInstanceStatus.PENDING.getCode().equals(ti.getStatus())) {
                continue;
            }
            TaskWithPriority twp = new TaskWithPriority();
            twp.setTask(ti);
            twp.setPriorityBonus(0);
            long waitMinutes = ti.getSubmitTime() == null ? 0L : ChronoUnit.MINUTES.between(ti.getSubmitTime(), now);
            twp.setWaitingMinutes(waitMinutes);
            twp.setEffectivePriority(computeEffectivePriority(ti, now));
            out.add(twp);
        }
        return out;
    }

    private static double computeEffectivePriority(TaskInstance ti, LocalDateTime now) {
        long waitSec = ti.getSubmitTime() == null ? 0L : ChronoUnit.SECONDS.between(ti.getSubmitTime(), now);
        double base = ti.getPriority() == null ? 0.0 : ti.getPriority() / 10.0;
        return PRIORITY_WEIGHT * base + AGING_WEIGHT * (waitSec / 3600.0);
    }

    private List<ResourceNode> listOnlineNodes() {
        List<ResourceNode> onlineNodes = resourceNodeMapper.selectList(
                new LambdaQueryWrapper<ResourceNode>()
                        .eq(ResourceNode::getStatus, "ONLINE")
                        .orderByAsc(ResourceNode::getId)
        );
        return onlineNodes == null ? Collections.emptyList() : onlineNodes;
    }

    // -------------------------------------------------------------------------
    // P3-4 资源感知核心（以下为建议实现顺序：解析 → 可容纳 → 类型匹配 → 综合分 → 选点）
    // -------------------------------------------------------------------------

    /**
     * 解析任务实例上的 resourceRequirement JSON。
     * <p>
     * 说明：与 FIFO/优先级调度器中私有解析类似，但需覆盖 ResourceRequirement 扩展字段
     * （如 {@link com.imperium.distributed_lite_scheduler_v1.constant.NodeType}、excludeNodeIds、
     * gpuModel、minCpuCores、minMemoryMb、preferredNodeId 等），供 canFit / calculateTypeMatch 使用。
     */
    @Override
    protected ResourceRequirement parseRequirement(String requirementJson) {
        if (requirementJson == null || requirementJson.isBlank()) {
            return new ResourceRequirement();
        }
        try {
            JsonNode root = objectMapper.readTree(requirementJson);
            ResourceRequirement requirement = objectMapper.copy()
                    .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false)
                    .configure(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL, true)
                    .treeToValue(root, ResourceRequirement.class);
            if (requirement == null) {
                log.warn("Parsed resource requirement is null, defaulting to zero requirement. json={}", requirementJson);
                return new ResourceRequirement();
            }

            JsonNode nodeTypeNode = root.get("nodeType");
            if (requirement.getNodeType() == null && nodeTypeNode != null && nodeTypeNode.isTextual()) {
                String raw = nodeTypeNode.asText().trim();
                if (!raw.isEmpty()) {
                    try {
                        requirement.setNodeType(NodeType.valueOf(raw.toUpperCase(Locale.ROOT)));
                    } catch (IllegalArgumentException ex) {
                        log.warn("Unknown nodeType '{}' in resource requirement JSON, ignoring. json={}", raw, requirementJson);
                    }
                }
            }

            double cpu = requirement.getCpu() != null ? Math.max(0.0, requirement.getCpu()) : 0.0;
            requirement.setCpu(cpu);
            long memoryMb = requirement.getMemoryMb() != null ? Math.max(0L, requirement.getMemoryMb()) : 0L;
            requirement.setMemoryMb(memoryMb);
            int gpu = requirement.getGpu() != null ? Math.max(0, requirement.getGpu()) : 0;
            requirement.setGpu(gpu);

            Integer minCpu = requirement.getMinCpuCores();
            if (minCpu != null) {
                requirement.setMinCpuCores(Math.max(0, minCpu));
            }
            Long minMem = requirement.getMinMemoryMb();
            if (minMem != null) {
                requirement.setMinMemoryMb(Math.max(0L, minMem));
            }

            String gpuModel = requirement.getGpuModel();
            if (gpuModel != null) {
                String trimmed = gpuModel.trim();
                requirement.setGpuModel(trimmed.isEmpty() ? null : trimmed);
            }

            if (requirement.getTags() == null) {
                requirement.setTags(Collections.emptyList());
            }
            if (requirement.getExcludeNodeIds() == null) {
                requirement.setExcludeNodeIds(Collections.emptyList());
            }

            return requirement;
        } catch (Exception e) {
            log.warn("资源需求JSON解析失败，按零需求处理 json={}", requirementJson, e);
            return new ResourceRequirement();
        }
    }

    /**
     * 判断单个节点是否<strong>硬性</strong>满足任务资源需求（不满足则根本不应进入打分）。
     */
    private boolean canFit(ResourceNode node, ResourceRequirement requirement) {
        // 业务逻辑（注释备忘）：
        // 1) node 为 null：返回 false。
        // 2) 节点状态：仅允许 ONLINE（或你项目约定的可用状态）；MAINTENANCE/OFFLINE 直接 false。
        // 3) CPU：availableCpu >= 需求 CPU（需求取自 requirement，注意 Double/Long 与 int 转换及 Math.max(0, ...)）。
        // 4) 内存：availableMemoryMb >= 需求 memoryMb。
        // 5) GPU：若需求 gpu > 0，则 availableGpu >= 需求；若需求 gpu == 0，可按策略仍要求节点有 GPU 或不要求（通常不要求）。
        // 6) 节点类型（可选扩展）：若 requirement 指定了 nodeType，则 node.getNodeType() 字符串需与之兼容（完全相等或允许 MIXED 等规则）。
        // 7) gpuModel（可选）：若 requirement 填了 gpuModel，节点 gpuModel 需匹配（忽略大小写或精确匹配由你约定）。
        // 8) minCpuCores / minMemoryMb（可选）：节点 total 或 available 是否不低于「最小节点规格」，与设计稿一致即可。
        // 9) excludeNodeIds：若当前 node.getId() 在排除列表中，返回 false。
        // 10) tags / NodeAffinity（若后续任务参数里单独挂亲和对象）：requiredTags 必须全部命中节点 labels；excludedTags 命中则 false——可先 TODO，仅注释占位。
        if (node == null || requirement == null) {
            return false;
        }
        if (!"ONLINE".equals(node.getStatus())) {
            return false;
        }
        double cpuNeed = requirement.getCpu() != null ? requirement.getCpu() : 0.0;
        int needCpuCores = (int) Math.ceil(Math.max(0.0, cpuNeed));
        long needMemoryMb = requirement.getMemoryMb() != null ? Math.max(0L, requirement.getMemoryMb()) : 0L;
        int needGpu = requirement.getGpu() != null ? Math.max(0, requirement.getGpu()) : 0;

        Integer availableCpu = node.getAvailableCpu();
        Integer availableMemoryMb = node.getAvailableMemoryMb();
        Integer availableGpu = node.getAvailableGpu();
        if (availableCpu == null || availableMemoryMb == null || availableGpu == null) {
            return false;
        }
        if (availableCpu < needCpuCores || availableMemoryMb < needMemoryMb) {
            return false;
        }
        if (needGpu > 0 && availableGpu < needGpu) {
            return false;
        }
        if (!hardConstraintNodeType(node, requirement)) {
            return false;
        }
        String reqGpuModel = requirement.getGpuModel();
        if (reqGpuModel != null && !reqGpuModel.isEmpty()) {
            String nodeGpuModel = node.getGpuModel();
            if (nodeGpuModel == null || !reqGpuModel.equalsIgnoreCase(nodeGpuModel.trim())) {
                return false;
            }
        }
        Integer minCpuCores = requirement.getMinCpuCores();
        if (minCpuCores != null && minCpuCores > 0) {
            Integer totalCpu = node.getTotalCpu();
            if (totalCpu == null || totalCpu < minCpuCores) {
                return false;
            }
        }
        Long minNodeMemoryMb = requirement.getMinMemoryMb();
        if (minNodeMemoryMb != null && minNodeMemoryMb > 0) {
            Integer totalMemoryMb = node.getTotalMemoryMb();
            if (totalMemoryMb == null || totalMemoryMb.longValue() < minNodeMemoryMb) {
                return false;
            }
        }
        Long nodeId = node.getId();
        if (nodeId != null && requirement.getExcludeNodeIds() != null) {
            for (Long excludedId : requirement.getExcludeNodeIds()) {
                if (excludedId != null && excludedId.equals(nodeId)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * 计算节点类型与任务需求的匹配度，供综合打分中的「异构匹配」项使用。
     * <p>
     * 返回值语义建议：越高越匹配（例如 0.0 ~ 1.0），具体区间与 calculateFitScore 内权重保持一致。
     */
    private double calculateTypeMatch(ResourceNode node, ResourceRequirement requirement) {
        // 业务逻辑（注释备忘，对齐设计稿 3.3 / 4.1）：
        // 1) 从 node.getNodeType() 解析为 NodeType 枚举（CPU/GPU/MIXED）；解析失败时的默认分（如 0.5 或 0）自行约定。
        // 2) 若任务需求 gpu > 0（GPU 任务）：
        //    - 节点 GPU → 1.0；MIXED → 0.5；CPU → 0.0（或更小）。
        // 3) 若任务需求 gpu == 0（CPU 为主任务）：
        //    - 节点 CPU → 1.0；MIXED → 0.8；GPU → 0.3（可用 GPU 跑 CPU 但不推荐）。
        // 4) 若 requirement 显式指定了 nodeType：可与上述规则组合（例如硬约束已在 canFit 处理，这里只做软分微调）。
        if (node == null || requirement == null) {
            return 0.0;
        }
        NodeType nodeKind = parseNodeTypeFromString(node.getNodeType());
        double base;
        if (nodeKind == null) {
            base = 0.5;
        } else {
            int needGpu = requirement.getGpu() != null ? Math.max(0, requirement.getGpu()) : 0;
            if (needGpu > 0) {
                base = switch (nodeKind) {
                    case GPU -> 1.0;
                    case MIXED -> 0.5;
                    case CPU -> 0.0;
                };
            } else {
                base = switch (nodeKind) {
                    case CPU -> 1.0;
                    case MIXED -> 0.8;
                    case GPU -> 0.3;
                };
            }
        }
        NodeType explicit = requirement.getNodeType();
        if (explicit != null && nodeKind == explicit) {
            base = Math.min(1.0, base + 0.1);
        }
        return base;
    }

    private static NodeType parseNodeTypeFromString(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        try {
            return NodeType.valueOf(raw.trim().toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ex) {
            return null;
        }
    }

    private static boolean hardConstraintNodeType(ResourceNode node, ResourceRequirement requirement) {
        NodeType required = requirement.getNodeType();
        if (required == null) {
            return true;
        }
        NodeType actual = parseNodeTypeFromString(node.getNodeType());
        if (actual == null) {
            return false;
        }
        return switch (required) {
            case CPU -> actual == NodeType.CPU || actual == NodeType.MIXED;
            case GPU -> actual == NodeType.GPU || actual == NodeType.MIXED;
            case MIXED -> actual == NodeType.MIXED;
        };
    }

    /**
     * 计算节点与任务的<strong>综合匹配分</strong>：分数越高越优先被选为 Best Fit。
     * <p>
     * 约定：若节点不可能运行该任务（等同于 canFit 为 false），应返回负数（如 -1），方便调用方统一过滤。
     */
    private double calculateFitScore(ResourceNode node, TaskInstance task) {
        // 业务逻辑（注释备忘，对齐设计稿多维评分）：
        // 1) 调用 parseRequirement(task.getResourceRequirement()) 得到 req。
        // 2) 若 !canFit(node, req)：返回 -1（或统一常量 FIT_SCORE_REJECT）。
        // 3) 浪费率 waste（CPU/内存/GPU 维度）：
        //    - cpuWaste = (availableCpu - needCpu) / totalCpu（注意 total 为 0 时避免除零）。
        //    - 同理 memWaste、gpuWaste（totalGpu 为 0 且需求 gpu==0 时可令 gpuWaste=0）。
        //    - wasteScore = cpuWaste * wCpu + memWaste * wMem + gpuWaste * wGpu（权重如 0.4 / 0.3 / 0.3）。
        // 4) 负载因子 loadFactor：
        //    - 可用「1 - 当前负载率」；负载率可用 (totalCpu - availableCpu)/totalCpu，或用节点额外字段若后续有。
        // 5) typeMatch = calculateTypeMatch(node, req)。
        // 6) 综合：例如 (1 - wasteScore) * 0.5 + loadFactor * 0.3 + typeMatch * 0.2（权重与设计稿一致可调）。
        // 7) 可选加分：preferredNodeId 与 node.getId() 一致时增加小幅 bonus。
        // 8) 确保返回值落在合理区间或至少保证「候选节点之间可比」；打 debug 日志时可输出各子项便于调参。
        if (node == null || task == null) {
            return FIT_SCORE_REJECT;
        }
        ResourceRequirement req = parseRequirement(task.getResourceRequirement());
        if (!canFit(node, req)) {
            return FIT_SCORE_REJECT;
        }
        double cpuNeed = req.getCpu() != null ? req.getCpu() : 0.0;
        int needCpu = (int) Math.ceil(Math.max(0.0, cpuNeed));
        long needMemMb = req.getMemoryMb() != null ? Math.max(0L, req.getMemoryMb()) : 0L;
        int needGpu = req.getGpu() != null ? Math.max(0, req.getGpu()) : 0;

        int availCpu = node.getAvailableCpu();
        int availMemMb = node.getAvailableMemoryMb();
        int availGpu = node.getAvailableGpu();

        Integer totalCpu = node.getTotalCpu();
        Integer totalMemMb = node.getTotalMemoryMb();
        Integer totalGpu = node.getTotalGpu();

        double cpuWaste = 0.0;
        if (totalCpu != null && totalCpu > 0) {
            cpuWaste = (double) (availCpu - needCpu) / totalCpu;
            cpuWaste = Math.max(0.0, Math.min(1.0, cpuWaste));
        }
        double memWaste = 0.0;
        if (totalMemMb != null && totalMemMb > 0) {
            memWaste = (double) (availMemMb - needMemMb) / totalMemMb;
            memWaste = Math.max(0.0, Math.min(1.0, memWaste));
        }
        double gpuWaste = 0.0;
        if (needGpu > 0 && totalGpu != null && totalGpu > 0) {
            gpuWaste = (double) (availGpu - needGpu) / totalGpu;
            gpuWaste = Math.max(0.0, Math.min(1.0, gpuWaste));
        }

        final double wCpu = 0.4;
        final double wMem = 0.3;
        final double wGpu = 0.3;
        double wasteScore = cpuWaste * wCpu + memWaste * wMem + gpuWaste * wGpu;
        wasteScore = Math.max(0.0, Math.min(1.0, wasteScore));

        double loadFactor;
        if (totalCpu != null && totalCpu > 0) {
            loadFactor = (double) availCpu / totalCpu;
            loadFactor = Math.max(0.0, Math.min(1.0, loadFactor));
        } else {
            loadFactor = 1.0;
        }

        double typeMatch = calculateTypeMatch(node, req);
        double score = (1.0 - wasteScore) * 0.5 + loadFactor * 0.3 + typeMatch * 0.2;

        Long preferred = req.getPreferredNodeId();
        Long nodeId = node.getId();
        if (preferred != null && nodeId != null && preferred.equals(nodeId)) {
            score += 0.05;
        }

        log.debug(
                "fitScore taskId={} nodeId={} cpuWaste={} memWaste={} gpuWaste={} wasteScore={} loadFactor={} typeMatch={} finalScore={}",
                task.getId(), nodeId, cpuWaste, memWaste, gpuWaste, wasteScore, loadFactor, typeMatch, score);
        return score;
    }

    /**
     * Best Fit：在候选节点列表中选出<strong>综合匹配分最高</strong>的一个节点。
     */
    private ResourceNode selectBestNode(TaskInstance task, List<ResourceNode> nodes) {
        // 业务逻辑（注释备忘）：
        // 1) task 为 null 或 task.getId() 为 null：返回 null。
        // 2) nodes 为 null 或空：返回 null。
        // 3) 遍历 nodes，对每个 node 调用 calculateFitScore(node, task)。
        // 4) 跳过得分 < 0（或 FIT_SCORE_REJECT）的节点。
        // 5) 在剩余候选中取最高分节点；若并列：可用 nodeId 升序打破平局，或 secondary 比较浪费度更小者。
        // 6) 若无一候选：返回 null；可选 debug 日志打印 taskId 与 requirement 摘要。
        // 7) 性能注意：后续可加并行流或缓存在线节点列表（设计稿 7.x），当前先保证语义正确。
        if (task == null || task.getId() == null) {
            return null;
        }
        if (nodes == null || nodes.isEmpty()) {
            return null;
        }
        ResourceNode best = null;
        double bestScore = FIT_SCORE_REJECT;
        for (ResourceNode node : nodes) {
            if (node == null) {
                continue;
            }
            double score = calculateFitScore(node, task);
            if (score < 0) {
                continue;
            }
            if (best == null || score > bestScore
                    || (Double.compare(score, bestScore) == 0 && lowerNodeIdWins(node, best))) {
                best = node;
                bestScore = score;
            }
        }
        if (best == null) {
            ResourceRequirement rq = parseRequirement(task.getResourceRequirement());
            log.debug("无可用BestFit节点 taskId={} cpu={} memMb={} gpu={}", task.getId(), rq.getCpu(), rq.getMemoryMb(), rq.getGpu());
        }
        return best;
    }

    private static boolean lowerNodeIdWins(ResourceNode candidate, ResourceNode incumbent) {
        Long cid = candidate.getId();
        Long iid = incumbent.getId();
        if (cid == null || iid == null) {
            return false;
        }
        return cid < iid;
    }
}

package com.imperium.distributed_lite_scheduler_v1.service.workflow.annotation;

import java.lang.annotation.*;

/**
 * 工作流权限检查注解
 * 
 * 用于标记需要权限检查的方法
 * 该注解与AOP结合使用，在方法执行前自动进行权限验证
 * 
 * 示例：
 * @RequireWorkflowPermission(roles = {"OWNER", "ADMIN"}, message = "当前角色无操作权限")
 * public void updateWorkflow(...) { }
 * 
 * @author UNSC
 * @since 2026-05-12
 */
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
@Documented
public @interface RequireWorkflowPermission {

    /**
     * 允许的角色集合
     */
    String[] roles() default {};

    /**
     * 权限不足时的错误消息
     */
    String message() default "当前角色无权限执行此操作";

    /**
     * 为 true 时，在鉴权通过后校验首参数对应的项目属于当前租户：
     * {@link com.imperium.distributed_lite_scheduler_v1.model.dto.workflow.WorkflowCreateRequest#getProjectId()}；
     * 或方法名为 {@code listWorkflows} 时首参数 {@code Long projectId}。
     */
    boolean validateProject() default false;
}

@Aspect
@Component
@Slf4j
public class WorkflowSecurityAspect {

    private static final int NOT_DELETED = 0;

    @Autowired
    private TenantAccessGuard tenantAccessGuard;

    @Autowired
    private ProjectMapper projectMapper;

    @Pointcut("@annotation(com.imperium.distributed_lite_scheduler_v1.service.workflow.annotation.RequireWorkflowPermission)")
    public void requireWorkflowPermission() {
    }

    @Around("requireWorkflowPermission()")
    public Object checkPermissionAndExecute(ProceedingJoinPoint pjp) throws Throwable {
        MethodSignature signature = (MethodSignature) pjp.getSignature();
        Method method = signature.getMethod();
        RequireWorkflowPermission permission = method.getAnnotation(RequireWorkflowPermission.class);

        Set<String> roles = permission.roles().length > 0 ? Set.of(permission.roles()) : Set.of();
        Result<TenantAccessGuard.AccessContext> access = tenantAccessGuard.requireTenantMember(
                roles, permission.message());
        if (!access.isSuccess()) {
            log.warn("工作流权限拒绝 method={} reason={}", method.getName(), access.getMessage());
            throw new IllegalArgumentException(access.getMessage());
        }

        TenantAccessGuard.AccessContext ctx = access.getData();
        validateProjectIfNeeded(pjp, method, permission, ctx);

        WorkflowSecurityContextHolder.set(ctx);
        try {
            return pjp.proceed();
        } finally {
            WorkflowSecurityContextHolder.clear();
        }
    }

    private void validateProjectIfNeeded(
            ProceedingJoinPoint pjp,
            Method method,
            RequireWorkflowPermission permission,
            TenantAccessGuard.AccessContext ctx) {
        if (!permission.validateProject()) {
            return;
        }
        Object[] args = pjp.getArgs();
        if (args.length == 0) {
            return;
        }
        Long projectId = null;
        if (args[0] instanceof WorkflowCreateRequest req) {
            projectId = req.getProjectId();
        } else if (args[0] instanceof Long && "listWorkflows".equals(method.getName())) {
            projectId = (Long) args[0];
        }
        if (projectId == null) {
            throw new IllegalArgumentException("项目ID不能为空");
        }
        Long tenantId = ctx.principal().tenantId();
        Project project = projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, projectId)
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
        if (project == null) {
            throw new IllegalArgumentException("项目不存在");
        }
    }

    @AfterThrowing(
            pointcut = "execution(* com.imperium.distributed_lite_scheduler_v1.service.workflow.impl.WorkflowServiceImpl.*(..))",
            throwing = "exception"
    )
    public void handleWorkflowException(Exception exception) {
        if (exception instanceof IllegalArgumentException) {
            log.warn("工作流操作验证失败: {}", exception.getMessage());
        } else if (exception instanceof IllegalStateException) {
            log.error("工作流操作状态异常: {}", exception.getMessage());
        } else {
            log.error("工作流操作出现意外异常", exception);
        }
    }
}

@Component
@Slf4j
public class DistributedWorkflowCacheManager {
    
    /**
     * Redis 缓存 key 前缀
     */
    private static final String CACHE_KEY_PREFIX = "workflow:execution:plan:";
    
    /**
     * 缓存失效通知的 Pub/Sub channel
     */
    private static final String INVALIDATE_CHANNEL = "workflow:execution:plan:invalidate";
    
    /**
     * Redis 中缓存的 TTL（30分钟）
     */
    private static final long REDIS_TTL_SECONDS = 1800;
    
    @Autowired
    private RedissonClient redissonClient;
    
    @Autowired
    private ObjectMapper objectMapper;
    
    /**
     * L1 本地缓存：Caffeine
     * 配置参数：
     * - 最大容量：500 个工作流
     * - 写入后过期：30 分钟
     * - 统计信息：记录缓存命中率等
     * -- GETTER --
     *  获取本地缓存对象本身（供监听器和外部使用）
     *
     * @return Caffeine 本地缓存对象

     */
    @Getter
    private final Cache<Long, WorkflowExecutionPlan> localCache =
        Caffeine.newBuilder()
            .maximumSize(500)
            .expireAfterWrite(30, TimeUnit.MINUTES)
            .recordStats()
            .build();
    
    /**
     * 从分布式缓存读取执行计划
     * 
     * 流程：
     * 1. 先查 L1 本地缓存（Caffeine）- 最快
     * 2. 未命中则查 L2 Redis - 快速，跨实例共享
     * 3. 都未命中则调用 loader 从数据库加载，并双写入缓存
     * 
     * @param workflowId 工作流 ID
     * @param loader 数据库加载函数（从工作流 ID 返回执行计划）
     * @return 执行计划对象
     */
    public WorkflowExecutionPlan getExecutionPlan(
            Long workflowId,
            Function<Long, WorkflowExecutionPlan> loader) {

        if (workflowId == null) {
            throw new IllegalArgumentException("工作流 ID 不能为空");
        }

        // 使用 Caffeine 的 get(key, mappingFunction) 而非 getIfPresent()。
        // 区别：同一个 key 并发时只有一个线程执行 mappingFunction，其他线程等待并复用结果，
        // 消灭进程内缓存击穿（原先 1000 个并发全部穿透到下游）。
        return localCache.get(workflowId, id -> loadFromRedisOrDb(id, loader));
    }

    /**
     * L1 miss 后的加载链：L2 Redis → DB，加载成功后双写回 L1+L2。
     * 此方法在 Caffeine per-key 锁内执行，单 JVM 内不会并发。
     * 跨 JVM 的并发穿透由 Redis 的最终一致性承担（多次 DB 加载结果相同，可接受）。
     */
    private WorkflowExecutionPlan loadFromRedisOrDb(Long workflowId, Function<Long, WorkflowExecutionPlan> loader) {
        // 第一步：尝试从 L2 Redis 获取
        String redisKey = CACHE_KEY_PREFIX + workflowId;
        try {
            RBucket<Object> bucket = redissonClient.getBucket(redisKey);
            Object cached = bucket.get();
            if (cached != null) {
                try {
                    WorkflowExecutionPlan plan = objectMapper.readValue(
                            objectMapper.writeValueAsString(cached),
                            WorkflowExecutionPlan.class);
                    log.debug("缓存命中：L2 Redis缓存 workflowId={}", workflowId);
                    return plan;
                } catch (Exception e) {
                    log.warn("反序列化 Redis 缓存失败，继续查询数据库 workflowId={}", workflowId, e);
                }
            }
        } catch (Exception e) {
            log.warn("访问 Redis 缓存异常，继续查询数据库 workflowId={}", workflowId, e);
        }

        // 第二步：缓存未命中，从数据库加载
        log.debug("缓存未命中，从数据库加载 workflowId={}", workflowId);
        WorkflowExecutionPlan plan = loader.apply(workflowId);

        // 第三步：回填 L2 Redis（L1 由 Caffeine.get() 在返回后自动填充）
        if (plan != null) {
            putToRedis(workflowId, plan);
            log.info("数据库加载并写入 L2 缓存成功 workflowId={}", workflowId);
        }

        return plan;
    }
    
    /**
     * 写入 Redis 缓存
     * 
     * @param workflowId 工作流 ID
     * @param plan 执行计划对象
     */
    private void putToRedis(Long workflowId, WorkflowExecutionPlan plan) {
        if (plan == null) {
            return;
        }
        
        try {
            String redisKey = CACHE_KEY_PREFIX + workflowId;
            String json = objectMapper.writeValueAsString(plan);
            RBucket<String> bucket = redissonClient.getBucket(redisKey);
            // Redisson RBucket：使用新的 set 方法（替代废弃的方法）
            bucket.set(json, java.time.Duration.ofSeconds(REDIS_TTL_SECONDS));
            log.debug("写入 Redis 缓存成功 workflowId={}", workflowId);
        } catch (Exception e) {
            log.error("写入 Redis 缓存失败，但不影响业务流程 workflowId={}", workflowId, e);
            // Redis 写入失败不影响业务，继续执行
        }
    }
    
    /**
     * 分布式缓存失效（跨实例协调）
     * 
     * 执行步骤：
     * 1. 清除本实例的 L1 本地缓存
     * 2. 清除 Redis L2 分布式缓存
     * 3. 发布 Pub/Sub 失效通知，其他实例接收后清除各自的 L1 缓存
     * 
     * 这样保证了在分布式环境中，所有实例的缓存都能及时失效。
     * 
     * @param workflowId 要失效的工作流 ID
     */
    public void invalidateExecutionPlan(Long workflowId) {
        if (workflowId == null) {
            return;
        }
        
        log.info("开始分布式缓存失效 workflowId={}", workflowId);
        
        try {
            // 步骤1：清除本实例的 L1 本地缓存
            localCache.invalidate(workflowId);
            log.debug("已清除 L1 本地缓存 workflowId={}", workflowId);
            
            // 步骤2：清除 Redis L2 分布式缓存
            String redisKey = CACHE_KEY_PREFIX + workflowId;
            redissonClient.getBucket(redisKey).delete();
            log.debug("已清除 L2 Redis 缓存 workflowId={}", workflowId);
            
            // 步骤3：发布失效通知（Pub/Sub）
            // 其他实例监听此 channel，收到消息后清除各自的 L1 缓存
            RTopic topic = redissonClient.getTopic(INVALIDATE_CHANNEL);
            topic.publish(workflowId);
            log.info("已发布缓存失效通知 workflowId={}", workflowId);
            
        } catch (Exception e) {
            log.error("分布式缓存失效过程中出现异常，但不影响业务继续执行 workflowId={}", workflowId, e);
            // 缓存失效异常不影响业务流程
        }
    }
    
    /**
     * 获取本地缓存统计信息（用于监控和调试）
     * 
     * @return 缓存统计信息字符串，包含：
     *         - 缓存命中数
     *         - 缓存未命中数
     *         - 命中率百分比
     */
    public String getCacheStats() {
        return String.format(
            "WorkflowExecutionPlan缓存统计 - %s",
            localCache.stats().toString()
        );
    }

    /**
     * 获取本地缓存中指定工作流的执行计划（仅用于测试和调试）
     * 
     * @param workflowId 工作流 ID
     * @return 缓存中的执行计划，如果未缓存则返回 null
     */
    public WorkflowExecutionPlan getFromLocalCache(Long workflowId) {
        return localCache.getIfPresent(workflowId);
    }
    
    /**
     * 清空所有本地缓存（危险操作，仅用于测试）
     */
    public void clearLocalCache() {
        localCache.invalidateAll();
        log.warn("已清空所有本地缓存（仅用于测试）");
    }
}

@Component
@Slf4j
public class WorkflowCacheInvalidationListener {
    
    /**
     * 缓存失效通知的 Pub/Sub channel（与 CacheManager 保持一致）
     */
    private static final String INVALIDATE_CHANNEL = "workflow:execution:plan:invalidate";
    
    @Autowired
    private DistributedWorkflowCacheManager cacheManager;
    
    @Autowired
    private RedissonClient redissonClient;
    
    /**
     * 在 Spring 容器启动完成后注册 Pub/Sub 监听器
     * 
     * 这样确保：
     * 1. RedissonClient 已初始化
     * 2. cacheManager 已注入
     * 3. 监听器在应用启动时立即激活
     */
    @PostConstruct
    public void subscribeToCacheInvalidation() {
        try {
            RTopic topic = redissonClient.getTopic(INVALIDATE_CHANNEL);
            
            // 注册监听器：接收 Long 类型的消息（工作流 ID）
            topic.addListener(Long.class, (channel, workflowId) -> {
                log.info("收到跨实例缓存失效通知 channel={} workflowId={}", channel, workflowId);
                handleCacheInvalidationMessage(workflowId);
            });
            
            log.info("工作流缓存失效通知监听器已启动 channel={}", INVALIDATE_CHANNEL);
        } catch (Exception e) {
            log.error("启动缓存失效通知监听器失败", e);
            throw new RuntimeException("缓存失效通知监听器初始化失败", e);
        }
    }
    
    /**
     * 处理缓存失效通知消息
     * 
     * 当其他实例发布缓存失效通知时，本实例接收到工作流 ID，
     * 然后清除本地缓存中对应的执行计划。
     * 
     * 注意：
     * - Redis L2 缓存已由发起失效的实例清除，无需再清
     * - 只需清除本实例的 L1 本地缓存（Caffeine）
     * 
     * @param workflowId 要失效的工作流 ID
     */
    private void handleCacheInvalidationMessage(Long workflowId) {
        if (workflowId == null) {
            log.warn("接收到 null 的工作流 ID，忽略处理");
            return;
        }
        
        try {
            // 从本实例的 L1 本地缓存中移除对应的执行计划
            // Redis L2 缓存由发起实例已清除，无需处理
            cacheManager.getLocalCache().invalidate(workflowId);
            log.info("已清除本实例的本地缓存 workflowId={}", workflowId);
        } catch (Exception e) {
            log.error("处理缓存失效通知时出现异常 workflowId={}", workflowId, e);
            // 即使处理失败也不中断，缓存会在 30 分钟后自动过期
        }
    }
}

@Service
@Slf4j
@RequiredArgsConstructor
public class ConditionContextBuilder {

    private static final TypeReference<Map<String, Object>> MAP_TYPE =
            new TypeReference<>() {};

    private final WorkflowInstanceMapper workflowInstanceMapper;
    private final WorkflowTaskInstanceMapper workflowTaskInstanceMapper;
    private final ObjectMapper objectMapper;

    /**
     * 为指定工作流实例构建一份可用于 SpEL 的上下文快照。
     */
    public ConditionContext buildContext(Long workflowInstanceId) {
        if (workflowInstanceId == null) {
            throw new IllegalArgumentException("workflowInstanceId must not be null");
        }

        WorkflowInstance instance = workflowInstanceMapper.selectById(workflowInstanceId);
        if (instance == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + workflowInstanceId);
        }

        ConditionContext ctx = new ConditionContext();
        ctx.setTasks(collectTerminalTaskResults(workflowInstanceId));
        ctx.setContext(parseInstanceContext(instance.getContextJson()));
        ctx.setSystem(buildSystem(instance));
        return ctx;
    }

    private Map<String, Object> parseInstanceContext(String contextJson) {
        if (!StringUtils.hasText(contextJson)) {
            return new LinkedHashMap<>();
        }
        try {
            Map<String, Object> m =
                    objectMapper.readValue(contextJson.trim(), MAP_TYPE);
            return m != null ? new LinkedHashMap<>(m) : new LinkedHashMap<>();
        } catch (Exception e) {
            log.warn("解析实例 context_json 失败，将作为空上下文处理 workflowInstanceJsonLen={}", Optional.of(contextJson.length()), e);
            return new LinkedHashMap<>();
        }
    }

    private Map<String, Object> buildSystem(WorkflowInstance instance) {
        Map<String, Object> system = new LinkedHashMap<>();
        system.put("workflowInstanceId", instance.getId());
        system.put("currentTime", LocalDateTime.now());
        system.put("workflowId", instance.getWorkflowId());
        system.put("tenantId", instance.getTenantId());
        return system;
    }

    /**
     * 仅聚合已<strong>结束</strong>的节点结果；未结束的节点不出现在 {@code tasks} 中，
     * 便于表达式用存在性判断是否已跑出结果。
     */
    private Map<String, TaskResult> collectTerminalTaskResults(Long workflowInstanceId) {
        List<WorkflowTaskInstance> rows =
                workflowTaskInstanceMapper.selectByInstanceId(workflowInstanceId);
        Map<String, TaskResult> tasks = new HashMap<>();

        for (WorkflowTaskInstance wti : rows) {
            TaskInstanceStatus status = parseStoredStatus(wti.getStatus());
            if (status == null || !status.isTerminal()) {
                continue;
            }
            TaskResult tr = new TaskResult();
            tr.setStatus(status.getCode());
            tr.setExitCode(wti.getExitCode());
            if (wti.getDurationSeconds() != null) {
                tr.setDurationSeconds(Long.valueOf(wti.getDurationSeconds().longValue()));
            }
            tr.setOutput(parseOutputMap(wti.getOutput()));
            tasks.put(wti.getTaskName(), tr);
        }
        return tasks;
    }

    private TaskInstanceStatus parseStoredStatus(String code) {
        if (!StringUtils.hasText(code)) {
            return null;
        }
        try {
            return TaskInstanceStatus.fromCode(code);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    private Map<String, Object> parseOutputMap(String output) {
        if (!StringUtils.hasText(output)) {
            return new LinkedHashMap<>();
        }
        String raw = output.trim();
        try {
            if (raw.startsWith("{")) {
                Map<String, Object> parsed = objectMapper.readValue(raw, MAP_TYPE);
                return parsed != null ? new LinkedHashMap<>(parsed) : new LinkedHashMap<>();
            }
        } catch (Exception e) {
            log.trace("workflow_task_instance.output 非 JSON object，将作为 raw 键保留 taskBodyLen={}",
                    Optional.of(raw.length()), e);
        }
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("raw", raw);
        return body;
    }
}

@Service
@Slf4j
public class ConditionEvaluator {

    private static final Pattern TYPE_REF_T = Pattern.compile("(?<![\\w$])T\\(");

    private final SpelExpressionParser parser = new SpelExpressionParser();
    private final ConcurrentMap<String, Expression> parsedCache = new ConcurrentHashMap<>();

    /**
     * 判断依赖边条件是否成立。
     *
     * @param conditionExpr null 或空白表示恒为 true
     */
    public boolean evaluate(String conditionExpr, ConditionContext context) {
        if (!StringUtils.hasText(conditionExpr)) {
            return true;
        }
        assertSafeExpression(conditionExpr);
        String normalized = normalizeExpression(conditionExpr.trim());
        long t0 = System.nanoTime();
        try {
            SimpleEvaluationContext evalContext =
                    SimpleEvaluationContext.forReadOnlyDataBinding().build();
            evalContext.setVariable("tasks", context.getTasks());
            evalContext.setVariable("context", context.getContext());
            evalContext.setVariable("system", context.getSystem());

            Expression exp = parsedCache.computeIfAbsent(normalized, parser::parseExpression);
            Object value = exp.getValue(evalContext);
            boolean result = coerceToBoolean(value);
            if (log.isDebugEnabled()) {
                log.debug(
                        "P4-4 SpEL evaluated instanceContext in {}ms result={} expr={}",
                        (System.nanoTime() - t0) / 1_000_000,
                        result,
                        truncateForLog(normalized));
            }
            return result;
        } catch (Exception e) {
            log.warn(
                    "P4-4 条件求值失败，按 false 处理: expr={}",
                    truncateForLog(normalized),
                    e);
            return false;
        }
    }

    /**
     * 校验表达式语法（解析即可）；用于 DAG 保存时快速失败。
     */
    public void validateSyntax(String conditionExpr) {
        if (!StringUtils.hasText(conditionExpr)) {
            return;
        }
        assertSafeExpression(conditionExpr);
        String normalized = normalizeExpression(conditionExpr.trim());
        try {
            parser.parseExpression(normalized);
        } catch (ParseException e) {
            throw new IllegalArgumentException(
                    "条件表达式语法无效: " + truncateForLog(normalized), e);
        }
    }

    /** 兼容占位符写法 {@code ${ #tasks['a'].status }}
     * ，去掉最外层 {@code ${...}} 后 trimmed。 */
    private static String normalizeExpression(String expr) {
        String e = expr.trim();
        if (e.startsWith("${") && e.endsWith("}") && e.length() > 3) {
            return e.substring(2, e.length() - 1).trim();
        }
        return e;
    }

    /**
     * 阻断常见高风险 SpEL 片段（不改变合法 {@code #tasks[...]} 访问）。
     */
    private static void assertSafeExpression(String expr) {
        String lower = expr.toLowerCase(Locale.ROOT);
        if (expr.contains("\n") || expr.contains("\r")) {
            throw new IllegalArgumentException("条件表达式不允许换行");
        }
        // 不允许 SpEL 类型引用 T(com.foo.Bar)
        if (TYPE_REF_T.matcher(expr).find()) {
            throw new IllegalArgumentException(
                    "条件表达式不允许类型引用语法 T(...)，请仅用 #tasks / #context / #system");
        }
        if (expr.contains("@")) {
            throw new IllegalArgumentException("条件表达式不允许 @Bean 引用");
        }
        if (lower.contains(".getclass(")) {
            throw new IllegalArgumentException("条件表达式不允许反射类探测");
        }
        if (lower.contains("runtime") && lower.matches(".*java\\.lang\\.runtime.*")) {
            throw new IllegalArgumentException("条件表达式不安全");
        }
        if (lower.contains(" new ")) {
            throw new IllegalArgumentException("条件表达式不允许使用 new");
        }
    }

    private static boolean coerceToBoolean(Object value) {
        if (value == null) {
            return false;
        }
        if (value instanceof Boolean b) {
            return b;
        }
        if (value instanceof Number n) {
            return n.doubleValue() != 0.0d;
        }
        if (value instanceof String s) {
            return Boolean.parseBoolean(s) || "1".equals(s);
        }
        return true;
    }

    private static String truncateForLog(String expr) {
        if (expr == null) {
            return "";
        }
        return expr.length() > 200 ? expr.substring(0, 200) + "..." : expr;
    }
}

@Component
@Slf4j
@RequiredArgsConstructor
public class WorkflowConditionSyntaxValidator {

    private final ConditionEvaluator conditionEvaluator;

    /**
     * 对多条条件串做语法校验；null 或空白跳过。
     */
    public void validateAll(List<String> conditionExpressions) {
        if (conditionExpressions == null || conditionExpressions.isEmpty()) {
            return;
        }
        for (String expr : conditionExpressions) {
            if (!StringUtils.hasText(expr)) {
                continue;
            }
            conditionEvaluator.validateSyntax(expr);
        }
    }
}

@Component
@Slf4j
@RequiredArgsConstructor
public class WorkflowConditionalLayerGate {

    private final WorkflowTaskInstanceMapper workflowTaskInstanceMapper;
    private final WorkflowInstanceMapper workflowInstanceMapper;
    private final ConditionEvaluator conditionEvaluator;
    private final ConditionContextBuilder conditionContextBuilder;
    private final ObjectMapper objectMapper;

    /**
     * 在向外层提交调度前：将该层仍为 PENDING 且条件不成立的节点写入 SKIPPED，避免层内长期 PENDING 死锁。
     */
    public void applyBeforeLayerSubmit(Long workflowInstanceId, int layerIndex) {
        try {
            applyBeforeLayerSubmitInternal(workflowInstanceId, layerIndex);
        } catch (Exception e) {
            log.error(
                    "P4-4 条件门控失败 instanceId={} layerIndex={}（工作流仍可继续但不保证跳过分支）",
                    workflowInstanceId,
                    layerIndex,
                    e);
        }
    }

    private void applyBeforeLayerSubmitInternal(Long workflowInstanceId, int layerIndex)
            throws Exception {
        WorkflowInstance inst = workflowInstanceMapper.selectById(workflowInstanceId);
        if (inst == null) {
            return;
        }

        WorkflowExecutionPlan plan =
                objectMapper.readValue(inst.getExecutionPlan(), WorkflowExecutionPlan.class);
        List<WorkflowDependency> deps = plan.getDependencies();
        if (deps == null || deps.isEmpty()) {
            return;
        }

        List<WorkflowTaskInstance> layerTasks =
                workflowTaskInstanceMapper.selectByInstanceIdAndLayer(workflowInstanceId, layerIndex);
        boolean anyPending =
                layerTasks.stream()
                        .anyMatch(
                                w ->
                                        TaskInstanceStatus.PENDING.matches(w.getStatus()));
        if (!anyPending) {
            return;
        }

        Map<String, WorkflowTaskInstance> byName =
                workflowTaskInstanceMapper.selectByInstanceId(workflowInstanceId).stream()
                        .collect(Collectors.toMap(WorkflowTaskInstance::getTaskName, x -> x, (a, b) -> a));

        ConditionContext ctx = conditionContextBuilder.buildContext(workflowInstanceId);

        for (WorkflowTaskInstance wt : layerTasks) {
            if (!TaskInstanceStatus.PENDING.matches(wt.getStatus())) {
                continue;
            }
            if (shouldSkipNode(wt.getTaskName(), deps, ctx, byName)) {
                markSkippedConditionNotMet(wt);
            }
        }
    }

    private boolean shouldSkipNode(
            String taskName,
            List<WorkflowDependency> deps,
            ConditionContext ctx,
            Map<String, WorkflowTaskInstance> byName) {
        List<WorkflowDependency> inbound =
                deps.stream()
                        .filter(d -> taskName.equals(d.getTo()))
                        .collect(Collectors.toList());
        if (inbound.isEmpty()) {
            return false;
        }

        for (WorkflowDependency d : inbound) {
            WorkflowTaskInstance pred = byName.get(d.getFrom());
            if (pred == null) {
                log.warn(
                        "P4-4 跳过节点：上游任务实例缺失 instanceId downstream={}",
                        taskName);
                return true;
            }
            TaskInstanceStatus ps = resolveStatus(pred.getStatus());
            if (ps == null || !ps.isTerminal()) {
                log.warn(
                        "P4-4 跳过节点：上游未终态 from={} status={}",
                        pred.getTaskName(),
                        pred.getStatus());
                return true;
            }
            if (!StringUtils.hasText(d.getCondition())) {
                continue;
            }
            if (!conditionEvaluator.evaluate(d.getCondition(), ctx)) {
                log.info(
                        "P4-4 边上条件未满足，跳过下游 task={} upstream={}",
                        taskName,
                        d.getFrom());
                return true;
            }
        }
        return false;
    }

    private static TaskInstanceStatus resolveStatus(String code) {
        if (!StringUtils.hasText(code)) {
            return null;
        }
        try {
            return TaskInstanceStatus.fromCode(code);
        } catch (IllegalArgumentException ignored) {
            return null;
        }
    }

    private void markSkippedConditionNotMet(WorkflowTaskInstance wt) {
        wt.setStatus(TaskInstanceStatus.SKIPPED.getCode());
        wt.setEndTime(LocalDateTime.now());
        wt.setErrorMessage(
                "Skipped by conditional edge (P4-4)");
        workflowTaskInstanceMapper.updateById(wt);
    }
}

@Service
@Slf4j
public class WorkflowAnalysisServiceImpl implements WorkflowAnalysisService {

    private static final double LOW_AVG_PARALLELISM = 1.5d;
    private static final double LOW_PARALLEL_RATIO = 0.3d;
    private static final double BOTTLENECK_THRESHOLD_FACTOR = 0.5d;
    private static final double CRITICAL_PATH_DEPTH_RATIO = 0.7d;

    @Override
    public ParallelismReport analyzeParallelism(WorkflowExecutionPlan plan) {
        if (plan == null) {
            throw new IllegalArgumentException("执行计划不能为空");
        }

        // 1. 创建ParallelismReport对象
        ParallelismReport report = new ParallelismReport();

        int totalTasks = plan.getTotalTaskCount();
        Integer totalLayersBoxed = plan.getTotalLayers();
        int totalLayers = totalLayersBoxed != null ? totalLayersBoxed : 0;
        List<TaskLayer> layers = plan.getLayers() != null ? plan.getLayers() : Collections.emptyList();
        if (totalLayers <= 0 && !layers.isEmpty()) {
            totalLayers = layers.size();
        }

        // 2. 计算平均并行度
        double averageParallelism =
                totalLayers > 0 ? (double) totalTasks / (double) totalLayers : 0.0d;
        report.setAverageParallelism(averageParallelism);

        // 3. 计算并行化比率
        int parallelTasks = 0;
        for (TaskLayer layer : layers) {
            int p = layer.getParallelism() != null ? layer.getParallelism() : 0;
            if (p > 1) {
                int count = layer.getTasks() != null ? layer.getTasks().size() : p;
                parallelTasks += count;
            }
        }
        double parallelRatio = totalTasks > 0 ? (double) parallelTasks / (double) totalTasks : 0.0d;
        report.setParallelRatio(parallelRatio);

        // 4. 设置关键路径长度
        //    - report.setCriticalPathLength(totalLayers)
        // 说明：当前简化模型下，分层拓扑的「关键路径长度」取总层数（与接口文档一致）
        report.setCriticalPathLength(totalLayers);

        // 5. 构建层并行度分布
        Map<Integer, Integer> distribution = new HashMap<>();
        for (int i = 0; i < layers.size(); i++) {
            TaskLayer layer = layers.get(i);
            int idx = layer.getLayerIndex() != null ? layer.getLayerIndex() : i;
            int par = layer.getParallelism() != null ? layer.getParallelism() : 0;
            distribution.put(idx, par);
        }
        report.setLayerParallelismDistribution(distribution);

        // 6. 识别瓶颈层
        List<Integer> bottlenecks = identifyBottlenecks(plan);
        if (!bottlenecks.isEmpty()) {
            report.setBottleneckLayerIndex(bottlenecks.get(0));
        }

        // 7. 查找关键路径
        List<String> criticalPath = findCriticalPath(plan);
        report.setCriticalPathTasks(criticalPath);

        // 8. 生成优化建议
        List<String> suggestions = generateOptimizationSuggestions(plan, report);
        report.setOptimizationSuggestions(suggestions);

        // 9. 记录日志
        log.info(
                "并行度分析完成 totalTasks={} totalLayers={} avgParallelism={} maxParallelism={}",
                totalTasks,
                totalLayers,
                averageParallelism,
                plan.getMaxParallelism());

        // 10. return report
        return report;
    }

    @Override
    public List<String> findCriticalPath(WorkflowExecutionPlan plan) {
        // 当前版本：简单地从每一层选择第一个任务（简化版关键路径）
        //
        // 1. List<String> criticalPath = new ArrayList<>()
        List<String> criticalPath = new ArrayList<>();
        if (plan == null || plan.getLayers() == null) {
            return criticalPath;
        }
        // 2. 遍历plan.getLayers()
        for (TaskLayer layer : plan.getLayers()) {
            // 3. 对每一层，取第一个任务：
            List<TaskExecutionNode> tasks = layer.getTasks();
            if (tasks != null && !tasks.isEmpty()) {
                TaskExecutionNode first = tasks.get(0);
                if (first.getTaskName() != null) {
                    criticalPath.add(first.getTaskName());
                }
            }
        }
        
        // 注意：完整实现需要：
        // - 考虑任务的实际依赖关系
        // - 考虑任务的预估执行时间
        // - 使用动态规划计算最长路径
        return criticalPath;
    }

    @Override
    public List<Integer> identifyBottlenecks(WorkflowExecutionPlan plan) {
        // 1. List<Integer> bottlenecks = new ArrayList<>()
        List<Integer> bottlenecks = new ArrayList<>();
        if (plan == null || plan.getLayers() == null || plan.getLayers().isEmpty()) {
            return bottlenecks;
        }
        List<TaskLayer> layers = plan.getLayers();

        // 2. 计算平均并行度
        //    - double avgParallelism = (double) plan.getTotalTaskCount() / plan.getTotalLayers()
        int totalTasks = plan.getTotalTaskCount();
        int totalLayers = plan.getTotalLayers() != null ? plan.getTotalLayers() : layers.size();
        if (totalLayers <= 0) {
            return bottlenecks;
        }
        double avgParallelism = (double) totalTasks / (double) totalLayers;

        // 3. 定义瓶颈阈值
        //    - double threshold = avgParallelism * 0.5
        double threshold = avgParallelism * BOTTLENECK_THRESHOLD_FACTOR;

        // 4. 遍历中间层（排除第0层和最后一层）
        //    - List<TaskLayer> layers = plan.getLayers()
        //    - for (int i = 1; i < layers.size() - 1; i++) {
        //        TaskLayer layer = layers.get(i)
        //        if (layer.getParallelism() < threshold) {
        //            bottlenecks.add(layer.getLayerIndex())
        //        }
        //    }
        for (int i = 1; i < layers.size() - 1; i++) {
            TaskLayer layer = layers.get(i);
            int p = layer.getParallelism() != null ? layer.getParallelism() : 0;
            if (p < threshold) {
                int layerIndex = layer.getLayerIndex() != null ? layer.getLayerIndex() : i;
                bottlenecks.add(layerIndex);
            }
        }

        // 5. 按并行度从小到大排序
        //    - bottlenecks.sort(Comparator.comparing(idx -> plan.getLayer(idx).getParallelism()))
        bottlenecks.sort(
                Comparator.comparingInt(
                        idx -> {
                            TaskLayer l = plan.getLayer(idx);
                            if (l == null || l.getParallelism() == null) {
                                return Integer.MAX_VALUE;
                            }
                            return l.getParallelism();
                        }));

        // 6. return bottlenecks
        return bottlenecks;
    }

    @Override
    public List<String> generateOptimizationSuggestions(WorkflowExecutionPlan plan, ParallelismReport report) {
        // 1. List<String> suggestions = new ArrayList<>()
        List<String> suggestions = new ArrayList<>();
        if (plan == null || report == null) {
            return suggestions;
        }

        Double avg = report.getAverageParallelism();
        Integer bottleneckIdx = report.getBottleneckLayerIndex();
        Integer criticalLen = report.getCriticalPathLength();
        Double parallelRatio = report.getParallelRatio();
        int totalTasks = plan.getTotalTaskCount();

        // 2. 检查平均并行度
        //    - if (report.getAverageParallelism() < 1.5) {
        //        suggestions.add("工作流并行度较低（平均" + report.getAverageParallelism() + "），建议：")
        //        suggestions.add("  - 检查任务间的依赖关系，减少不必要的串行依赖")
        //        suggestions.add("  - 考虑将大任务拆分为多个可并行的小任务")
        //    }
        if (avg != null && avg < LOW_AVG_PARALLELISM) {
            suggestions.add("工作流并行度较低（平均" + avg + "），建议：");
            suggestions.add("  - 检查任务间的依赖关系，减少不必要的串行依赖");
            suggestions.add("  - 考虑将大任务拆分为多个可并行的小任务");
        }

        // 3. 检查瓶颈层
        //    - if (report.getBottleneckLayerIndex() != null) {
        //        int bottleneckIdx = report.getBottleneckLayerIndex()
        //        TaskLayer bottleneckLayer = plan.getLayer(bottleneckIdx)
        //        suggestions.add("检测到瓶颈层 Layer " + bottleneckIdx + "，并行度仅为" + bottleneckLayer.getParallelism())
        //        suggestions.add("  - 分析该层的任务，考虑拆分或重组")
        //    }
        if (bottleneckIdx != null) {
            TaskLayer bottleneckLayer = plan.getLayer(bottleneckIdx);
            int par =
                    bottleneckLayer != null && bottleneckLayer.getParallelism() != null
                            ? bottleneckLayer.getParallelism()
                            : 0;
            suggestions.add("检测到瓶颈层 Layer " + bottleneckIdx + "，并行度仅为" + par);
            suggestions.add("  - 分析该层的任务，考虑拆分或重组");
        }

        // 4. 检查关键路径
        //    - if (report.getCriticalPathLength() > plan.getTotalTaskCount() * 0.7) {
        //        suggestions.add("关键路径较长（" + report.getCriticalPathLength() + "层），建议优化以下方面：")
        //        suggestions.add("  - 减少关键路径上的任务数量")
        //        suggestions.add("  - 优化关键路径任务的执行效率")
        //    }
        if (criticalLen != null && totalTasks > 0 && criticalLen > totalTasks * CRITICAL_PATH_DEPTH_RATIO) {
            suggestions.add("关键路径较长（" + criticalLen + "层），建议优化以下方面：");
            suggestions.add("  - 减少关键路径上的任务数量");
            suggestions.add("  - 优化关键路径任务的执行效率");
        }

        // 5. 检查并行化比率
        //    - if (report.getParallelRatio() < 0.3) {
        //        suggestions.add("仅" + (report.getParallelRatio() * 100) + "%的任务可并行执行，并行化程度低")
        //        suggestions.add("  - 重新设计工作流结构，增加并行执行的机会")
        //    }
        if (parallelRatio != null && parallelRatio < LOW_PARALLEL_RATIO) {
            suggestions.add("仅" + (parallelRatio * 100) + "%的任务可并行执行，并行化程度低");
            suggestions.add("  - 重新设计工作流结构，增加并行执行的机会");
        }

        // 6. 如果没有明显问题
        //    - if (suggestions.isEmpty()) {
        //        suggestions.add("工作流结构良好，并行度合理")
        //    }
        if (suggestions.isEmpty()) {
            suggestions.add("工作流结构良好，并行度合理");
        }

        // 7. return suggestions
        return suggestions;
    }
}

@Service
@Slf4j
public class WorkflowControlServiceImpl implements WorkflowControlService {

    @Autowired
    private WorkflowExecutor workflowExecutor;

    @Autowired
    private WorkflowInstanceMapper workflowInstanceMapper;

    @Autowired
    private WorkflowTaskInstanceMapper workflowTaskInstanceMapper;

    @Autowired
    private TaskInstanceService taskInstanceService;

    @Autowired
    private TaskExecutionCancelService taskExecutionCancelService;

    /**
     * 暂停工作流实例
     * 约束：
     * - 只能暂停RUNNING状态的实例
     * 行为：
     * 1. 更新WorkflowInstance状态为PAUSED
     * 2. WorkflowExecutor检测到状态变化后停止调度新任务
     * 3. 已经在运行的任务继续执行完成
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void pauseWorkflowInstance(Long instanceId) {
        log.info("暂停工作流实例, instanceId={}", instanceId);

        WorkflowInstance instance = requireInstance(instanceId);
        WorkflowInstanceStatus st = parseWorkflowInstanceStatus(instance.getStatus());
        if (!st.canPause()) {
            throw new IllegalStateException("仅 RUNNING 状态可暂停，当前状态: " + st.getCode());
        }

        instance.setStatus(WorkflowInstanceStatus.PAUSED.getCode());
        workflowInstanceMapper.updateById(instance);
    }

    /**
     * 恢复工作流实例
     * 约束：
     * - 只能恢复PAUSED状态的实例
     * 行为：
     * 1. 更新WorkflowInstance状态为RUNNING
     * 2. 重新提交到WorkflowExecutor执行队列
     * 3. 从暂停点继续执行（已完成的任务不重复执行）
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void resumeWorkflowInstance(Long instanceId) {
        log.info("恢复工作流实例, instanceId={}", instanceId);

        WorkflowInstance instance = requireInstance(instanceId);
        WorkflowInstanceStatus st = parseWorkflowInstanceStatus(instance.getStatus());
        if (!st.canResume()) {
            throw new IllegalStateException("仅 PAUSED 状态可恢复，当前状态: " + st.getCode());
        }

        instance.setStatus(WorkflowInstanceStatus.RUNNING.getCode());
        workflowInstanceMapper.updateById(instance);

        workflowExecutor.resumeWorkflowInstanceAsync(instanceId);
    }

    /**
     * 取消工作流实例
     * 约束：
     * - 不能取消已终止的实例（SUCCESS/FAILED/PARTIAL_SUCCESS/CANCELLED）
     * 行为：
     * 1. 更新WorkflowInstance状态为CANCELLED
     * 2. 取消所有RUNNING的WorkflowTaskInstance
     * 3. 调用TaskSubmitService取消对应的TaskInstance（经 {@link TaskInstanceService}）
     * 4. 将PENDING的WorkflowTaskInstance标记为SKIPPED
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void cancelWorkflowInstance(Long instanceId) {
        log.info("取消工作流实例, instanceId={}", instanceId);

        WorkflowInstance instance = requireInstance(instanceId);
        WorkflowInstanceStatus st = parseWorkflowInstanceStatus(instance.getStatus());
        if (!st.canCancel()) {
            throw new IllegalStateException("该工作流实例不可取消（已终止或状态非法），当前状态: " + st.getCode());
        }

        Long operatorUserId = currentUserIdSafe();

        instance.setStatus(WorkflowInstanceStatus.CANCELLED.getCode());
        workflowInstanceMapper.updateById(instance);

        List<WorkflowTaskInstance> tasks = workflowTaskInstanceMapper.selectByInstanceId(instanceId);
        for (WorkflowTaskInstance wt : tasks) {
            TaskInstanceStatus t = safeTaskStatus(wt.getStatus());
            if (t == TaskInstanceStatus.RUNNING || t == TaskInstanceStatus.PENDING) {
                cancelSchedulerTaskIfPresent(wt, operatorUserId);
                wt.setStatus(TaskInstanceStatus.SKIPPED.getCode());
                workflowTaskInstanceMapper.updateById(wt);
            }
        }
    }

    /**
     * 重试失败的任务
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public int retryFailedTasks(Long instanceId) {
        log.info("重试失败的任务, instanceId={}", instanceId);

        WorkflowInstance instance = requireInstance(instanceId);
        WorkflowInstanceStatus wf = parseWorkflowInstanceStatus(instance.getStatus());
        if (wf != WorkflowInstanceStatus.FAILED && wf != WorkflowInstanceStatus.PARTIAL_SUCCESS) {
            throw new IllegalStateException(
                    "仅 FAILED 或 PARTIAL_SUCCESS 状态实例可批量重试，当前状态: " + wf.getCode());
        }

        List<WorkflowTaskInstance> tasks = workflowTaskInstanceMapper.selectByInstanceId(instanceId);
        int retries = 0;
        List<WorkflowTaskInstance> resets = new ArrayList<>();
        for (WorkflowTaskInstance wt : tasks) {
            if (TaskInstanceStatus.FAILED.matches(wt.getStatus())) {
                resets.add(wt);
            }
        }
        for (WorkflowTaskInstance wt : resets) {
            resetWorkflowTaskForRetry(wt);
            retries++;
        }

        if (retries == 0) {
            return 0;
        }

        instance.setStatus(WorkflowInstanceStatus.RUNNING.getCode());
        instance.setEndTime(null);
        instance.setDurationMs(null);
        workflowInstanceMapper.updateById(instance);

        workflowExecutor.resumeWorkflowInstanceAsync(instanceId);
        return retries;
    }

    /**
     * 重试指定的任务
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void retryTask(Long workflowTaskInstanceId) {
        log.info("重试任务, workflowTaskInstanceId={}", workflowTaskInstanceId);

        WorkflowTaskInstance wt = workflowTaskInstanceMapper.selectById(workflowTaskInstanceId);
        if (wt == null) {
            throw new IllegalArgumentException("工作流任务实例不存在: " + workflowTaskInstanceId);
        }
        if (!TaskInstanceStatus.FAILED.matches(wt.getStatus())) {
            throw new IllegalStateException("仅 FAILED 的任务可重试");
        }

        resetWorkflowTaskForRetry(wt);

        WorkflowInstance parent = requireInstance(wt.getWorkflowInstanceId());
        parent.setStatus(WorkflowInstanceStatus.RUNNING.getCode());
        parent.setEndTime(null);
        parent.setDurationMs(null);
        workflowInstanceMapper.updateById(parent);

        workflowExecutor.resumeWorkflowInstanceAsync(parent.getId());
    }

    /**
     * 跳过失败的任务
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public int skipFailedTasks(Long instanceId) {
        log.info("跳过失败的任务, instanceId={}", instanceId);

        WorkflowInstance instance = requireInstance(instanceId);

        List<WorkflowTaskInstance> tasks = workflowTaskInstanceMapper.selectByInstanceId(instanceId);
        int skipped = 0;
        for (WorkflowTaskInstance wt : tasks) {
            if (TaskInstanceStatus.FAILED.matches(wt.getStatus())) {
                wt.setStatus(TaskInstanceStatus.SKIPPED.getCode());
                workflowTaskInstanceMapper.updateById(wt);
                skipped++;
            }
        }

        if (skipped > 0) {
            int failed = instance.getFailedTasks() == null ? 0 : instance.getFailedTasks();
            instance.setFailedTasks(Math.max(0, failed - skipped));
            workflowInstanceMapper.updateById(instance);
        }

        return skipped;
    }

    // ==================== 私有辅助方法 ====================

    private WorkflowInstance requireInstance(Long instanceId) {
        WorkflowInstance instance = workflowInstanceMapper.selectById(instanceId);
        if (instance == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + instanceId);
        }
        return instance;
    }

    private Long currentUserIdSafe() {
        try {
            return WorkflowSecurityContextHolder.require().principal().userId();
        } catch (IllegalStateException e) {
            return null;
        }
    }

    private void resetWorkflowTaskForRetry(WorkflowTaskInstance wt) {
        wt.setStatus(TaskInstanceStatus.PENDING.getCode());
        wt.setTaskInstanceId(null);
        wt.setStartTime(null);
        wt.setEndTime(null);
        wt.setDurationSeconds(null);
        wt.setExitCode(null);
        wt.setOutput(null);
        wt.setErrorMessage(null);
        int rc = wt.getRetryCount() == null ? 0 : wt.getRetryCount();
        wt.setRetryCount(rc + 1);
        workflowTaskInstanceMapper.updateById(wt);
    }

    private TaskInstanceStatus safeTaskStatus(String code) {
        try {
            return TaskInstanceStatus.fromCode(code);
        } catch (Exception e) {
            return TaskInstanceStatus.PENDING;
        }
    }

    /**
     * 取消单个任务对应的调度 TaskInstance。
     */
    private void cancelSchedulerTaskIfPresent(WorkflowTaskInstance taskInstance, Long operatorUserId) {
        Long sid = taskInstance.getTaskInstanceId();
        if (sid == null) {
            return;
        }
        TaskInstance ti = taskInstanceService.getById(sid);
        if (ti == null) {
            return;
        }
        TaskInstanceStatus cur;
        try {
            cur = TaskInstanceStatus.fromCode(ti.getStatus());
        } catch (Exception e) {
            return;
        }
        if (cur != TaskInstanceStatus.PENDING && cur != TaskInstanceStatus.RUNNING) {
            return;
        }
        if (cur == TaskInstanceStatus.RUNNING) {
            taskExecutionCancelService.cancelRunningTask(ti.getId(), ti.getResourceNodeId());
        }
        InternalTaskInstanceStatusTransitionRequest req =
                new InternalTaskInstanceStatusTransitionRequest(
                        cur.getCode(),
                        TaskInstanceStatus.CANCELLED.getCode(),
                        "SYSTEM",
                        "工作流实例取消",
                        operatorUserId,
                        null,
                        null);
        Result<TaskInstance> r = taskInstanceService.transitionStatus(ti.getId(), req);
        if (!r.isSuccess()) {
            log.warn(
                    "取消调度任务实例未成功 workflowTaskInstanceId={} schedulerTaskInstanceId={} msg={}",
                    taskInstance.getId(),
                    ti.getId(),
                    r.getMessage());
        }
    }

    private static WorkflowInstanceStatus parseWorkflowInstanceStatus(String raw) {
        if (raw == null || raw.isBlank()) {
            throw new IllegalArgumentException("工作流实例状态为空");
        }
        String s = raw.trim();
        for (WorkflowInstanceStatus st : WorkflowInstanceStatus.values()) {
            if (st.name().equalsIgnoreCase(s) || st.getCode().equalsIgnoreCase(s)) {
                return st;
            }
        }
        throw new IllegalArgumentException("不支持的工作流实例状态: " + raw);
    }
}

@Service
@Slf4j
public class WorkflowExecutionServiceImpl implements WorkflowExecutionService {
    
    @Autowired
    private WorkflowMapper workflowMapper;
    
    @Autowired
    private WorkflowService workflowService;
    
    @Autowired
    private DistributedWorkflowCacheManager cacheManager;
    
    @Override
    public WorkflowExecutionPlan buildExecutionPlan(Long workflowId) {
        // 使用分布式缓存管理器，实现 L1+L2 两层缓存协调
        // 若缓存未命中，doBuildExecutionPlan 作为 loader 从数据库加载
        return cacheManager.getExecutionPlan(workflowId, this::doBuildExecutionPlan);
    }
    
    /**
     * 实际构建执行计划的方法
     * 
     * 业务流程：
     * 1. 从数据库查询工作流定义
     * 2. 验证工作流存在性
     * 3. 解析DAG JSON
     * 4. 构建邻接表和任务映射表
     * 5. 执行拓扑排序
     * 6. 构建执行计划对象
     * 7. 记录日志
     * 
     * @param workflowId 工作流ID
     * @return 执行计划
     */
    private WorkflowExecutionPlan doBuildExecutionPlan(Long workflowId) {
        // 1. workflowMapper.selectById(workflowId)
        Workflow workflow = workflowMapper.selectById(workflowId);
        // 2. 检查workflow是否为null，为null抛出IllegalArgumentException
        if (workflow == null) {
            log.warn("工作流不存在 workflowId={}", workflowId);
            throw new IllegalArgumentException("工作流不存在");
        }
        String dagJson = workflow.getDagJson();
        if (dagJson == null || dagJson.isBlank()) {
            log.warn("工作流 DAG 为空 workflowId={}", workflowId);
            throw new IllegalArgumentException("工作流 DAG 定义不能为空");
        }
        // 3. 调用workflowService.parseDAG(workflow.getDagJson())解析DAG
        WorkflowDAG dag = workflowService.parseDAG(dagJson);
        // 4. 调用buildGraph(dag)构建邻接表
        Map<String, List<String>> graph = buildGraph(dag);
        // 5. 调用buildTaskMap(dag)构建任务映射
        Map<String, WorkflowTask> taskMap = buildTaskMap(dag);
        // 6. 调用topologicalSort(graph)得到分层结果
        List<List<String>> layers = topologicalSort(graph);
        // 7. 创建WorkflowExecutionPlan对象
        WorkflowExecutionPlan plan = new WorkflowExecutionPlan();
        // 8. 设置workflowId, workflowName, totalLayers
        plan.setWorkflowId(workflowId);
        plan.setWorkflowName(workflow.getWorkflowName());
        plan.setTotalLayers(layers.size());
        // 9. 遍历layers，构建TaskLayer列表：
        //    - 对每一层创建TaskLayer对象
        //    - 设置layerIndex
        //    - 遍历该层的任务名，创建TaskExecutionNode
        //    - 设置taskName, taskDefinition（从taskMap获取）, layerIndex
        //    - 将nodes设置到TaskLayer
        //    - 设置parallelism（nodes.size()）
        List<TaskLayer> taskLayers = new ArrayList<>();
        for (int i = 0; i < layers.size(); i++) {
            List<String> taskNames = layers.get(i);
            TaskLayer layer = new TaskLayer();
            layer.setLayerIndex(i);
            List<TaskExecutionNode> nodes = new ArrayList<>();
            for (String taskName : taskNames) {
                WorkflowTask taskDef = taskMap.get(taskName);
                if (taskDef == null) {
                    log.error("任务定义不存在 taskName={} workflowId={}", taskName, workflowId);
                    throw new IllegalStateException("任务定义不存在: " + taskName);
                }
                TaskExecutionNode node = new TaskExecutionNode();
                node.setTaskName(taskName);
                node.setTaskDefinition(taskDef);
                node.setLayerIndex(i);
                node.setStatus(TaskNodeStatus.PENDING);
                nodes.add(node);
            }
            layer.setTasks(nodes);
            layer.setParallelism(nodes.size());
            taskLayers.add(layer);
        }

        // 10. 设置分层任务与各层并行度
        plan.setLayers(taskLayers);

        // 11. DAG 依赖边快照（含 P4-4 condition），随实例 execution_plan JSON 固化
        List<WorkflowDependency> depSnapshot =
                dag.getDependencies() != null
                        ? new ArrayList<>(dag.getDependencies())
                        : new ArrayList<>();
        plan.setDependencies(depSnapshot);

        // 12. 记录日志并返回
        log.info(
                "构建工作流执行计划成功 workflowId={} workflowName={} totalLayers={} totalTasks={}",
                workflowId,
                workflow.getWorkflowName(),
                plan.getTotalLayers(),
                plan.getTotalTaskCount());
        return plan;
    }

    // Kahn算法实现分层拓扑排序
    @Override
    public List<List<String>> topologicalSort(Map<String, List<String>> graph) {
        // 步骤1: 计算入度
        // - 创建 Map<String, Integer> inDegree
        Map<String, Integer> indegree = new HashMap<>();
        // 先初始化所有节点入度为0
        for(String node : graph.keySet()){
            indegree.putIfAbsent(node, 0);
        }
        // 再遍历边累加入度
        for(String node : graph.keySet()){
            for(String neighbor : graph.get(node)){
                indegree.put(neighbor, indegree.getOrDefault(neighbor, 0) + 1);
            }
        }

        // 步骤2: 初始化队列
        // - 创建 Queue<String> queue, ArrayDeque实现
        // - 遍历inDegree，将入度为0的节点加入队列
        Queue<String> queue = new ArrayDeque<>();
        for(String node : graph.keySet()){
            if(indegree.get(node) == 0){
                queue.offer(node);
            }
        }

        // 步骤3: 分层处理（关键）
        List<List<String>> layers = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        while(!queue.isEmpty()){
            int layerSize = queue.size(); // 当前层的节点数
            List<String> currentLayer = new ArrayList<>();

            // 处理当前层的所有节点
            for(int i = 0; i < layerSize; i++){
                String node = queue.poll();
                currentLayer.add(node);
                visited.add(node);

                // 更新邻居的入度
                for(String neighbor : graph.getOrDefault(node, Collections.emptyList())){
                    indegree.put(neighbor, indegree.get(neighbor) - 1);

                    // 入度变为0，加入队列（下一层）
                    if(indegree.get(neighbor) == 0){
                        queue.offer(neighbor);
                    }
                }
            }
            layers.add(currentLayer);
        }

        // 步骤4: 检测环
        if(visited.size() != graph.size()){
            log.error("检测到环，已访问节点数={} 总节点数={}", visited.size(), graph.size());
            throw new IllegalStateException("DAG存在环，无法进行拓扑排序");
        }

        // 步骤5: 返回结果
        log.info("拓扑排序完成 layers={}", layers);
        return layers;
    }
    
    @Override
    public Map<String, List<String>> buildGraph(WorkflowDAG dag) {
        Map<String, List<String>> graph = new HashMap<>();
        for (WorkflowTask task : dag.getTasks()) {
            graph.put(task.getNodeName(), new ArrayList<>());
        }
        List<WorkflowDependency> deps =
                dag.getDependencies() != null ? dag.getDependencies() : Collections.emptyList();
        for (WorkflowDependency dep : deps) {
            List<String> outs = graph.get(dep.getFrom());
            if (outs == null) {
                throw new IllegalArgumentException("依赖的上游节点不存在: " + dep.getFrom());
            }
            outs.add(dep.getTo());
        }
        return graph;
    }
    
    @Override
    public Map<String, WorkflowTask> buildTaskMap(WorkflowDAG dag) {
        Map<String, WorkflowTask> taskMap = new HashMap<>();
        for(WorkflowTask task : dag.getTasks()){
            taskMap.put(task.getNodeName(), task);
        }
        return taskMap;
    }
    
    @Override
    public void invalidatePlanCache(Long workflowId) {
        // 委托给分布式缓存管理器
        // 它会：1. 清本实例 L1 缓存
        //      2. 清 Redis L2 缓存
        //      3. 发布 Pub/Sub 通知其他实例清除各自的 L1 缓存
        cacheManager.invalidateExecutionPlan(workflowId);
    }
    
    /**
     * 获取缓存统计信息（用于监控）
     * 返回本实例 L1 本地缓存的统计数据
     */
    public String getCacheStats() {
        return cacheManager.getCacheStats();
    }
}

@Service
@Slf4j
public class WorkflowExecutorImpl implements WorkflowExecutor {
    
    @Autowired
    private WorkflowInstanceMapper workflowInstanceMapper;
    
    @Autowired
    private WorkflowTaskInstanceMapper workflowTaskInstanceMapper;
    
    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private WorkflowLayerDispatchFacade workflowLayerDispatchFacade;
    
    @Autowired
    @Qualifier("workflowExecutorThreadPool")
    private ExecutorService executorService;
    
    /**
     * 执行工作流实例
     * 
     * 注意：此方法只负责启动工作流执行，实际的任务执行由以下组件协同完成：
     * 1. DAG引擎（本类）：编排任务顺序，提交PENDING任务
     * 2. 调度器：资源管理决策，状态流转
     * 3. 执行器：实际执行任务
     * 4. 事件监听器：监听任务完成，触发DAG引擎继续编排
     */
    @Override
    public void executeWorkflowInstance(Long instanceId) {
        log.info("开始执行工作流实例, instanceId={}", instanceId);
        
        // 1. 验证实例状态（必须是PENDING）
        WorkflowInstance instance = workflowInstanceMapper.selectById(instanceId);
        if (instance == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + instanceId);
        }

        if (parseWorkflowInstanceStatus(instance.getStatus()) != WorkflowInstanceStatus.PENDING) {
            throw new IllegalStateException("工作流实例状态不正确，当前状态: " + instance.getStatus());
        }

        // 2. 更新状态为PREPARING
        updateInstanceStatus(instanceId, WorkflowInstanceStatus.PREPARING);

        try {
            // 3. 解析执行计划 JSON（校验可读）
            parseExecutionPlan(instance.getExecutionPlan());

            // 4. 更新状态为RUNNING，记录开始时间
            instance.setStatus(WorkflowInstanceStatus.RUNNING.getCode());
            instance.setStartTime(LocalDateTime.now());
            workflowInstanceMapper.updateById(instance);

            // 5. 提交第0层（入度为0的任务）到调度器
            Long submitUserId =
                    instance.getTriggerUserId() != null ? instance.getTriggerUserId() : instance.getTenantId();
            workflowLayerDispatchFacade.dispatchLayer(instanceId, 0, submitUserId);

            log.info("工作流实例启动完成, instanceId={}, 已提交第0层任务到调度器", instanceId);

            // 注意：不在这里等待任务完成
            // 任务完成后，TaskCompletionStreamListener 消费 Stream 事件并触发下一批任务的提交

        } catch (Exception e) {
            log.error("工作流实例执行失败 instanceId={}", instanceId, e);
            failWorkflowInstance(instance, e.getMessage());
            throw new RuntimeException("工作流执行失败", e);
        }
    }
    
    /**
     * 异步执行工作流实例
     */
    @Override
    public void executeWorkflowInstanceAsync(Long instanceId) {
        log.info("异步执行工作流实例, instanceId={}", instanceId);
        
        executorService.submit(() -> {
            try {
                executeWorkflowInstance(instanceId);
            } catch (Exception e) {
                log.error("异步执行工作流实例失败 instanceId={}", instanceId, e);
            }
        });
    }

    @Override
    public void resumeWorkflowInstanceAsync(Long instanceId) {
        log.info("异步继续投递Pending工作流任务, instanceId={}", instanceId);
        executorService.submit(() -> {
            try {
                continueSchedulePendingLayers(instanceId);
            } catch (Exception e) {
                log.error("继续投递Pending工作流任务失败 instanceId={}", instanceId, e);
            }
        });
    }

    /**
     * 从仍存在 PENDING 节点的最浅层重新提交到调度队列（与同层 RUNNING 任务共存）。
     */
    private void continueSchedulePendingLayers(Long instanceId) throws Exception {
        WorkflowInstance instance = workflowInstanceMapper.selectById(instanceId);
        if (instance == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + instanceId);
        }
        WorkflowInstanceStatus wfStatus = parseWorkflowInstanceStatus(instance.getStatus());
        if (wfStatus != WorkflowInstanceStatus.RUNNING) {
            throw new IllegalStateException(
                    "工作流实例必须为 RUNNING 后方可继续投递，当前状态: " + wfStatus.getCode());
        }
        Integer minLayer = computeMinPendingLayer(instanceId);
        if (minLayer != null) {
            Long submitUserId =
                    instance.getTriggerUserId() != null ? instance.getTriggerUserId() : instance.getTenantId();
            workflowLayerDispatchFacade.dispatchLayer(instanceId, minLayer, submitUserId);
            log.info("已继续投递第{}层 PENDING 任务 instanceId={}", minLayer, instanceId);
        } else {
            log.info("未发现 PENDING 工作流节点，跳过投递 instanceId={}", instanceId);
        }
    }

    private Integer computeMinPendingLayer(Long instanceId) {
        List<WorkflowTaskInstance> all = workflowTaskInstanceMapper.selectByInstanceId(instanceId);
        int min = Integer.MAX_VALUE;
        boolean found = false;
        for (WorkflowTaskInstance t : all) {
            if (TaskInstanceStatus.PENDING.matches(t.getStatus())) {
                found = true;
                if (t.getLayerIndex() != null) {
                    min = Math.min(min, t.getLayerIndex());
                }
            }
        }
        return found ? min : null;
    }

    private static WorkflowInstanceStatus parseWorkflowInstanceStatus(String raw) {
        if (raw == null || raw.isBlank()) {
            throw new IllegalArgumentException("工作流实例状态为空");
        }
        String s = raw.trim();
        for (WorkflowInstanceStatus st : WorkflowInstanceStatus.values()) {
            if (st.name().equalsIgnoreCase(s) || st.getCode().equalsIgnoreCase(s)) {
                return st;
            }
        }
        throw new IllegalArgumentException("Unsupported workflow instance status: " + raw);
    }

    // ==================== 私有辅助方法 ====================

    private void failWorkflowInstance(WorkflowInstance instance, String errorMessage) {
        instance.setStatus(WorkflowInstanceStatus.FAILED.getCode());
        instance.setEndTime(LocalDateTime.now());

        if (instance.getStartTime() != null) {
            long ms = java.time.Duration.between(
                    instance.getStartTime(),
                    instance.getEndTime()
            ).toMillis();
            instance.setDurationMs(ms);
        }

        workflowInstanceMapper.updateById(instance);

        log.error("工作流实例执行失败 instanceId={} error={}", instance.getId(), errorMessage);
    }

    /**
     * 解析执行计划 JSON
     */
    private WorkflowExecutionPlan parseExecutionPlan(String json) throws Exception {
        return objectMapper.readValue(json, WorkflowExecutionPlan.class);
    }

    /**
     * 更新实例状态
     */
    private void updateInstanceStatus(Long instanceId, WorkflowInstanceStatus status) {
        WorkflowInstance patch = new WorkflowInstance();
        patch.setId(instanceId);
        patch.setStatus(status.getCode());
        workflowInstanceMapper.updateById(patch);
    }
}

@Service
@Slf4j
public class WorkflowInstanceServiceImpl implements WorkflowInstanceService {

    private static final int WORKFLOW_ENABLED = 1;
    private static final DateTimeFormatter INSTANCE_TS = DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss");

    @Autowired
    private WorkflowInstanceMapper workflowInstanceMapper;

    @Autowired
    private WorkflowTaskInstanceMapper workflowTaskInstanceMapper;

    @Autowired
    private WorkflowExecutionService workflowExecutionService;

    @Autowired
    private WorkflowExecutor workflowExecutor;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private WorkflowService workflowService;

    /**
     * 创建工作流实例
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long createWorkflowInstance(WorkflowInstanceCreateRequest request) {
        log.info("开始创建工作流实例, workflowId={}", request.getWorkflowId());

        // 1. 验证工作流定义存在且状态正常（跨租户已由 WorkflowSecurityContextHolder 与工作流归属校验兜底）
        var workflowDefinition = workflowService.getById(request.getWorkflowId());
        if (workflowDefinition == null) {
            throw new IllegalArgumentException("工作流不存在或无访问权限");
        }
        if (workflowDefinition.getStatus() == null || workflowDefinition.getStatus() != WORKFLOW_ENABLED) {
            throw new IllegalStateException("工作流未启用或不可用");
        }

        // 2. 构建执行计划
        WorkflowExecutionPlan plan = workflowExecutionService.buildExecutionPlan(request.getWorkflowId());

        Long tenantId = WorkflowSecurityContextHolder.require().principal().tenantId();
        Long triggerUserId = resolveTriggerUserId(request.getTriggeredBy());
        FailureStrategy fs =
                request.getFailureStrategy() != null ? request.getFailureStrategy() : FailureStrategy.STOP_ON_FAILURE;

        WorkflowInstance entity = new WorkflowInstance();
        entity.setWorkflowId(request.getWorkflowId());
        entity.setTenantId(tenantId);
        entity.setTriggerType(
                request.getTriggerType() != null ? request.getTriggerType().name() : TriggerType.MANUAL.name());
        entity.setTriggerUserId(triggerUserId);
        entity.setFailureStrategy(fs.getCode());
        entity.setStatus(WorkflowInstanceStatus.PENDING.getCode());
        entity.setTotalTasks(plan.getTotalTaskCount());
        entity.setSuccessTasks(0);
        entity.setFailedTasks(0);

        String nameOrCode =
                StringUtils.hasText(request.getInstanceName())
                        ? request.getInstanceName().trim()
                        : generateInstanceName(workflowDefinition.getWorkflowName());
        entity.setInstanceCode(nameOrCode);

        try {
            entity.setExecutionPlan(objectMapper.writeValueAsString(plan));
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("序列化执行计划失败", e);
        }

        if (request.getWorkflowContext() != null && !request.getWorkflowContext().isEmpty()) {
            try {
                entity.setContextJson(objectMapper.writeValueAsString(request.getWorkflowContext()));
            } catch (JsonProcessingException e) {
                throw new IllegalArgumentException("实例上下文 workflowContext 序列化失败", e);
            }
        }

        if (workflowInstanceMapper.insert(entity) != 1 || entity.getId() == null) {
            throw new IllegalStateException("保存工作流实例失败");
        }

        try {
            createTaskSnapshots(entity.getId(), plan);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("持久化任务实例快照失败", e);
        }

        boolean runNow = request.getExecuteImmediately() == null || Boolean.TRUE.equals(request.getExecuteImmediately());
        if (runNow) {
            workflowExecutor.executeWorkflowInstanceAsync(entity.getId());
        }

        log.info("工作流实例创建成功, instanceId={}", entity.getId());
        return entity.getId();
    }

    /**
     * 根据ID获取工作流实例
     */
    @Override
    public WorkflowInstance getWorkflowInstance(Long instanceId) {
        log.info("查询工作流实例, instanceId={}", instanceId);

        WorkflowInstance workflowInstance = workflowInstanceMapper.selectById(instanceId);
        if (workflowInstance == null) {
            return null;
        }
        requireInstanceAccessible(workflowInstance);
        return workflowInstance;
    }

    /**
     * 重新运行工作流实例
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long rerunWorkflowInstance(Long instanceId) {
        log.info("重新运行工作流实例, instanceId={}", instanceId);

        WorkflowInstance previous = workflowInstanceMapper.selectById(instanceId);
        if (previous == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + instanceId);
        }
        requireInstanceAccessible(previous);

        WorkflowInstanceCreateRequest next = new WorkflowInstanceCreateRequest();
        next.setWorkflowId(previous.getWorkflowId());
        next.setFailureStrategy(parseFailureStrategy(previous.getFailureStrategy()));
        next.setTriggerType(parseTriggerType(previous.getTriggerType()));
        next.setTriggeredBy(previous.getTriggerUserId());
        next.setExecuteImmediately(true);

        String baseName =
                previous.getInstanceCode() != null && previous.getInstanceCode().contains("_")
                        ? previous.getInstanceCode().substring(0, previous.getInstanceCode().lastIndexOf('_'))
                        : previous.getInstanceCode();
        next.setInstanceName(generateInstanceName(baseName != null ? baseName : "workflow"));

        return createWorkflowInstance(next);
    }

    /**
     * 删除工作流实例
     *
     * 注意：只能删除已终止的实例
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void deleteWorkflowInstance(Long instanceId) {
        log.info("删除工作流实例, instanceId={}", instanceId);

        WorkflowInstance instance = workflowInstanceMapper.selectById(instanceId);
        if (instance == null) {
            throw new IllegalArgumentException("工作流实例不存在: " + instanceId);
        }
        requireInstanceAccessible(instance);

        WorkflowInstanceStatus st = parseWorkflowInstanceStatus(instance.getStatus());
        if (!st.isTerminal()) {
            throw new IllegalStateException("仅允许删除已终止的工作流实例，当前状态: " + st.getCode());
        }

        workflowTaskInstanceMapper.delete(
                new LambdaQueryWrapper<WorkflowTaskInstance>()
                        .eq(WorkflowTaskInstance::getWorkflowInstanceId, instanceId));

        workflowInstanceMapper.deleteById(instanceId);
    }

    /**
     * 生成实例名称
     *
     * 格式：{工作流名称}_{yyyyMMdd_HHmmss}
     */
    @Override
    public String generateInstanceName(String workflowName) {
        String safe = workflowName != null ? workflowName.replaceAll("\\s+", "_").trim() : "workflow";
        if (safe.length() > 80) {
            safe = safe.substring(0, 80);
        }
        return safe + "_" + INSTANCE_TS.format(LocalDateTime.now());
    }

    // ==================== 私有辅助方法 ====================

    private Long resolveTriggerUserId(Long triggeredByOverride) {
        if (triggeredByOverride != null) {
            return triggeredByOverride;
        }
        return WorkflowSecurityContextHolder.require().principal().userId();
    }

    /**
     * 创建任务实例
     *
     * 每条记录保存 {@link WorkflowTask} 快照，供执行引擎与调度器消费。
     */
    private void createTaskSnapshots(Long instanceId, WorkflowExecutionPlan plan) throws JsonProcessingException {
        if (plan == null || plan.getLayers() == null) {
            return;
        }
        for (TaskLayer layer : plan.getLayers()) {
            if (layer == null || layer.getTasks() == null) {
                continue;
            }
            Integer layerIx = layer.getLayerIndex();
            for (TaskExecutionNode node : layer.getTasks()) {
                if (node == null || !StringUtils.hasText(node.getTaskName())) {
                    continue;
                }
                WorkflowTaskInstance row = new WorkflowTaskInstance();
                row.setWorkflowInstanceId(instanceId);
                row.setTaskName(node.getTaskName().trim());
                WorkflowTask def = node.getTaskDefinition();
                row.setTaskDefinition(def == null ? "{}" : objectMapper.writeValueAsString(def));
                row.setStatus(TaskInstanceStatus.PENDING.getCode());
                row.setLayerIndex(layerIx != null ? layerIx : node.getLayerIndex());
                row.setRetryCount(0);

                workflowTaskInstanceMapper.insert(row);
            }
        }
    }

    private void requireInstanceAccessible(WorkflowInstance workflowInstance) {
        if (workflowInstance == null) {
            return;
        }
        if (workflowService.getById(workflowInstance.getWorkflowId()) == null) {
            throw new IllegalArgumentException("工作流实例不存在或无访问权限");
        }
    }

    private static WorkflowInstanceStatus parseWorkflowInstanceStatus(String raw) {
        if (raw == null || raw.isBlank()) {
            throw new IllegalArgumentException("工作流实例状态为空");
        }
        String s = raw.trim();
        for (WorkflowInstanceStatus st : WorkflowInstanceStatus.values()) {
            if (st.name().equalsIgnoreCase(s) || st.getCode().equalsIgnoreCase(s)) {
                return st;
            }
        }
        throw new IllegalArgumentException("不支持的工作流实例状态: " + raw);
    }

    private FailureStrategy parseFailureStrategy(String stored) {
        if (!StringUtils.hasText(stored)) {
            return FailureStrategy.STOP_ON_FAILURE;
        }
        try {
            return FailureStrategy.fromCode(stored.trim());
        } catch (Exception e) {
            return FailureStrategy.STOP_ON_FAILURE;
        }
    }

    private TriggerType parseTriggerType(String stored) {
        if (!StringUtils.hasText(stored)) {
            return TriggerType.MANUAL;
        }
        String token = stored.trim();
        for (TriggerType t : TriggerType.values()) {
            if (t.name().equalsIgnoreCase(token) || t.getCode().equalsIgnoreCase(token)) {
                return t;
            }
        }
        return TriggerType.MANUAL;
    }
}

@Service
@Slf4j
@RequiredArgsConstructor
public class WorkflowLayerDispatchFacade {

    private final WorkflowTaskInstanceMapper workflowTaskInstanceMapper;
    private final WorkflowInstanceMapper workflowInstanceMapper;
    private final TaskSubmitService taskSubmitService;
    private final ObjectMapper objectMapper;
    private final WorkflowConditionalLayerGate conditionalLayerGate;

    /**
     * 某 WorkflowTaskInstance 刚进入终态后调用：在当前层<strong>整体</strong>终态时再打开下一层。
     */
    public void onWorkflowTaskTerminated(Long workflowInstanceId, int taskCompletedLayerIndex) {
        try {
            WorkflowInstance flow = workflowInstanceMapper.selectById(workflowInstanceId);
            if (flow != null) {
                WorkflowInstanceStatus wfStatus = parseWorkflowInstanceStatus(flow.getStatus());
                if (wfStatus == WorkflowInstanceStatus.PAUSED
                        || wfStatus == WorkflowInstanceStatus.CANCELLED) {
                    log.debug(
                            "工作流实例为 {}，不再驱动下一层 instanceId={}",
                            wfStatus.name(),
                            workflowInstanceId);
                    return;
                }
            }

            List<WorkflowTaskInstance> currentLayerTasks =
                    workflowTaskInstanceMapper.selectByInstanceIdAndLayer(
                            workflowInstanceId, taskCompletedLayerIndex);

            boolean allTerminal =
                    currentLayerTasks.stream().allMatch(WorkflowLayerDispatchFacade::isWorkflowTaskTerminal);

            if (!allTerminal) {
                log.debug(
                        "第{}层任务尚未全部完成 instanceId={}",
                        taskCompletedLayerIndex,
                        workflowInstanceId);
                return;
            }

            log.info("第{}层任务全部完成 instanceId={}", taskCompletedLayerIndex, workflowInstanceId);
            proceedAfterLayerFinished(workflowInstanceId, taskCompletedLayerIndex);

        } catch (Exception e) {
            log.error(
                    "工作流层级推进失败 instanceId={} layerIndex={}",
                    workflowInstanceId,
                    taskCompletedLayerIndex,
                    e);
        }
    }

    /**
     * 投递某层仍为 PENDING 的 WorkflowTaskInstance 到调度器；含 P4-4 门前条件门控，
     * 并在整层已终态时再自动推进后续层。
     */
    public void dispatchLayer(Long workflowInstanceId, int layerIndex, Long submitPrincipalId)
            throws Exception {
        conditionalLayerGate.applyBeforeLayerSubmit(workflowInstanceId, layerIndex);

        log.info("提交第{}层任务 instanceId={}", layerIndex, workflowInstanceId);

        List<WorkflowTaskInstance> layerTasks =
                workflowTaskInstanceMapper.selectByInstanceIdAndLayer(workflowInstanceId, layerIndex);
        if (layerTasks.isEmpty()) {
            log.warn("第{}层没有任务 instanceId={}，视作已结束并尝试推进", layerIndex, workflowInstanceId);
            proceedAfterLayerFinished(workflowInstanceId, layerIndex);
            return;
        }

        WorkflowInstance instance =
                workflowInstanceMapper.selectById(workflowInstanceId);
        Long tenantId =
                instance != null && instance.getTenantId() != null
                        ? instance.getTenantId()
                        : instance != null ? instance.getTriggerUserId() : null;

        Long effectiveSubmitUser =
                submitPrincipalId != null
                        ? submitPrincipalId
                        : instance != null
                                ? (instance.getTriggerUserId() != null
                                        ? instance.getTriggerUserId()
                                        : instance.getTenantId())
                                : tenantId;

        for (WorkflowTaskInstance wtInstance : layerTasks) {
            try {
                // 只调度 PENDING 状态的节点；DISPATCHED/RUNNING/终态均已处理，幂等跳过
                if (!TaskInstanceStatus.PENDING.matches(wtInstance.getStatus())) {
                    log.debug("跳过非PENDING节点 taskName={} status={}",
                            wtInstance.getTaskName(), wtInstance.getStatus());
                    continue;
                }
                TaskInstance taskInstance = wtInstance.toTaskInstance(tenantId, effectiveSubmitUser);
                Result<TaskSubmitResponse> result =
                        taskSubmitService.submitTask(buildTaskSubmitRequest(taskInstance));
                if (!result.isSuccess()) {
                    throw new RuntimeException("任务提交失败: " + result.getMessage());
                }
                TaskSubmitResponse submitResponse = result.getData();
                if (submitResponse != null && submitResponse.getTaskInstanceId() != null) {
                    wtInstance.setTaskInstanceId(submitResponse.getTaskInstanceId());
                }
                // 标记为 DISPATCHED，防止 dispatchLayer 重入时重复提交（DAG 推进幂等的关键屏障）
                wtInstance.setStatus(TaskInstanceStatus.DISPATCHED.getCode());
                workflowTaskInstanceMapper.updateById(wtInstance);
                log.info(
                        "任务已提交到调度器 taskName={} workflowTaskInstanceId={} taskInstanceId={}",
                        wtInstance.getTaskName(),
                        wtInstance.getId(),
                        submitResponse != null ? submitResponse.getTaskInstanceId() : null);
            } catch (Exception e) {
                log.error(
                        "提交任务失败 taskName={} workflowTaskInstanceId={}",
                        wtInstance.getTaskName(),
                        wtInstance.getId(),
                        e);
                wtInstance.setStatus(TaskInstanceStatus.FAILED.getCode());
                wtInstance.setErrorMessage("提交任务失败: " + e.getMessage());
                wtInstance.setEndTime(LocalDateTime.now());
                workflowTaskInstanceMapper.updateById(wtInstance);
                workflowInstanceMapper.incrementFailedTasks(workflowInstanceId);
            }
        }

        reconcileSilentLayerTermination(workflowInstanceId, layerIndex);
    }

    private void reconcileSilentLayerTermination(Long workflowInstanceId, int layerIndex)
            throws Exception {
        List<WorkflowTaskInstance> layerTasks =
                workflowTaskInstanceMapper.selectByInstanceIdAndLayer(workflowInstanceId, layerIndex);
        if (layerTasks.isEmpty()) {
            return;
        }
        boolean allTerminal = layerTasks.stream().allMatch(WorkflowLayerDispatchFacade::isWorkflowTaskTerminal);
        if (allTerminal) {
            proceedAfterLayerFinished(workflowInstanceId, layerIndex);
        }
    }

    private void proceedAfterLayerFinished(Long workflowInstanceId, int completedLayerIndex)
            throws Exception {
        WorkflowInstance instance = workflowInstanceMapper.selectById(workflowInstanceId);
        if (instance == null) {
            log.warn("工作流实例不存在，跳过后续推进 instanceId={}", workflowInstanceId);
            return;
        }
        WorkflowExecutionPlan plan =
                objectMapper.readValue(instance.getExecutionPlan(), WorkflowExecutionPlan.class);

        int nextLayer = completedLayerIndex + 1;
        if (nextLayer < plan.getLayers().size()) {
            Long submitPrincipal =
                    instance.getTriggerUserId() != null
                            ? instance.getTriggerUserId()
                            : instance.getTenantId();
            log.info("提交下一层任务 instanceId={} nextLayer={}", workflowInstanceId, nextLayer);
            dispatchLayer(workflowInstanceId, nextLayer, submitPrincipal);
        } else {
            log.info("所有层任务已完成，标记工作流完成 instanceId={}", workflowInstanceId);
            completeWorkflowInstance(instance);
        }
    }

    private void completeWorkflowInstance(WorkflowInstance instance) {
        instance.setEndTime(LocalDateTime.now());
        if (instance.getStartTime() != null) {
            long ms = Duration.between(instance.getStartTime(), instance.getEndTime()).toMillis();
            instance.setDurationMs(ms);
        }
        if (instance.getFailedTasks() != null && instance.getFailedTasks() > 0) {
            instance.setStatus(WorkflowInstanceStatus.PARTIAL_SUCCESS.getCode());
        } else {
            instance.setStatus(WorkflowInstanceStatus.SUCCESS.getCode());
        }
        workflowInstanceMapper.updateById(instance);
        log.info(
                "工作流实例执行完成 instanceId={} status={} durationMs={}",
                instance.getId(),
                instance.getStatus(),
                instance.getDurationMs());
    }

    private static boolean isWorkflowTaskTerminal(WorkflowTaskInstance task) {
        try {
            return TaskInstanceStatus.fromCode(task.getStatus()).isTerminal();
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private TaskSubmitRequest buildTaskSubmitRequest(TaskInstance taskInstance) {
        return TaskSubmitRequest.builder()
                .taskId(taskInstance.getTaskId())
                .priority(taskInstance.getPriority())
                .tenantId(taskInstance.getTenantId())
                .submitUserId(taskInstance.getSubmitUserId())
                .workflowInstanceId(taskInstance.getWorkflowInstanceId())
                .executorConfig(taskInstance.getExecutorConfig())
                .resourceRequirement(taskInstance.getResourceRequirement())
                .parameters(parseParametersMap(taskInstance.getParameters()))
                .build();
    }

    private java.util.Map<String, Object> parseParametersMap(String parametersJson) {
        if (parametersJson == null || parametersJson.isBlank()) {
            return null;
        }
        try {
            return new ObjectMapper().readValue(parametersJson, new com.fasterxml.jackson.core.type.TypeReference<>() {});
        } catch (Exception e) {
            log.warn("工作流任务参数解析失败 json={}", parametersJson, e);
            return null;
        }
    }

    /**
     * 兼容库中枚举名（如 RUNNING）、code（如 running）或历史混合大小写的状态字段。
     */
    private static WorkflowInstanceStatus parseWorkflowInstanceStatus(String raw) {
        if (raw == null || raw.isBlank()) {
            throw new IllegalArgumentException("工作流实例状态为空");
        }
        String s = raw.trim();
        for (WorkflowInstanceStatus st : WorkflowInstanceStatus.values()) {
            if (st.name().equalsIgnoreCase(s) || st.getCode().equalsIgnoreCase(s)) {
                return st;
            }
        }
        throw new IllegalArgumentException("Unsupported workflow instance status: " + raw);
    }
}

@Service
@Slf4j
public class WorkflowServiceImpl implements WorkflowService {

    private static final int NOT_DELETED = 0;

    @Autowired
    private WorkflowMapper workflowMapper;
    
    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private TaskMapper taskMapper;

    @Autowired
    private ProjectMapper projectMapper;

    /**
     * 执行计划缓存失效（与 {@link WorkflowExecutionService} 解耦；{@code @Lazy} 避免与解析 DAG 的循环依赖）。
     */
    @Autowired
    @Lazy
    private WorkflowExecutionService workflowExecutionService;

    @Autowired
    private WorkflowConditionSyntaxValidator workflowConditionSyntaxValidator;

    /**
     * 验证项目是否属于指定租户
     * @return 如果项目存在且属于租户则返回Project对象，否则返回null
     */
    private Project validateProjectBelongsToTenant(Long projectId, Long tenantId) {
        return projectMapper.selectOne(
                new LambdaQueryWrapper<Project>()
                        .eq(Project::getId, projectId)
                        .eq(Project::getTenantId, tenantId)
                        .eq(Project::getDeleted, NOT_DELETED));
    }

    // ==================== 辅助方法：更新操作的字段处理 =====================
    /**
     * 验证并更新工作流编码（需要检查重复性）
     */
    private void updateWorkflowCode(Workflow workflow, String newCode) {
        if (newCode == null) {
            return;  // 请求中没有工作流编码更新
        }
        if (!StringUtils.hasText(newCode)) {
            throw new IllegalArgumentException("工作流编码不能为空");
        }
        String code = newCode.trim();
        if (!code.equals(workflow.getWorkflowCode())) {
            Long dup = workflowMapper.selectCount(
                    new LambdaQueryWrapper<Workflow>()
                            .eq(Workflow::getProjectId, workflow.getProjectId())
                            .eq(Workflow::getWorkflowCode, code)
                            .ne(Workflow::getId, workflow.getId()));
            if (dup != null && dup > 0) {
                throw new IllegalArgumentException("工作流编码已存在");
            }
            workflow.setWorkflowCode(code);
        }
    }

    /**
     * 验证并更新DAG定义
     */
    private void updateDagJson(Workflow workflow, String newDagJson) {
        if (newDagJson == null) {
            return;  // 请求中没有DAG定义更新
        }
        if (!StringUtils.hasText(newDagJson)) {
            throw new IllegalArgumentException("DAG定义不能为空");
        }
        String dagJson = newDagJson.trim();
        WorkflowDAG dag = parseDAG(dagJson);
        validateDAG(dag);
        workflow.setDagJson(dagJson);
    }

    /**
     * 更新简单的字符串字段（带自动trim）
     */
    private void updateSimpleStringField(String newValue, java.util.function.Consumer<String> setter) {
        if (newValue != null) {
            if (StringUtils.hasText(newValue)) {
                setter.accept(newValue.trim());
            } else {
                setter.accept(null);
            }
        }
    }
    
    @Override
    @Transactional
    @RequireWorkflowPermission(
        roles = {"OWNER", "ADMIN", "MEMBER"},
        message = "当前角色无创建工作流权限",
        validateProject = true
    )
    public Long createWorkflow(WorkflowCreateRequest request) {
        log.info("创建工作流 workflowName={}", request.getWorkflowName());

        Long userId = WorkflowSecurityContextHolder.require().principal().userId();

        WorkflowDAG dag = parseDAG(request.getDagJson());
        validateDAG(dag);

        Workflow workflow = new Workflow();
        BeanUtils.copyProperties(request, workflow);

        String workflowCode;
        if (StringUtils.hasText(request.getWorkflowCode())) {
            workflowCode = request.getWorkflowCode().trim();
            Long dup = workflowMapper.selectCount(
                    new LambdaQueryWrapper<Workflow>()
                            .eq(Workflow::getProjectId, request.getProjectId())
                            .eq(Workflow::getWorkflowCode, workflowCode));
            if (dup != null && dup > 0) {
                throw new IllegalArgumentException("工作流编码已存在");
            }
        } else {
            workflowCode = "wf_" + UUID.randomUUID().toString().replace("-", "");
        }
        workflow.setWorkflowCode(workflowCode);

        if (!StringUtils.hasText(workflow.getScheduleType())) {
            workflow.setScheduleType("MANUAL");
        } else {
            workflow.setScheduleType(workflow.getScheduleType().trim());
        }
        if (StringUtils.hasText(workflow.getCronExpression())) {
            workflow.setCronExpression(workflow.getCronExpression().trim());
        } else {
            workflow.setCronExpression(null);
        }
        if (workflow.getAlertOnFailure() == null) {
            workflow.setAlertOnFailure(0);
        }
        if (workflow.getTimeoutSeconds() == null) {
            workflow.setTimeoutSeconds(7200);
        }
        workflow.setStatus(1);
        workflow.setVersion(0);
        workflow.setCreatorUserId(userId);

        int inserted = workflowMapper.insert(workflow);
        if (inserted != 1 || workflow.getId() == null) {
            throw new IllegalStateException("创建工作流失败");
        }
        log.info("创建工作流成功 id={}", workflow.getId());
        return workflow.getId();
    }
    
    @Override
    @Transactional
    @RequireWorkflowPermission(
        roles = {"OWNER", "ADMIN", "MEMBER"},
        message = "当前角色无更新工作流权限"
    )
    public void updateWorkflow(Long id, WorkflowUpdateRequest request) {
        log.info("更新工作流 id={}", id);
        Workflow workflow = requireOwnedWorkflow(id);

        // 使用辅助方法简化字段更新逻辑
        updateSimpleStringField(request.getWorkflowName(), workflow::setWorkflowName);
        updateWorkflowCode(workflow, request.getWorkflowCode());
        updateSimpleStringField(request.getDescription(), workflow::setDescription);
        updateDagJson(workflow, request.getDagJson());
        
        // 处理 scheduleType：如果为空则设置为 MANUAL，否则 trim
        if (request.getScheduleType() != null) {
            workflow.setScheduleType(StringUtils.hasText(request.getScheduleType()) 
                ? request.getScheduleType().trim() : "MANUAL");
        }
        
        // 处理 cronExpression：如果为空则设置为 null，否则 trim
        if (request.getCronExpression() != null) {
            workflow.setCronExpression(StringUtils.hasText(request.getCronExpression())
                ? request.getCronExpression().trim() : null);
        }
        
        // 处理其他简单字段
        if (request.getTimeoutSeconds() != null) {
            workflow.setTimeoutSeconds(request.getTimeoutSeconds());
        }
        if (request.getAlertOnFailure() != null) {
            workflow.setAlertOnFailure(request.getAlertOnFailure());
        }
        
        // 状态有效性检查
        if (request.getStatus() != null) {
            if (request.getStatus() != 0 && request.getStatus() != 1) {
                throw new IllegalArgumentException("状态值无效");
            }
            workflow.setStatus(request.getStatus());
        }

        int updated = workflowMapper.updateById(workflow);
        if (updated != 1) {
            throw new IllegalStateException("更新工作流失败，可能版本冲突或记录不存在");
        }
        workflowExecutionService.invalidatePlanCache(id);
    }
    
    @Override
    @Transactional
    @RequireWorkflowPermission(
        roles = {"OWNER", "ADMIN"},
        message = "当前角色无删除工作流权限"
    )
    public void deleteWorkflow(Long id) {
        log.info("删除工作流 id={}", id);
        Workflow workflow = requireOwnedWorkflow(id);
        int deleted = workflowMapper.deleteById(workflow.getId());
        if (deleted != 1) {
            throw new IllegalStateException("删除工作流失败");
        }
    }
    
    @Override
    @RequireWorkflowPermission(
        roles = {"OWNER", "ADMIN", "MEMBER", "GUEST"},
        message = "当前角色无查看工作流权限"
    )
    public Workflow getById(Long id) {
        Long tenantId = WorkflowSecurityContextHolder.require().principal().tenantId();

        Workflow workflow = workflowMapper.selectById(id);
        if (workflow == null) {
            return null;
        }
        
        Project project = validateProjectBelongsToTenant(workflow.getProjectId(), tenantId);
        if (project == null) {
            return null;
        }
        return workflow;
    }

    /**
     * 加载工作流并校验：记录存在且所属项目在当前租户下。
     */
    private Workflow requireOwnedWorkflow(Long workflowId) {
        Long tenantId = WorkflowSecurityContextHolder.require().principal().tenantId();

        Workflow workflow = workflowMapper.selectById(workflowId);
        if (workflow == null) {
            throw new IllegalArgumentException("工作流不存在");
        }
        
        Project project = validateProjectBelongsToTenant(workflow.getProjectId(), tenantId);
        if (project == null) {
            throw new IllegalArgumentException("工作流不存在");
        }
        return workflow;
    }
    
    @Override
    public WorkflowVO toVO(Workflow workflow) {
        if (workflow == null) {
            return null;
        }
        WorkflowVO vo = new WorkflowVO();
        BeanUtils.copyProperties(workflow, vo);

        String dagJson = workflow.getDagJson();
        if (dagJson != null && !dagJson.isBlank()) {
            try {
                WorkflowDAG dag = objectMapper.readValue(dagJson, WorkflowDAG.class);
                vo.setDag(dag);
                vo.setTaskCount(dag.getTasks() != null ? dag.getTasks().size() : 0);
            } catch (Exception e) {
                log.warn("工作流 dagJson 解析失败 id={}", workflow.getId(), e);
                vo.setDag(null);
                vo.setTaskCount(0);
            }
        } else {
            vo.setDag(null);
            vo.setTaskCount(0);
        }
        return vo;
    }
    
    @Override
    @RequireWorkflowPermission(
        roles = {"OWNER", "ADMIN", "MEMBER", "GUEST"},
        message = "当前角色无查看工作流列表权限"
    )
    public List<WorkflowVO> listWorkflows(Long projectId, Integer status) {
        log.info("查询工作流列表 projectId={} status={}", projectId, status);

//        LambdaQueryWrapper<Workflow> wrapper = new LambdaQueryWrapper<Workflow>()
//                .eq(Workflow::getProjectId, projectId)
//                .eq(status != null, Workflow::getStatus, status)
//                .orderByDesc(Workflow::getCreatedAt);
//        List<Workflow> workflows = workflowMapper.selectList(wrapper);
        List<Workflow> workflows = workflowMapper.selectByProjectIdAndStatus(projectId,status);
        return workflows.stream().map(this::toVO).collect(Collectors.toList());
    }

    // ==================== DAG解析与验证 =====================
    @Override
    public WorkflowDAG parseDAG(String dagJson) {
        try {
            // 解析JSON为WorkflowDAG对象
            WorkflowDAG dag = objectMapper.readValue(dagJson, WorkflowDAG.class);
            // 校验必填字段
            if (dag.getTasks() == null || dag.getTasks().isEmpty()) {
                throw new IllegalArgumentException("工作流至少包含一个任务");
            }
            return dag;
        } catch (Exception e) {
            log.error("解析DAG JSON失败", e);
            throw new IllegalArgumentException("DAG JSON格式错误: " + e.getMessage());
        }
    }
    
    @Override
    public void validateDAG(WorkflowDAG dag) {
        // 1. 验证节点名称唯一性
        Set<String> nodeNames = new HashSet<>();
        for (WorkflowTask task : dag.getTasks()){
            if (!nodeNames.add(task.getNodeName())){
                throw new IllegalArgumentException("节点名称重复: " + task.getNodeName());
            }
        }
        
        // 2. 验证引用的 Task 实体存在（查询 task 表）
        Set<Long> taskIds = dag.getTasks().stream()
                .map(WorkflowTask::getTaskId)
                        .collect(Collectors.toSet());
        List<Task> tasks = taskMapper.selectByIds(taskIds);
        if (tasks.size() != taskIds.size()){
            throw new IllegalArgumentException("引用的任务不存在");
        }

        // 3. 验证依赖引用的节点存在
        Set<String> nodeNameSet = dag.getTasks().stream()
                .map(WorkflowTask::getNodeName)
                        .collect(Collectors.toSet());
        List<WorkflowDependency> dependencies =
                dag.getDependencies() != null ? dag.getDependencies() : Collections.emptyList();
        for (WorkflowDependency dep : dependencies) {
            if (!nodeNameSet.contains(dep.getFrom())) {
                throw new IllegalArgumentException("依赖的上游节点不存在: " + dep.getFrom());
            }
            if (!nodeNameSet.contains(dep.getTo())) {
                throw new IllegalArgumentException("依赖的下游节点不存在: " + dep.getTo());
            }
        }

        workflowConditionSyntaxValidator.validateAll(
                dependencies.stream().map(WorkflowDependency::getCondition).collect(Collectors.toList()));

        // 4. 调用detectCycle()检测循环依赖
        detectCycle(dag);

        log.info("DAG验证通过 taskCount={} dependencyCount={}", 
                dag.getTasks() != null ? dag.getTasks().size() : 0,
                dependencies.size());
    }
    
    /**
     * 检测循环依赖（DFS + 三色标记）
     * 
     * @param dag DAG对象
     * @throws IllegalArgumentException 如果存在循环依赖
     */
    private void detectCycle(WorkflowDAG dag) {
        // 1. 构建邻接表（使用 nodeName 作为 key）
        Map<String, List<String>> graph = new HashMap<>();
        for (WorkflowTask task : dag.getTasks()){
            graph.put(task.getNodeName(), new ArrayList<>());
        }
        List<WorkflowDependency> dependencies =
                dag.getDependencies() != null ? dag.getDependencies() : Collections.emptyList();
        for (WorkflowDependency dep : dependencies) {
            graph.get(dep.getFrom()).add(dep.getTo());
        }

        // 2. 初始化三色标记（0=白色，1=灰色，2=黑色）
        Map<String, Integer> color = new HashMap<>();
        for (String nodeName : graph.keySet()) {
            color.put(nodeName, 0);
        }
        
        // 3. DFS检测环
        for (String nodeName : graph.keySet()){
            if (color.get(nodeName) == 0){
                if (dfsHasCycle(nodeName, graph, color, new ArrayList<>())){
                    throw new IllegalArgumentException("检测到循环依赖，DAG无效");
                }
            }
        }
        log.info("循环依赖检测通过");
    }
    
    /**
     * DFS递归检测环
     * 
     * @param node 当前节点
     * @param graph 邻接表
     * @param color 节点颜色
     * @param path 访问路径（用于记录环）
     * @return 是否存在环
     */
    private boolean dfsHasCycle(
            String node,
            Map<String, List<String>> graph,
            Map<String, Integer> color,
            List<String> path) {
        
        // DFS环检测算法
        // 1. 标记当前节点为灰色
        color.put(node, 1);
        path.add(node);
        
        // 2. 访问所有邻居
        for (String neighbor : graph.get(node)) {
            int neighborColor = color.get(neighbor);
            // 3. 如果邻居是灰色，说明存在环
            if(neighborColor == 1){
                path.add(neighbor);
                log.error("检测到循环依赖: {}", String.join(" → ", path));
                return true;
            }
            // 4. 如果邻居是白色，递归访问
            if(neighborColor == 0){
                if(dfsHasCycle(neighbor, graph, color, path)){
                    return true;
                }
            }
        }
        // 5. 标记当前节点为黑色
        color.put(node, 2);
        path.removeLast();
        
        return false;
    }
}

@Component
@Slf4j
@RequiredArgsConstructor
public class TaskCompletionStreamListener implements StreamListener<String, MapRecord<String, String, String>> {

    private final TaskCompletionStreamHandler handler;
    private final StringRedisTemplate stringRedisTemplate;

    @Override
    public void onMessage(MapRecord<String, String, String> message) {
        try {
            TaskCompletionEvent event = toEvent(message.getValue());
            handler.handle(event);
            stringRedisTemplate.opsForStream().acknowledge(
                    TaskCompletionStreamConstants.CONSUMER_GROUP, message);
            log.debug("消息已确认 recordId={} taskInstanceId={}",
                    message.getId(), event.getTaskInstanceId());
        } catch (Exception e) {
            log.error("处理任务完成消息失败 recordId={} body={}", message.getId(), message.getValue(), e);
        }
    }

    private static TaskCompletionEvent toEvent(Map<String, String> data) {
        String taskInstanceIdStr = data.get("taskInstanceId");
        if (taskInstanceIdStr == null || taskInstanceIdStr.isBlank()) {
            throw new IllegalArgumentException("taskInstanceId is required in event data");
        }

        String workflowInstanceIdStr = data.get("workflowInstanceId");
        String exitCodeStr = data.get("exitCode");
        String durationMsStr = data.get("durationMs");

        return TaskCompletionEvent.builder()
                .taskInstanceId(Long.parseLong(taskInstanceIdStr))
                .workflowInstanceId(workflowInstanceIdStr != null && !workflowInstanceIdStr.isBlank()
                        ? Long.parseLong(workflowInstanceIdStr) : null)
                .status(data.get("status"))
                .exitCode(exitCodeStr != null && !exitCodeStr.isBlank() ? Integer.parseInt(exitCodeStr) : null)
                .errorMessage(data.get("errorMessage"))
                .durationMs(durationMsStr != null && !durationMsStr.isBlank() ? Long.parseLong(durationMsStr) : null)
                .timestamp(LocalDateTime.now())
                .build();
    }
}

public final class WorkflowSecurityContextHolder {

