        CONTEXT.set(context);
    }

    public static TenantAccessGuard.AccessContext require() {
        TenantAccessGuard.AccessContext ctx = CONTEXT.get();
        if (ctx == null) {
            throw new IllegalStateException("缺少工作流安全上下文，请确认方法已标注 @RequireWorkflowPermission");
        }
        return ctx;
    }

