@Component
@RequiredArgsConstructor
public class DockerTaskTypeExecutor implements WorkerTaskTypeExecutor {

    private final ProcessExecutionHelper processExecutionHelper;
    private final ExecutorConfigSupport configSupport;

    @Override
    public boolean supports(String taskType) {
        return taskType != null && "DOCKER".equalsIgnoreCase(taskType.trim());
    }

    @Override
    public ExecutionResult execute(LocalRunSpec runSpec) throws Exception {
        JsonNode root = configSupport.parse(runSpec.getExecutorConfig());
        String image = configSupport.readText(root, "image");
        if (!StringUtils.hasText(image)) {
            return ExecutionResult.configurationError("DOCKER 任务缺少 image");
        }
        Map<String, Object> params = runSpec.getParameters() != null ? runSpec.getParameters() : Map.of();
        image = ParameterTemplateResolver.resolve(image, params);

        List<String> dockerCmd = new ArrayList<>();
        dockerCmd.add("docker");
        dockerCmd.add("run");
        dockerCmd.add("--rm");
        dockerCmd.add("-w");
        dockerCmd.add("/work");
        dockerCmd.add("-v");
        dockerCmd.add(runSpec.getWorkDirectory().toAbsolutePath() + ":/work");

        for (Map.Entry<String, String> env : configSupport.readStringMap(root, "env").entrySet()) {
            dockerCmd.add("-e");
            dockerCmd.add(env.getKey() + "=" + ParameterTemplateResolver.resolve(env.getValue(), params));
        }

        dockerCmd.add(image);
        List<String> containerCommand = configSupport.readStringList(root, "command");
        if (containerCommand.isEmpty() && StringUtils.hasText(runSpec.getCommand())) {
            containerCommand = List.of(runSpec.getCommand());
        }
        for (String part : containerCommand) {
            dockerCmd.add(ParameterTemplateResolver.resolve(part, params));
        }

        return processExecutionHelper.execute(
                runSpec.getTaskInstanceId(),
                runSpec.getWorkDirectory(),
                runSpec.getTimeoutSeconds(),
                new ProcessBuilder(dockerCmd));
    }
}

@Value
@Builder
public class ExecutionResult {

    boolean success;
    int exitCode;
    String stdout;
    String stderr;
    String errorMessage;
    boolean timedOut;

    public static ExecutionResult success(int exitCode, String stdout, String stderr) {
        return ExecutionResult.builder()
                .success(exitCode == 0)
                .exitCode(exitCode)
                .stdout(stdout)
                .stderr(stderr)
                .build();
    }

    public static ExecutionResult failure(int exitCode, String stdout, String stderr, String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(exitCode)
                .stdout(stdout)
                .stderr(stderr)
                .errorMessage(errorMessage)
                .build();
    }

    public static ExecutionResult timedOut(String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(-1)
                .timedOut(true)
                .errorMessage(errorMessage)
                .build();
    }

    public static ExecutionResult configurationError(String errorMessage) {
        return ExecutionResult.builder()
                .success(false)
                .exitCode(-1)
                .errorMessage(errorMessage)
                .build();
    }
}

@Component
public class ExecutorConfigSupport {

    private final ObjectMapper objectMapper;

    public ExecutorConfigSupport(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public JsonNode parse(String json) {
        if (!StringUtils.hasText(json)) {
            return null;
        }
        try {
            return objectMapper.readTree(json);
        } catch (Exception e) {
            return null;
        }
    }

    public String readText(JsonNode root, String field) {
        if (root == null || !root.hasNonNull(field)) {
            return null;
        }
        return root.get(field).asText();
    }

    public List<String> readStringList(JsonNode root, String field) {
        if (root == null || !root.has(field) || !root.get(field).isArray()) {
            return List.of();
        }
        List<String> list = new ArrayList<>();
        for (JsonNode node : root.get(field)) {
            list.add(node.asText());
        }
        return list;
    }

    public Map<String, String> readStringMap(JsonNode root, String field) {
        if (root == null || !root.has(field) || !root.get(field).isObject()) {
            return Collections.emptyMap();
        }
        Map<String, String> map = new LinkedHashMap<>();
        JsonNode objectNode = root.get(field);
        objectNode.fieldNames().forEachRemaining(name -> map.put(name, objectNode.get(name).asText()));
        return map;
    }
}

