@Component
@RequiredArgsConstructor
public class ProcessExecutionHelper {

    private final WorkerProperties properties;
    private final RunningTaskRegistry runningTaskRegistry;

    public ExecutionResult execute(
            Long taskInstanceId, Path workDirectory, Integer timeoutSeconds, ProcessBuilder processBuilder)
            throws Exception {
        Files.createDirectories(workDirectory);
        processBuilder.directory(workDirectory.toFile());
        processBuilder.redirectErrorStream(false);

        Process process = processBuilder.start();
        ProcessRunningTaskHandle handle = new ProcessRunningTaskHandle(taskInstanceId, process);
        if (!runningTaskRegistry.tryRegister(taskInstanceId, handle)) {
            process.destroyForcibly();
            process.waitFor(5, TimeUnit.SECONDS);
            return ExecutionResult.failure(
                    -1, null, null, "duplicate execution rejected: taskInstanceId already running");
        }

        try {
            long waitSeconds = timeoutSeconds != null && timeoutSeconds > 0 ? timeoutSeconds : Long.MAX_VALUE;
            StringBuilder stdout = new StringBuilder();
            StringBuilder stderr = new StringBuilder();
            Charset charset = Charset.defaultCharset();

            Thread outThread = readStream(process.getInputStream(), stdout, charset);
            Thread errThread = readStream(process.getErrorStream(), stderr, charset);
            outThread.start();
            errThread.start();

            boolean finished;
            if (waitSeconds == Long.MAX_VALUE) {
                process.waitFor();
                finished = true;
            } else {
                finished = process.waitFor(waitSeconds, TimeUnit.SECONDS);
            }

            outThread.join(5_000);
            errThread.join(5_000);

            String out = truncate(stdout.toString());
            String err = truncate(stderr.toString());

            if (!finished) {
                process.destroyForcibly();
                process.waitFor(5, TimeUnit.SECONDS);
                return ExecutionResult.timedOut("任务执行超时（超过 " + waitSeconds + " 秒）");
            }

            int exitCode = process.exitValue();
            if (exitCode == 0) {
                return ExecutionResult.success(exitCode, out, err);
            }
            String message = err != null && !err.isBlank() ? err : ("进程退出码 " + exitCode);
            return ExecutionResult.failure(exitCode, out, err, truncate(message));
        } finally {
            runningTaskRegistry.unregister(taskInstanceId);
        }
    }

    private Thread readStream(java.io.InputStream stream, StringBuilder target, Charset charset) {
        Thread thread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, charset))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    if (target.length() < properties.getExecutor().getOutputMaxChars()) {
                        if (!target.isEmpty()) {
                            target.append(System.lineSeparator());
                        }
                        target.append(line);
                    }
                }
            } catch (Exception ignored) {
                // ignore
            }
        }, "worker-process-stream");
        thread.setDaemon(true);
        return thread;
    }

    private String truncate(String text) {
        if (text == null) {
            return null;
        }
        int max = properties.getExecutor().getOutputMaxChars();
        return text.length() <= max ? text : text.substring(0, max) + "...(truncated)";
    }
}

@Slf4j
@RequiredArgsConstructor
public class ProcessRunningTaskHandle implements RunningTaskHandle {

    private final Long taskInstanceId;
    private final Process process;

    @Override
    public void cancelForcibly() {
        if (process == null || !process.isAlive()) {
            return;
        }
        log.info("Worker 终止任务进程 taskInstanceId={}", taskInstanceId);
        process.destroyForcibly();
        try {
            process.waitFor(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

public interface RunningTaskHandle {

    void cancelForcibly();
}

@Component
public class RunningTaskRegistry {

    private final ConcurrentHashMap<Long, RunningTaskHandle> handles = new ConcurrentHashMap<>();

    /**
     * @return true 表示注册成功；false 表示已有同 ID 任务在跑（二次防御）
     */
    public boolean tryRegister(Long taskInstanceId, RunningTaskHandle handle) {
        if (taskInstanceId == null || handle == null) {
            return false;
        }
        return handles.putIfAbsent(taskInstanceId, handle) == null;
    }

    public void register(Long taskInstanceId, RunningTaskHandle handle) {
        tryRegister(taskInstanceId, handle);
    }

    public void unregister(Long taskInstanceId) {
        if (taskInstanceId != null) {
            handles.remove(taskInstanceId);
        }
    }

    public boolean cancel(Long taskInstanceId) {
        RunningTaskHandle handle = handles.remove(taskInstanceId);
        if (handle == null) {
            return false;
        }
        handle.cancelForcibly();
        return true;
    }
}

@Component
public class WorkerRunAcceptanceRegistry {

    private final ConcurrentHashMap<Long, Boolean> inFlight = new ConcurrentHashMap<>();

    /**
     * @return true 表示首次接受；false 表示该任务已在执行或排队中
     */
    public boolean tryAccept(long taskInstanceId) {
        return inFlight.putIfAbsent(taskInstanceId, Boolean.TRUE) == null;
    }

    public boolean isInFlight(long taskInstanceId) {
        return inFlight.containsKey(taskInstanceId);
    }

    public void release(long taskInstanceId) {
        inFlight.remove(taskInstanceId);
    }
}

public class WorkerTokenFilter extends OncePerRequestFilter {

    public static final String WORKER_TOKEN_HEADER = "X-Worker-Token";

    private final WorkerProperties properties;

    public WorkerTokenFilter(WorkerProperties properties) {
        this.properties = properties;
    }

    @Override
    protected void doFilterInternal(
            HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {

        String configured = properties.getApi().getToken();
        if (!StringUtils.hasText(configured)) {
            filterChain.doFilter(request, response);
            return;
        }

        String token = request.getHeader(WORKER_TOKEN_HEADER);
        if (!configured.equals(token)) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
            response.setCharacterEncoding(StandardCharsets.UTF_8.name());
            response.getWriter().write("{\"success\":false,\"message\":\"Worker token invalid\"}");
            return;
        }

        UsernamePasswordAuthenticationToken authentication =
                new UsernamePasswordAuthenticationToken(
                        "worker", null, List.of(new SimpleGrantedAuthority("ROLE_WORKER")));
        SecurityContextHolder.getContext().setAuthentication(authentication);
        filterChain.doFilter(request, response);
    }
}

@Slf4j
@Component
public class SchedulerCallbackClient {

    public static final String INTERNAL_TOKEN_HEADER = "X-Internal-Token";

    private static final int MAX_RETRY = 3;
    private static final long INITIAL_DELAY_MS = 2_000;

    private final RestClient restClient = RestClient.create();

    // -------------------------------------------------------------------------
    // 任务完成回调（带重试）
    // -------------------------------------------------------------------------

    public void report(WorkerRunCallback callback, ExecutionResult result) {
        if (callback == null || !StringUtils.hasText(callback.getStatusTransitionUrl())) {
            log.error("缺少回调地址，无法上报任务状态");
            return;
        }
        TaskStatusTransitionBody body = buildBody(result);
        postWithRetry(callback.getStatusTransitionUrl(), callback.getInternalToken(), body, "状态回调");
    }

    // -------------------------------------------------------------------------
    // 任务级心跳（单次，失败仅打 warn）
    // -------------------------------------------------------------------------

    public void heartbeat(WorkerRunCallback callback, Long taskInstanceId) {
        if (callback == null || !StringUtils.hasText(callback.getHeartbeatUrl())) {
            return;
        }
        try {
            buildSpec(callback.getHeartbeatUrl(), callback.getInternalToken(), null)
                    .retrieve().toBodilessEntity();
            log.trace("任务心跳已上报 taskInstanceId={}", taskInstanceId);
        } catch (RestClientException e) {
            log.warn("任务心跳上报失败 taskInstanceId={}", taskInstanceId, e);
        }
    }

    // -------------------------------------------------------------------------
    // 内部工具
    // -------------------------------------------------------------------------

    private void postWithRetry(String url, String token, Object body, String label) {
        long delayMs = INITIAL_DELAY_MS;
        for (int attempt = 1; attempt <= MAX_RETRY; attempt++) {
            try {
                buildSpec(url, token, body).retrieve().toBodilessEntity();
                log.info("{}成功（第 {} 次）", label, attempt);
                return;
            } catch (RestClientException e) {
                if (attempt == MAX_RETRY) {
                    log.error("{}最终失败，已重试 {} 次 url={}", label, MAX_RETRY, url, e);
                } else {
                    log.warn("{}失败，{}ms 后重试（{}/{}）url={}", label, delayMs, attempt, MAX_RETRY, url);
                    sleepQuietly(delayMs);
                    delayMs *= 2;
                }
            }
        }
    }

    private RestClient.RequestBodySpec buildSpec(String url, String token, Object body) {
        var spec = restClient.post().uri(url);
        if (StringUtils.hasText(token)) {
            spec = spec.header(INTERNAL_TOKEN_HEADER, token);
        }
        if (body != null) {
            return spec.contentType(MediaType.APPLICATION_JSON).body(body);
        }
        return spec;
    }

    private static void sleepQuietly(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private TaskStatusTransitionBody buildBody(ExecutionResult result) {
        if (result.isTimedOut()) {
            return TaskStatusTransitionBody.builder()
                    .fromStatus("RUNNING").toStatus("TIMEOUT")
                    .triggerSource("WORKER").reason("执行超时")
                    .exitCode(-1).errorMessage(result.getErrorMessage())
                    .build();
        }
        if (result.isSuccess()) {
            return TaskStatusTransitionBody.builder()
                    .fromStatus("RUNNING").toStatus("SUCCESS")
                    .triggerSource("WORKER").reason("执行成功")
                    .exitCode(result.getExitCode())
                    .build();
        }
        return TaskStatusTransitionBody.builder()
                .fromStatus("RUNNING").toStatus("FAILED")
                .triggerSource("WORKER").reason("执行失败")
                .exitCode(result.getExitCode()).errorMessage(result.getErrorMessage())
                .build();
    }
}

@Slf4j
@Component
public class SchedulerNodeClient {

    private final WorkerProperties properties;
    private final RestClient restClient = RestClient.create();

    public SchedulerNodeClient(WorkerProperties properties) {
        this.properties = properties;
    }

    public void register() {
        String baseUrl = trimBaseUrl(properties.getScheduler().getBaseUrl());
        Map<String, Object> body = buildNodePayload();
        try {
            restClient.post()
                    .uri(baseUrl + "/api/resource/register")
                    .body(body)
                    .retrieve()
                    .toBodilessEntity();
            log.info("已向调度中心注册 Worker 节点 host={} port={}", body.get("nodeHost"), body.get("nodePort"));
        } catch (Exception e) {
            log.error("Worker 节点注册失败", e);
        }
    }

    public void heartbeat() {
        sendHeartbeat("ONLINE");
    }

    /** 停机前通知调度中心将本节点标记为 OFFLINE，让调度器停止向本节点分发新任务。 */
    public void deregister() {
        sendHeartbeat("OFFLINE");
        log.info("已通知调度中心节点下线 host={} port={}",
                properties.getNode().getHost(), properties.getNode().getPort());
    }

    private void sendHeartbeat(String status) {
        String baseUrl = trimBaseUrl(properties.getScheduler().getBaseUrl());
        WorkerProperties.Node node = properties.getNode();
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("nodeHost", node.getHost());
        body.put("nodePort", node.getPort());
        body.put("availableCpu", node.getTotalCpu());
        body.put("availableMemoryMb", node.getTotalMemoryMb());
        body.put("availableGpu", node.getTotalGpu());
        body.put("status", status);
        try {
            restClient.post()
                    .uri(baseUrl + "/api/resource/heartbeat")
                    .body(body)
                    .retrieve()
                    .toBodilessEntity();
            log.debug("Worker 心跳成功 status={}", status);
        } catch (Exception e) {
            log.warn("Worker 心跳失败 status={}", status, e);
        }
    }

    private Map<String, Object> buildNodePayload() {
        WorkerProperties.Node node = properties.getNode();
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("nodeName", node.getName());
        body.put("nodeHost", node.getHost());
        body.put("nodePort", node.getPort());
        body.put("nodeType", node.getType());
        body.put("totalCpu", node.getTotalCpu());
        body.put("totalMemoryMb", node.getTotalMemoryMb());
        body.put("totalGpu", node.getTotalGpu());
        if (StringUtils.hasText(node.getWorkerEndpoint())) {
            body.put("workerEndpoint", node.getWorkerEndpoint().trim());
        } else {
            body.put("workerEndpoint", "http://" + node.getHost() + ":" + node.getPort());
        }
        return body;
    }

    private static String trimBaseUrl(String baseUrl) {
        String url = StringUtils.hasText(baseUrl) ? baseUrl.trim() : "http://localhost:8080";
        while (url.endsWith("/")) {
            url = url.substring(0, url.length() - 1);
        }
        return url;
    }
}

@Slf4j
@Service
public class WorkerRunService {

    private final WorkerProperties properties;
    private final WorkerTaskTypeExecutorRegistry executorRegistry;
    private final SchedulerCallbackClient schedulerCallbackClient;
    private final RunningTaskRegistry runningTaskRegistry;
    private final WorkerRunAcceptanceRegistry acceptanceRegistry;
    private final Executor workerTaskExecutor;

    /** 单线程守护池，用于任务执行期间的心跳调度，不影响任务线程池资源。 */
    private final ScheduledExecutorService heartbeatExecutor = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread t = new Thread(r, "worker-task-heartbeat");
        t.setDaemon(true);
        return t;
    });

    public WorkerRunService(
            WorkerProperties properties,
            WorkerTaskTypeExecutorRegistry executorRegistry,
            SchedulerCallbackClient schedulerCallbackClient,
            RunningTaskRegistry runningTaskRegistry,
            WorkerRunAcceptanceRegistry acceptanceRegistry,
            @Qualifier("workerTaskExecutor") Executor workerTaskExecutor) {
        this.properties = properties;
        this.executorRegistry = executorRegistry;
        this.schedulerCallbackClient = schedulerCallbackClient;
        this.runningTaskRegistry = runningTaskRegistry;
        this.acceptanceRegistry = acceptanceRegistry;
        this.workerTaskExecutor = workerTaskExecutor;
    }

    /**
     * 幂等接受任务：同一 {@code taskInstanceId} 在飞行中重复 POST 不再提交线程池。
     * HTTP 仍返回 202，便于 Scheduler 侧将重复下发视为成功接受（WorkerHttpClient 只认 202）。
     */
    public WorkerSubmitOutcome submitAsync(WorkerRunRequest request) {
        long taskInstanceId = request.getTaskInstanceId();
        if (!acceptanceRegistry.tryAccept(taskInstanceId)) {
            log.info("忽略重复下发 taskInstanceId={}（已在执行或排队）", taskInstanceId);
            return WorkerSubmitOutcome.ALREADY_ACCEPTED;
        }

        try {
            workerTaskExecutor.execute(() -> {
                try {
                    executeSync(request);
                } finally {
                    acceptanceRegistry.release(taskInstanceId);
                }
            });
            return WorkerSubmitOutcome.ACCEPTED;
        } catch (RejectedExecutionException e) {
            acceptanceRegistry.release(taskInstanceId);
            log.warn("Worker 线程池已满 taskInstanceId={}", taskInstanceId, e);
            schedulerCallbackClient.report(
                    request.getCallback(),
                    ExecutionResult.configurationError("Worker 线程池已满"));
            return WorkerSubmitOutcome.REJECTED_POOL_FULL;
        }
    }

    public boolean cancel(Long taskInstanceId) {
        return runningTaskRegistry.cancel(taskInstanceId);
    }

    private void executeSync(WorkerRunRequest request) {
        log.info("Worker 执行任务 taskInstanceId={} type={}", request.getTaskInstanceId(), request.getTaskType());
        ScheduledFuture<?> heartbeat = startHeartbeat(request);
        try {
            WorkerTaskTypeExecutor executor = executorRegistry.resolve(request.getTaskType()).orElse(null);
            if (executor == null) {
                schedulerCallbackClient.report(
                        request.getCallback(),
                        ExecutionResult.configurationError("不支持的任务类型: " + request.getTaskType()));
                return;
            }

            Path workDir =
                    Path.of(properties.getExecutor().getWorkDir(), String.valueOf(request.getTaskInstanceId()));

            LocalRunSpec spec = LocalRunSpec.builder()
                    .taskInstanceId(request.getTaskInstanceId())
                    .taskType(request.getTaskType())
                    .command(request.getCommand())
                    .executorConfig(request.getExecutorConfig())
                    .workDirectory(workDir)
                    .timeoutSeconds(request.getTimeoutSeconds())
                    .parameters(request.getParameters())
                    .build();

            ExecutionResult result = executor.execute(spec);
            schedulerCallbackClient.report(request.getCallback(), result);
        } catch (Exception e) {
            log.error("Worker 任务执行异常 taskInstanceId={}", request.getTaskInstanceId(), e);
            schedulerCallbackClient.report(
                    request.getCallback(), ExecutionResult.failure(-1, null, null, e.getMessage()));
        } finally {
            stopHeartbeat(heartbeat);
        }
    }

    private ScheduledFuture<?> startHeartbeat(WorkerRunRequest request) {
        WorkerRunCallback callback = request.getCallback();
        if (callback == null || !StringUtils.hasText(callback.getHeartbeatUrl())) {
            return null;
        }
        long intervalSeconds = Math.max(properties.getHeartbeatIntervalSeconds() / 2L, 10L);
        return heartbeatExecutor.scheduleWithFixedDelay(
                () -> schedulerCallbackClient.heartbeat(callback, request.getTaskInstanceId()),
                intervalSeconds, intervalSeconds, TimeUnit.SECONDS);
    }

    private static void stopHeartbeat(ScheduledFuture<?> future) {
        if (future != null) {
            future.cancel(false);
        }
    }
}

WorkerSubmitOutcome(String message) {
    this.message = message;
}

public String message() {
    return message;
}

class WorkerRunAcceptanceRegistryTest {

    @Test
    void tryAccept_isIdempotentUntilRelease() {
        WorkerRunAcceptanceRegistry registry = new WorkerRunAcceptanceRegistry();

        assertTrue(registry.tryAccept(100L));
        assertFalse(registry.tryAccept(100L));
        assertTrue(registry.isInFlight(100L));

        registry.release(100L);

        assertFalse(registry.isInFlight(100L));
        assertTrue(registry.tryAccept(100L));
    }
}
